  document.getElementById('fichaje-filter-empleado')?.addEventListener('change',()=>renderFichajeAdminTabla());
  document.getElementById('fichaje-filter-desde')?.addEventListener('change',()=>renderFichajeAdminTabla());
  document.getElementById('fichaje-filter-hasta')?.addEventListener('change',()=>renderFichajeAdminTabla());
  document.getElementById('mya-pipe-filter-tier')?.addEventListener('change',()=>renderMyAPipeline());
  document.getElementById('mya-pipe-filter-etapa')?.addEventListener('change',()=>renderMyAPipeline());
  document.getElementById('mya-pipe-filter-gestor')?.addEventListener('change',()=>renderMyAPipeline());
