function getCRMVisibles() {
  const todos = data.contactos || [];
  if (currentRole === 'admin') return todos;
  const emps = getUserEmpresas();
  return todos.filter(c => !c.empresa || emps.includes(c.empresa));
}

// Total real de comunidades captadas (cierres "Cliente Captado" del CRM),
// usado para vincular KRs de OKR al dato real en vez de introducirlo a mano.
function getComunidadesCaptadasReal() {
  return getCRMVisibles()
    .filter(c => c.etapa === 'Cliente Captado')
    .reduce((s, c) => s + (parseFloat(c.comunidadesCaptadas) || 0), 0);
}

// Valor "actual" de un KR: si está vinculado al CRM (fuente:'ccpp_real') se calcula
// en tiempo real; si no, es el valor manual guardado.
function getKRActual(kr) {
  return kr.fuente === 'ccpp_real' ? getComunidadesCaptadasReal() : (parseFloat(kr.actual) || 0);
}


