// Prescriptores de Servicios Profesionales: nombres de las gestorías dadas
// de alta en el submódulo "Prescriptores" (base de datos propia, no la de
// Visalia — esa es exclusiva de comunidades).
function crmspPrescriptorOptions() {
  return (data.prescriptoresSP||[]).map(p => p.nombre).filter(Boolean).sort();
}

function getCRMSPVisibles() { return data.contactosSP || []; }

// Importe "real" de un contacto: si ya está Cliente Captado, el importe
// cerrado (que puede diferir del ofertado si hubo negociación); si no,
// el importe de la propuesta. Esta es la cifra que debe usarse en TODOS
// los sumatorios, listados y OKRs — nunca el importe ofertado una vez que
// el contacto ya está cerrado.
function spImporteEfectivo(c) {
  if (c.etapa === 'Cliente Captado') return c.importeCerrado || c.importePropuesta || 0;
  return c.importePropuesta || 0;
}

