  ['crmsp-leads-filter-empresa','crmsp-leads-filter-estado','crmsp-leads-filter-prescriptor','crmsp-leads-filter-poblacion','crmsp-leads-filter-resp'].forEach(id => { const el = document.getElementById(id); if (el) el.value=''; });
