/* ═══════════════════════════════════════════════════
   DASHBOARD (Pipeline / Seguimiento)
   ═══════════════════════════════════════════════════ */
function renderCRMSPFiltrosDashboard() {
  renderCRMSPEtapaFiltroChecks('crmsp-dash-filter-etapa', crmspFiltroEtapasDash, 'crmspDashEtapaFiltroToggle');
  let contactos = getCRMSPVisibles();
  if (crmspFiltroEtapasDash.length) contactos = contactos.filter(c => crmspFiltroEtapasDash.includes(c.etapa));
  const fResp = document.getElementById('crmsp-dash-filter-resp')?.value || '';
  const fOrigen = document.getElementById('crmsp-dash-filter-origen')?.value || '';
  const fTienePrescriptor = document.getElementById('crmsp-dash-filter-tiene-prescriptor')?.value || '';
  const fPrescriptor = document.getElementById('crmsp-dash-filter-prescriptor')?.value || '';
  const fProb = document.getElementById('crmsp-dash-filter-probabilidad')?.value || '';
  if (fResp) contactos = contactos.filter(c => c.responsable === fResp);
  if (fOrigen) contactos = contactos.filter(c => c.origen === fOrigen);
  if (fTienePrescriptor === 'si') contactos = contactos.filter(c => !!c.prescriptor);
  else if (fTienePrescriptor === 'no') contactos = contactos.filter(c => !c.prescriptor);
  if (fPrescriptor) contactos = contactos.filter(c => _prescriptorCoincide(c.prescriptor, fPrescriptor));
  if (fProb) contactos = contactos.filter(c => c.probabilidad === fProb);
  renderCRMSPDashboard(contactos);
}

function renderCRMSPDashboard(contactos) {
  const el = document.getElementById('crmsp-dashboard');
  if (!el) return;
  contactos = contactos || getCRMSPVisibles();

  const activos = contactos.filter(c => !CRMSP_ETAPAS_CIERRE.includes(c.etapa));
  const captados = contactos.filter(c => c.etapa === 'Cliente Captado');
  const descartados = contactos.filter(c => c.etapa === 'Descartado');
  const valorPipeline = activos.reduce((s,c) => s + spImporteEfectivo(c), 0);
  const valorGanado = captados.reduce((s,c) => s + spImporteEfectivo(c), 0);

  const activosEtapasJS = "[" + CRMSP_ETAPAS.filter(e=>!CRMSP_ETAPAS_CIERRE.includes(e)).map(e=>`'${esc(e).replace(/'/g,"\\'")}'`).join(',') + "]";

  // Cierre de contactos: % captados vs % descartados sobre el total de
  // cerrados, y desglose de los descartados por motivo — mismo patrón que
  // el dashboard del CRM de comunidades.
  const cerrados = captados.length + descartados.length;
  const pctCaptados = cerrados > 0 ? Math.round(captados.length / cerrados * 100) : 0;
  const pctDescartados = cerrados > 0 ? 100 - pctCaptados : 0;
  const motivosBreakdown = CRMSP_MOTIVOS.map(m => {
    const n = descartados.filter(c => c.motivoDescarte === m).length;
    const pct = descartados.length > 0 ? Math.round(n / descartados.length * 100) : 0;
    return { motivo: m, n, pct };
  });
  const sinMotivo = descartados.filter(c => !c.motivoDescarte).length;

  const cierreHTML = cerrados === 0
    ? `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;color:var(--muted);font-size:12px;text-align:center;padding:20px 0;">
        <i class="ti ti-target-arrow" style="font-size:22px;margin-bottom:6px;"></i>
        Aún no hay propuestas cerradas<br>(Cliente Captado / Descartado)
      </div>`
    : `
      <div style="display:flex;height:22px;border-radius:6px;overflow:hidden;margin-bottom:8px;">
        <div style="width:${pctCaptados}%;background:#7FB89A;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#fff;">${pctCaptados > 12 ? pctCaptados+'%' : ''}</div>
        <div style="width:${pctDescartados}%;background:#D98C8C;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#fff;">${pctDescartados > 12 ? pctDescartados+'%' : ''}</div>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:14px;">
        <span style="color:#3E7259;font-weight:600;"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#7FB89A;margin-right:4px;"></span>Captados: ${pctCaptados}% (${captados.length})</span>
        <span style="color:#A15A56;font-weight:600;"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#D98C8C;margin-right:4px;"></span>Descartados: ${pctDescartados}% (${descartados.length})</span>
      </div>
      ${descartados.length > 0 ? `
      <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.04em;margin-bottom:8px;padding-top:8px;border-top:1px solid var(--border);">Motivo de descarte</div>
      ${motivosBreakdown.map(mb => `
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;">
          <span style="font-size:11px;width:64px;flex-shrink:0;color:var(--text);">${esc(mb.motivo)}</span>
          <div style="flex:1;height:10px;background:var(--border);border-radius:4px;overflow:hidden;">
            <div style="height:100%;width:${mb.pct}%;background:#F6E7E6;border-right:2px solid #A15A56;"></div>
          </div>
          <span style="font-size:11px;font-weight:700;color:#A15A56;width:52px;text-align:right;">${mb.n} · ${mb.pct}%</span>
        </div>`).join('')}
      ${sinMotivo > 0 ? `<div style="font-size:10px;color:var(--muted);margin-top:4px;">${sinMotivo} descartado(s) sin motivo indicado</div>` : ''}
      ` : ''}`;

  const valorDescartado = descartados.reduce((s,c) => s + spImporteEfectivo(c), 0);

  const kpis = `
    <div style="display:flex;gap:12px;margin-bottom:20px;flex-wrap:wrap;align-items:stretch;">
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;flex:2 1 460px;">
        <div class="kpi-card" style="border-top:3px solid var(--purple);cursor:pointer;" onclick="irADetalleCRMSPFiltrado()" title="Ver estas propuestas en Detalle">
          <div class="kpi-icon-row"><i class="ti ti-users" style="color:var(--purple)" aria-hidden="true"></i><div class="kpi-label">TOTAL CONTACTOS</div></div>
          <div class="kpi-val">${contactos.length}</div>
          <div class="kpi-sub">${activos.length} activos</div>
        </div>
        <div class="kpi-card" style="border-top:3px solid #F59E0B;cursor:pointer;" onclick="irADetalleCRMSPFiltrado(${activosEtapasJS})" title="Ver estas propuestas en Detalle">
          <div class="kpi-icon-row"><i class="ti ti-building" style="color:#F59E0B" aria-hidden="true"></i><div class="kpi-label">PROPUESTAS EN GESTIÓN</div></div>
          <div class="kpi-val">${activos.length}</div>
          <div class="kpi-sub">${fmtEUR(valorPipeline)} presupuestado</div>
        </div>
        <div class="kpi-card" style="border-top:3px solid #7FB89A;cursor:pointer;" onclick="irADetalleCRMSPFiltrado('Cliente Captado')" title="Ver estas propuestas en Detalle">
          <div class="kpi-icon-row"><i class="ti ti-circle-check" style="color:#7FB89A" aria-hidden="true"></i><div class="kpi-label">CLIENTE CAPTADO</div></div>
          <div class="kpi-val">${captados.length}</div>
          <div class="kpi-sub">${fmtEUR(valorGanado)} cerrado</div>
        </div>
        <div class="kpi-card" style="border-top:3px solid #D98C8C;cursor:pointer;" onclick="irADetalleCRMSPFiltrado('Descartado')" title="Ver estas propuestas en Detalle">
          <div class="kpi-icon-row"><i class="ti ti-circle-x" style="color:#D98C8C" aria-hidden="true"></i><div class="kpi-label">DESCARTADAS</div></div>
          <div class="kpi-val">${descartados.length}</div>
          <div class="kpi-sub">${fmtEUR(valorDescartado)} presupuestado</div>
        </div>
      </div>
      <div class="dash-card" style="flex:1 1 260px;margin:0;">
        <div class="dash-card-header">
          <i class="ti ti-target-arrow" aria-hidden="true"></i>
          <span>Cierre de Contactos</span>
        </div>
        <div style="margin-top:12px;">${cierreHTML}</div>
      </div>
    </div>`;

  // ── Detalle por servicio: importe en pipeline vs importe ya cerrado,
  //    y cuánto de eso se cede al prescriptor en cada situación. La cesión
  //    en pipeline se recalcula SIEMPRE en vivo (spImporteEfectivo ya se usa
  //    para el importe; aquí spComisionEfectiva hace lo mismo para la
  //    comisión), así que un cambio de % en la ficha del prescriptor se ve
  //    reflejado aquí al momento — la cesión de lo ya CERRADO sigue fija,
  //    porque es un importe ya pactado y cobrado. ──
  const porServicio = {};
  activos.forEach(c => {
    (c.serviciosOfertados||[]).forEach(s => {
      if (!porServicio[s.key]) porServicio[s.key] = { nombre: s.nombre, pipeline: 0, cerrado: 0, cesionPipeline: 0, cesionCerrado: 0 };
      porServicio[s.key].pipeline += Number(s.precio) || 0;
      porServicio[s.key].cesionPipeline += spComisionEfectiva(c, s);
    });
  });
  captados.forEach(c => {
    const lista = (c.preciosCerrados && c.preciosCerrados.length) ? c.preciosCerrados : (c.serviciosOfertados||[]);
    lista.forEach(s => {
      if (!porServicio[s.key]) porServicio[s.key] = { nombre: s.nombre, pipeline: 0, cerrado: 0, cesionPipeline: 0, cesionCerrado: 0 };
      porServicio[s.key].cerrado += Number(s.precio) || 0;
      porServicio[s.key].cesionCerrado += Number(s.comisionPrescriptor) || 0;
    });
  });
  const filasServicio = Object.values(porServicio)
    .map(s => ({ ...s,
      total: s.pipeline + s.cerrado,
      cesionTotal: s.cesionPipeline + s.cesionCerrado,
      netoPipeline: s.pipeline - s.cesionPipeline,
      netoCerrado: s.cerrado - s.cesionCerrado,
      netoNuestro: (s.pipeline + s.cerrado) - (s.cesionPipeline + s.cesionCerrado) }))
    .sort((a,b) => b.total - a.total);
  const totalesServicio = filasServicio.reduce((acc,s) => {
    acc.pipeline += s.pipeline; acc.cerrado += s.cerrado; acc.cesionPipeline += s.cesionPipeline;
    acc.cesionCerrado += s.cesionCerrado; acc.total += s.total; acc.cesionTotal += s.cesionTotal;
    acc.netoPipeline += s.netoPipeline; acc.netoCerrado += s.netoCerrado; acc.netoNuestro += s.netoNuestro;
    return acc;
  }, { pipeline:0, cerrado:0, cesionPipeline:0, cesionCerrado:0, total:0, cesionTotal:0, netoPipeline:0, netoCerrado:0, netoNuestro:0 });

  // Tabla agrupada en 3 bloques (En Pipeline / Cerrado / Total) para que se
  // entienda de un vistazo qué corresponde a cada etapa, en vez de una fila
  // plana de 6 columnas donde era fácil perderse. Cada bloque tiene sus
  // propias 3 columnas: importe, cesión al prescriptor y lo que queda para
  // Moore Market.
  const tablaServicios = `
    <div class="dash-card" style="grid-column:1/-1;">
      <div class="dash-card-header"><i class="ti ti-list-details" aria-hidden="true"></i><span>Importe por servicio</span></div>
      ${filasServicio.length ? `<div class="crm-table-wrap" style="margin-top:10px;"><table class="crm-table">
        <thead>
          <tr>
            <th rowspan="2" style="vertical-align:bottom;">Servicio</th>
            <th colspan="3" style="text-align:center;border-left:2px solid var(--border);background:var(--bg);">EN PIPELINE</th>
            <th colspan="3" style="text-align:center;border-left:2px solid var(--border);background:#F0FBF6;">CERRADO</th>
            <th colspan="3" style="text-align:center;border-left:2px solid var(--border);background:#F5F3FF;">TOTAL (CERRADO + PIPELINE)</th>
          </tr>
          <tr>
            <th style="text-align:center;border-left:2px solid var(--border);">Comisiones totales</th><th style="text-align:center;">Cesión</th><th style="text-align:center;">Moore Market</th>
            <th style="text-align:center;border-left:2px solid var(--border);">Comisiones totales</th><th style="text-align:center;">Cesión</th><th style="text-align:center;">Moore Market</th>
            <th style="text-align:center;border-left:2px solid var(--border);">Comisiones totales</th><th style="text-align:center;">Cesión</th><th style="text-align:center;">Moore Market</th>
          </tr>
        </thead>
        <tbody>${filasServicio.map(s => `<tr>
          <td>${esc(spNombreCliente(s.nombre))}</td>
          <td style="text-align:center;border-left:2px solid var(--border);">${fmtEUR(s.pipeline)}</td>
          <td style="text-align:center;color:var(--purple);">${s.cesionPipeline?fmtEUR(s.cesionPipeline):'—'}</td>
          <td style="text-align:center;">${fmtEUR(s.netoPipeline)}</td>
          <td style="text-align:center;font-weight:700;color:#065F46;border-left:2px solid var(--border);">${fmtEUR(s.cerrado)}</td>
          <td style="text-align:center;color:var(--purple);">${s.cesionCerrado?fmtEUR(s.cesionCerrado):'—'}</td>
          <td style="text-align:center;">${fmtEUR(s.netoCerrado)}</td>
          <td style="text-align:center;font-weight:700;border-left:2px solid var(--border);">${fmtEUR(s.total)}</td>
          <td style="text-align:center;color:var(--purple);font-weight:600;">${s.cesionTotal?fmtEUR(s.cesionTotal):'—'}</td>
          <td style="text-align:center;font-weight:600;">${fmtEUR(s.netoNuestro)}</td>
        </tr>`).join('')}</tbody>
        <tfoot><tr style="border-top:2px solid var(--border);font-weight:700;">
          <td>TOTALES</td>
          <td style="text-align:center;border-left:2px solid var(--border);">${fmtEUR(totalesServicio.pipeline)}</td>
          <td style="text-align:center;color:var(--purple);">${fmtEUR(totalesServicio.cesionPipeline)}</td>
          <td style="text-align:center;">${fmtEUR(totalesServicio.netoPipeline)}</td>
          <td style="text-align:center;color:#065F46;border-left:2px solid var(--border);">${fmtEUR(totalesServicio.cerrado)}</td>
          <td style="text-align:center;color:var(--purple);">${fmtEUR(totalesServicio.cesionCerrado)}</td>
          <td style="text-align:center;">${fmtEUR(totalesServicio.netoCerrado)}</td>
          <td style="text-align:center;border-left:2px solid var(--border);">${fmtEUR(totalesServicio.total)}</td>
          <td style="text-align:center;color:var(--purple);">${fmtEUR(totalesServicio.cesionTotal)}</td>
          <td style="text-align:center;">${fmtEUR(totalesServicio.netoNuestro)}</td>
        </tr></tfoot>
      </table></div>` : `<p style="font-size:13px;color:var(--muted);margin-top:10px;">Todavía no hay servicios con importe en pipeline o cerrados.</p>`}
      ${filasServicio.length ? `
      <!-- VISTA MÓVIL: tarjetas apiladas (la tabla de arriba se oculta en
           pantallas de móvil por la regla global .crm-table-wrap{display:none}) -->
      <div class="crm-cards-mob" style="margin-top:10px;">
        ${filasServicio.map(s => `<div class="crm-card-mob" style="cursor:default;">
          <div class="crm-cell-main" style="margin-bottom:6px;">${esc(spNombreCliente(s.nombre))}</div>
          <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;font-size:11px;">
            <div>
              <div style="color:var(--muted);font-weight:600;margin-bottom:2px;">EN PIPELINE</div>
              <div>${fmtEUR(s.pipeline)}</div>
              <div style="color:var(--purple);">Cesión: ${s.cesionPipeline?fmtEUR(s.cesionPipeline):'—'}</div>
              <div>Neto: ${fmtEUR(s.netoPipeline)}</div>
            </div>
            <div>
              <div style="color:#065F46;font-weight:600;margin-bottom:2px;">CERRADO</div>
              <div style="font-weight:700;color:#065F46;">${fmtEUR(s.cerrado)}</div>
              <div style="color:var(--purple);">Cesión: ${s.cesionCerrado?fmtEUR(s.cesionCerrado):'—'}</div>
              <div>Neto: ${fmtEUR(s.netoCerrado)}</div>
            </div>
            <div>
              <div style="color:#5B21B6;font-weight:600;margin-bottom:2px;">TOTAL</div>
              <div style="font-weight:700;">${fmtEUR(s.total)}</div>
              <div style="color:var(--purple);">Cesión: ${s.cesionTotal?fmtEUR(s.cesionTotal):'—'}</div>
              <div style="font-weight:600;">Neto: ${fmtEUR(s.netoNuestro)}</div>
            </div>
          </div>
        </div>`).join('')}
        <div class="crm-card-mob" style="cursor:default;background:var(--bg);">
          <div class="crm-cell-main" style="margin-bottom:6px;">TOTALES</div>
          <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;font-size:11px;font-weight:700;">
            <div>${fmtEUR(totalesServicio.pipeline)}<div style="font-weight:400;color:var(--purple);">Cesión: ${fmtEUR(totalesServicio.cesionPipeline)}</div></div>
            <div style="color:#065F46;">${fmtEUR(totalesServicio.cerrado)}<div style="font-weight:400;color:var(--purple);">Cesión: ${fmtEUR(totalesServicio.cesionCerrado)}</div></div>
            <div>${fmtEUR(totalesServicio.total)}<div style="font-weight:400;color:var(--purple);">Cesión: ${fmtEUR(totalesServicio.cesionTotal)}</div></div>
          </div>
        </div>
      </div>` : ''}
    </div>`;


  const totalContactosDash = contactos.length;
  const porEtapa = CRMSP_ETAPAS.map(etapa => {
    const lista = contactos.filter(c => c.etapa === etapa);
    const ec = CRMSP_ETAPA_COLOR[etapa];
    const importe = lista.reduce((s,c) => s + spImporteEfectivo(c), 0);
    const pct = totalContactosDash > 0 ? Math.round(lista.length/totalContactosDash*100) : 0;
    return { etapa, ec, lista, importe, pct };
  });

  const tablaEtapas = `
    <div class="dash-card" style="grid-column:1/-1;">
      <div class="dash-card-header"><i class="ti ti-filter" aria-hidden="true"></i><span>Pipeline por etapa</span></div>
      <div style="margin-top:12px;">
        ${porEtapa.map(({etapa,ec,lista,importe,pct}) => `
          <div onclick="irADetalleCRMSPFiltrado('${esc(etapa)}')" style="display:flex;align-items:center;gap:10px;margin-bottom:6px;cursor:pointer;" title="Ver estas propuestas en Detalle">
            <span style="font-size:11px;width:140px;flex-shrink:0;color:var(--text);">${esc(etapa)}</span>
            <div style="flex:1;height:20px;background:var(--border);border-radius:4px;overflow:hidden;">
              <div style="height:100%;width:${pct}%;background:${ec.bg};border-right:2px solid ${ec.color};transition:width 0.4s;"></div>
            </div>
            <span style="text-align:right;width:56px;flex-shrink:0;">
              <span style="font-size:12px;font-weight:700;color:${ec.color};display:block;">${lista.length}</span>
              <span style="font-size:10px;color:var(--muted);display:block;">${importe?fmtEUR(importe):'—'}</span>
            </span>
          </div>`).join('')}
      </div>
    </div>`;

  // ── Facturación y comisiones — Cierres Captados ──
  const facturacionTotal = captados.reduce((s,c) => s + spImporteEfectivo(c), 0);
  const comisionPrescriptorTotal = captados.reduce((s,c) => s + (c.comisionPrescriptor || 0), 0);
  const netoMMTotal = facturacionTotal - comisionPrescriptorTotal;

  const facturacionHTML = `
    <div class="dash-card" style="margin-top:20px;">
      <div class="dash-card-header">
        <i class="ti ti-cash" aria-hidden="true"></i>
        <span>Facturación y Comisiones — Cierres Captados</span>
      </div>
      ${captados.length === 0 ? `
      <p style="color:var(--muted);font-size:13px;margin-top:12px;">Aún no hay propuestas cerradas como "Cliente Captado".</p>
      ` : `
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-top:12px;">
        <div style="text-align:center;background:#F0FBF6;border:1px solid #A9CFBB;border-radius:var(--r);padding:10px;">
          <div style="font-size:16px;font-weight:700;color:#3E7259;">${fmtEUR(facturacionTotal)}</div>
          <div style="font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:0.04em;">Facturación captada</div>
          <div style="font-size:10px;color:var(--muted);">${captados.length} cliente(s)</div>
        </div>
        <div style="text-align:center;background:var(--bg);border-radius:var(--r);padding:10px;">
          <div style="font-size:16px;font-weight:700;color:var(--purple);">${fmtEUR(comisionPrescriptorTotal)}</div>
          <div style="font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:0.04em;">Cesión a prescriptores</div>
        </div>
        <div style="text-align:center;background:var(--bg);border-radius:var(--r);padding:10px;">
          <div style="font-size:16px;font-weight:700;color:var(--purple);">${fmtEUR(netoMMTotal)}</div>
          <div style="font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:0.04em;">Neto Moore Market</div>
        </div>
      </div>
      <div style="overflow-x:auto;margin-top:14px;">
        <table style="width:100%;border-collapse:collapse;font-size:12px;">
          <thead>
            <tr style="border-bottom:1px solid var(--border);">
              <th style="text-align:left;padding:6px 8px;color:var(--muted);font-weight:600;font-size:10px;text-transform:uppercase;">Empresa</th>
              <th style="text-align:left;padding:6px 8px;color:var(--muted);font-weight:600;font-size:10px;text-transform:uppercase;">Prescriptor</th>
              <th style="text-align:right;padding:6px 8px;color:#3E7259;font-weight:600;font-size:10px;text-transform:uppercase;">Facturación</th>
              <th style="text-align:right;padding:6px 8px;color:var(--purple);font-weight:600;font-size:10px;text-transform:uppercase;">Cesión prescriptor</th>
              <th style="text-align:right;padding:6px 8px;color:var(--muted);font-weight:600;font-size:10px;text-transform:uppercase;">Neto MM</th>
            </tr>
          </thead>
          <tbody>
            ${captados.map(c => `
            <tr style="border-bottom:1px solid var(--border);cursor:pointer;" onclick="openModalCRMSP('${c.id}')">
              <td style="padding:6px 8px;font-weight:600;">${esc(c.empresa)}</td>
              <td style="padding:6px 8px;">${esc(c.prescriptor||'—')}</td>
              <td style="padding:6px 8px;text-align:right;font-weight:600;color:#3E7259;">${fmtEUR(spImporteEfectivo(c))}</td>
              <td style="padding:6px 8px;text-align:right;color:var(--purple);">${fmtEUR(c.comisionPrescriptor||0)}</td>
              <td style="padding:6px 8px;text-align:right;">${fmtEUR(spImporteEfectivo(c) - (c.comisionPrescriptor||0))}</td>
            </tr>`).join('')}
          </tbody>
        </table>
      </div>
      `}
    </div>`;

  el.innerHTML = kpis + `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:20px;align-items:start;">
    ${tablaEtapas}
    ${tablaServicios}
  </div>` + facturacionHTML;
}

function irADetalleCRMSPFiltrado(etapa) {
  crmspFiltroEtapas = !etapa ? [] : (Array.isArray(etapa) ? etapa : [etapa]);
  switchCRMSPSubTab('detalle');
}

/* ═══════════════════════════════════════════════════
   DETALLE (tabla)
   ═══════════════════════════════════════════════════ */
let crmspSortCol = null;
let crmspSortDir = 1; // 1 = ascendente, -1 = descendente

// Columnas ordenables de la tabla "Detalle Propuestas" — cada una con su
// función para extraer el valor comparable de un contacto.
// Campos ordenables (valor a comparar) — más columnas de las que se ven,
// porque varias columnas visuales agrupan más de un dato (p.ej. "Contacto"
// muestra nombre + teléfono + email, pero se ordena por nombre).
// Fecha de último contacto — la más reciente entre las notas de
// seguimiento del contacto y la fecha en que se envió la propuesta (si no
// hay notas todavía, la propuesta enviada cuenta como el último contacto).
function crmspFechaUltimoContacto(c) {
  const fechas = (c.seguimiento||[]).map(s => s.fecha).filter(Boolean);
  if (c.fechaPropuesta) fechas.push(c.fechaPropuesta);
  if (!fechas.length) return '';
  return fechas.sort().slice(-1)[0]; // formato ISO -> ordena bien como texto
}

const CRMSP_TABLA_CAMPOS = {
  empresa:            c => c.empresa || '',
  contacto:           c => c.contacto || '',
  origen:             c => c.origen || '',
  responsable:        c => c.responsable || '',
  etapa:              c => c.etapa || '',
  ultimoContacto:     c => crmspFechaUltimoContacto(c),
  fechaProximaAccion: c => c.fechaProximaAccion || '',
  autodiagnostico:    c => c.auditoriaRealizada ? 1 : 0,
  importePipeline:    c => (!CRMSP_ETAPAS_CIERRE.includes(c.etapa) ? spImporteEfectivo(c) : 0) || 0,
  importeContratado:  c => (c.etapa === 'Cliente Captado' ? spImporteEfectivo(c) : 0) || 0,
};

// Columnas visuales de la tabla — agrupadas para que quepan en pantalla sin
// scroll horizontal (antes eran 13 columnas sueltas: Empresa, Contacto,
// Teléfono, Email, Origen, Prescriptor, Responsable, Etapa, Probabilidad,
// Fecha propuesta, Próx. acción, Auditoría, Importe).
const CRMSP_TABLA_COLS = [
  { key:'empresa',            label:'Empresa' },
  { key:'contacto',           label:'Contacto' },
  { key:'origen',             label:'Origen / Prescriptor' },
  { key:'responsable',        label:'Responsable' },
  { key:'etapa',              label:'Etapa / Probabilidad' },
  { key:'ultimoContacto',     label:'Último contacto' },
  { key:'fechaProximaAccion', label:'Próximo contacto' },
  { key:'autodiagnostico',    label:'Autodiagnóstico' },
  { key:'importePipeline',    label:'Importe en pipeline' },
  { key:'importeContratado',  label:'Importe contratado' },
];

function crmspOrdenarTabla(col) {
  if (crmspSortCol === col) crmspSortDir *= -1;
  else { crmspSortCol = col; crmspSortDir = 1; }
  renderCRMSPFiltrosTabla();
}

function renderCRMSPFiltrosTabla() {
  renderCRMSPEtapaFiltroChecks('crmsp-filter-etapa', crmspFiltroEtapas, 'crmspEtapaFiltroToggle');
  let contactos = getCRMSPVisibles();
  const fEmpresa = _normalizarBusqueda(document.getElementById('crmsp-filter-empresa')?.value?.trim() || '');
  const fResp = document.getElementById('crmsp-filter-resp')?.value || '';
  const fOrigen = document.getElementById('crmsp-filter-origen')?.value || '';
  const fTienePrescriptor = document.getElementById('crmsp-filter-tiene-prescriptor')?.value || '';
  const fPrescriptor = document.getElementById('crmsp-filter-prescriptor')?.value || '';
  const fProb = document.getElementById('crmsp-filter-probabilidad')?.value || '';
  const fMotivo = document.getElementById('crmsp-filter-motivo')?.value || '';
  const fPoblacion = document.getElementById('crmsp-filter-poblacion')?.value || '';
  if (crmspFiltroEtapas.length) contactos = contactos.filter(c => crmspFiltroEtapas.includes(c.etapa));
  if (fEmpresa) contactos = contactos.filter(c => _normalizarBusqueda(c.empresa||'').includes(fEmpresa));
  if (fResp) contactos = contactos.filter(c => c.responsable === fResp);
  if (fOrigen) contactos = contactos.filter(c => c.origen === fOrigen);
  if (fTienePrescriptor === 'si') contactos = contactos.filter(c => !!c.prescriptor);
  else if (fTienePrescriptor === 'no') contactos = contactos.filter(c => !c.prescriptor);
  if (fPrescriptor) contactos = contactos.filter(c => _prescriptorCoincide(c.prescriptor, fPrescriptor));
  if (fProb) contactos = contactos.filter(c => c.probabilidad === fProb);
  if (fMotivo) contactos = contactos.filter(c => c.motivoDescarte === fMotivo);
  if (fPoblacion) contactos = contactos.filter(c => c.poblacion === fPoblacion);

  const selPoblacion = document.getElementById('crmsp-filter-poblacion');
  if (selPoblacion) {
    const municipios = [...new Set(getCRMSPVisibles().map(c=>c.poblacion).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
    selPoblacion.innerHTML = '<option value="">Todos los municipios</option>' + municipios.map(m=>`<option value="${esc(m)}" ${fPoblacion===m?'selected':''}>${esc(m)}</option>`).join('');
  }

  const el = document.getElementById('crmsp-list');
  if (!el) return;

  if (!contactos.length) {
    el.innerHTML = '<p style="font-size:13px;color:var(--muted);padding:20px;">No hay propuestas que coincidan con los filtros.</p>';
    return;
  }

  if (crmspSortCol) {
    const getVal = CRMSP_TABLA_CAMPOS[crmspSortCol];
    if (getVal) {
      contactos = contactos.slice().sort((a,b) => {
        const va = getVal(a), vb = getVal(b);
        if (typeof va === 'number' && typeof vb === 'number') return (va - vb) * crmspSortDir;
        return String(va).localeCompare(String(vb), 'es', {sensitivity:'base'}) * crmspSortDir;
      });
    }
  }

  const filas = contactos.map(c => {
    const ec = CRMSP_ETAPA_COLOR[c.etapa] || {bg:'#F3F4F6',color:'#6B7280'};
    const pc = CRMSP_PROBABILIDAD_COLOR[c.probabilidad] || {bg:'#F3F4F6',color:'#6B7280'};
    const importePipeline = !CRMSP_ETAPAS_CIERRE.includes(c.etapa) ? spImporteEfectivo(c) : 0;
    const importeContratado = c.etapa === 'Cliente Captado' ? spImporteEfectivo(c) : 0;
    return `<tr onclick="openModalCRMSP('${c.id}')" style="cursor:pointer;">
      <td>${esc(c.empresa)}
        ${c.propuestaAceptada ? `<div style="margin-top:2px;"><span style="font-size:10px;padding:2px 7px;border-radius:10px;background:#D1FAE5;color:#065F46;font-weight:600;" title="El cliente aceptó la propuesta el ${esc(fmtDate(c.propuestaAceptadaFecha))}"><i class="ti ti-circle-check" style="font-size:10px;"></i> Aceptada por el cliente</span></div>` : ''}
      </td>
      <td>
        ${esc(c.contacto||'—')}
        ${(c.telefono||c.email) ? `<div class="crm-cell-sub">${[c.telefono, c.email].filter(Boolean).map(esc).join(' · ')}</div>` : ''}
      </td>
      <td>
        ${esc(c.origen||'—')}
        ${c.prescriptor ? `<div class="crm-cell-sub"><i class="ti ti-user-star" style="font-size:10px;"></i> ${esc(c.prescriptor)}</div>` : ''}
      </td>
      <td>${esc(c.responsable||'—')}</td>
      <td style="text-align:center;">
        <span style="font-size:11px;padding:3px 8px;border-radius:10px;background:${ec.bg};color:${ec.color};font-weight:600;white-space:nowrap;">${esc(c.etapa)}</span>
        ${c.probabilidad ? `<div style="margin-top:3px;"><span style="font-size:10px;padding:2px 7px;border-radius:10px;background:${pc.bg};color:${pc.color};">${esc(c.probabilidad)}</span></div>` : ''}
      </td>
      <td style="text-align:center;white-space:nowrap;">
        ${(() => { const uc = crmspFechaUltimoContacto(c); return uc ? fmtDate(uc) : '<span style="color:var(--muted);">—</span>'; })()}
      </td>
      <td style="text-align:center;white-space:nowrap;">
        ${c.fechaProximaAccion ? `<span style="color:var(--purple);font-weight:600;">${fmtDate(c.fechaProximaAccion)}</span>` : '<span style="color:var(--muted);">—</span>'}
      </td>
      <td style="text-align:center;white-space:nowrap;">
        ${c.auditoriaRealizada
          ? `<div style="color:#065F46;font-size:11px;font-weight:600;" title="Autodiagnóstico realizado">✓ Autodiagnóstico${c.auditoria?.fecha ? ' · '+fmtDate(c.auditoria.fecha) : ''}</div>`
          : '<div style="color:var(--muted);font-size:11px;">Sin responder</div>'}
        ${c.seguimientoAutodiagnostico ? `<div style="margin-top:3px;">${_badgeSeguimientoAuditoriaSP(c.seguimientoAutodiagnostico)}</div>` : ''}
        ${c.propuestaAutoGenerada ? `<div style="margin-top:3px;"><span style="font-size:10px;padding:2px 7px;border-radius:10px;background:#EEF2FF;color:#3457B2;font-weight:600;" title="Propuesta generada sola a partir del autodiagnóstico — pendiente de revisar"><i class="ti ti-sparkles" style="font-size:10px;"></i> Auto-generada</span></div>` : ''}
      </td>
      <td style="text-align:right;font-weight:700;white-space:nowrap;color:var(--purple);">${importePipeline?fmtEUR(importePipeline):'—'}</td>
      <td style="text-align:right;font-weight:700;white-space:nowrap;color:#3E7259;">${importeContratado?fmtEUR(importeContratado):'—'}</td>
    </tr>`;
  }).join('');

  const thHTML = CRMSP_TABLA_COLS.map(colDef => {
    const activa = crmspSortCol === colDef.key;
    const flecha = activa ? (crmspSortDir === 1 ? ' ▲' : ' ▼') : '';
    return `<th style="cursor:pointer;user-select:none;${activa?'color:var(--purple);':''}" onclick="crmspOrdenarTabla('${colDef.key}')" title="Ordenar por ${esc(colDef.label)}">${esc(colDef.label)}${flecha}</th>`;
  }).join('');

  const tablaHTML = `<div class="crm-table-wrap"><table class="crm-table crm-table-compact">
    <thead><tr>${thHTML}</tr></thead>
    <tbody>${filas}</tbody>
  </table></div>`;

  // ── VISTA MÓVIL: cards apiladas — sin esto, en pantallas <768px la tabla
  // se oculta (regla CSS .crm-table-wrap{display:none}) y no queda nada
  // que mostrar en su lugar. ──
  const cardsHTML = `<div class="crm-cards-mob">
    ${contactos.map(c => {
      const ec = CRMSP_ETAPA_COLOR[c.etapa] || {bg:'#F3F4F6',color:'#6B7280'};
      const pc = CRMSP_PROBABILIDAD_COLOR[c.probabilidad] || {bg:'#F3F4F6',color:'#6B7280'};
      const importePipeline = !CRMSP_ETAPAS_CIERRE.includes(c.etapa) ? spImporteEfectivo(c) : 0;
      const importeContratado = c.etapa === 'Cliente Captado' ? spImporteEfectivo(c) : 0;
      return `<div class="crm-card-mob" onclick="openModalCRMSP('${c.id}')">
        <div class="crm-card-mob-header">
          <div>
            <div class="crm-cell-main">${esc(c.empresa)}</div>
            ${c.contacto ? `<div class="crm-cell-sub">${esc(c.contacto)}${c.telefono?' · '+esc(c.telefono):''}</div>` : ''}
            ${c.propuestaAceptada ? `<span style="font-size:10px;padding:2px 7px;border-radius:10px;background:#D1FAE5;color:#065F46;font-weight:600;display:inline-block;margin-top:3px;"><i class="ti ti-circle-check" style="font-size:10px;"></i> Aceptada</span>` : ''}
          </div>
          <span style="background:${ec.bg};color:${ec.color};font-size:10px;font-weight:600;padding:2px 8px;border-radius:20px;flex-shrink:0;">${esc(c.etapa||'—')}</span>
        </div>
        <div class="crm-card-mob-body">
          ${c.prescriptor ? `<div class="crm-cell-sub"><i class="ti ti-user-star" style="font-size:10px;"></i> ${esc(c.prescriptor)}</div>` : ''}
          ${c.responsable ? `<div class="crm-cell-sub" style="color:var(--purple);"><i class="ti ti-user" style="font-size:10px;"></i> ${esc(c.responsable)}</div>` : ''}
          ${c.origen ? `<div class="crm-cell-sub"><i class="ti ti-source-code" style="font-size:10px;"></i> ${esc(c.origen)}</div>` : ''}
          <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:4px;align-items:center;">
            ${c.probabilidad ? `<span class="crm-badge" style="background:${pc.bg};color:${pc.color};">${esc(c.probabilidad)}</span>` : ''}
            ${c.auditoriaRealizada ? `<span class="crm-badge" style="background:#D1FAE5;color:#065F46;">✓ Autodiagnóstico</span>` : ''}
            ${c.propuestaAutoGenerada ? `<span class="crm-badge" style="background:#EEF2FF;color:#3457B2;"><i class="ti ti-sparkles" style="font-size:10px;"></i> Auto-generada</span>` : ''}
            ${importePipeline ? `<span class="crm-badge" style="background:#EDE9FE;color:#5B21B6;" title="Importe en pipeline">${fmtEUR(importePipeline)}</span>` : ''}
            ${importeContratado ? `<span class="crm-badge" style="background:#D1FAE5;color:#065F46;" title="Importe contratado">${fmtEUR(importeContratado)}</span>` : ''}
          </div>
          ${c.seguimientoAutodiagnostico ? `<div style="margin-top:4px;">${_badgeSeguimientoAuditoriaSP(c.seguimientoAutodiagnostico)}</div>` : ''}
          ${(() => { const uc = crmspFechaUltimoContacto(c); return uc ? `<div class="crm-cell-sub" style="margin-top:4px;"><i class="ti ti-phone-outgoing" style="font-size:10px;"></i> Último contacto: ${fmtDate(uc)}</div>` : ''; })()}
          ${c.fechaProximaAccion ? `<div class="crm-cell-sub" style="color:var(--purple);margin-top:4px;"><i class="ti ti-clock" style="font-size:10px;"></i> Próx. acción: ${fmtDate(c.fechaProximaAccion)}</div>` : ''}
        </div>
      </div>`;
    }).join('')}
  </div>`;

  el.innerHTML = tablaHTML + cardsHTML;
}


/* ═══════════════════════════════════════════════════
   LEADS
   ═══════════════════════════════════════════════════ */
// Dashboard de estado de los leads (Empresas Potenciales) — mismo patrón
// que renderLeadsResumen() de CRM Comunidades: KPIs generales + una
// tarjeta clicable por cada estado de gestión, que filtra la lista al
// pulsarla.
function renderLeadsSPResumen() {
  const cont = document.getElementById('crmsp-leads-resumen');
  if (!cont) return;
  const todos = data.leadsSP || [];
  const total = todos.length;
  if (!total) { cont.innerHTML = ''; return; }

  const conteos = {};
  CRMSP_LEADS_ESTADOS.forEach(e => conteos[e] = 0);
  todos.forEach(l => { const e = l.estado || 'Sin contactar'; conteos[e] = (conteos[e]||0) + (CRMSP_LEADS_ESTADOS.includes(e) ? 1 : 0); });
  const sinContactar = conteos['Sin contactar'] || 0;
  const gestionados = total - sinContactar;
  const pct = (n, base) => base > 0 ? `${((n/base)*100).toFixed(1)}%` : '—';
  const estadosSecundarios = CRMSP_LEADS_ESTADOS.filter(e => e !== 'Sin contactar');

  cont.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-bottom:10px;">
      <div class="kpi-card" style="border-top:3px solid var(--purple);cursor:pointer;" onclick="filtrarLeadsSPPorEstado('')" title="Ver todos los leads">
        <div class="kpi-icon-row"><i class="ti ti-address-book" style="color:var(--purple)" aria-hidden="true"></i><div class="kpi-label">TOTAL LEADS</div></div>
        <div class="kpi-val">${total}</div>
        <div class="kpi-sub">${gestionados} gestionados · ${sinContactar} sin contactar</div>
      </div>
      <div class="kpi-card" style="border-top:3px solid ${CRMSP_LEADS_ESTADO_COLOR['Sin contactar'].color};cursor:pointer;" onclick="filtrarLeadsSPPorEstado('Sin contactar')" title="Ver leads sin contactar">
        <div class="kpi-icon-row"><i class="ti ti-user-question" style="color:${CRMSP_LEADS_ESTADO_COLOR['Sin contactar'].color}" aria-hidden="true"></i><div class="kpi-label">LEADS SIN CONTACTAR</div></div>
        <div class="kpi-val">${sinContactar}</div>
        <div class="kpi-sub">${pct(sinContactar,total)} del total</div>
      </div>
      <div class="kpi-card" style="border-top:3px solid var(--teal,#1A9070);cursor:pointer;" onclick="filtrarLeadsSPPorEstado('__gestionados__')" title="Ver leads contactados (todos los estados salvo 'Sin contactar')">
        <div class="kpi-icon-row"><i class="ti ti-user-check" style="color:var(--teal,#1A9070)" aria-hidden="true"></i><div class="kpi-label">LEADS CONTACTADOS</div></div>
        <div class="kpi-val">${gestionados}</div>
        <div class="kpi-sub">${pct(gestionados,total)} del total</div>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;">
      ${estadosSecundarios.map(e => {
        const n = conteos[e] || 0;
        const ec = CRMSP_LEADS_ESTADO_COLOR[e];
        const label = (CRMSP_LEADS_ESTADO_LABELS[e] || e).toUpperCase();
        return `<div class="kpi-card kpi-card-sm" style="border-top:3px solid ${ec.color};cursor:pointer;" onclick="filtrarLeadsSPPorEstado('${e}')" title="Ver leads en estado ${esc(e)}">
          <div class="kpi-label">${esc(label)}</div>
          <div class="kpi-val">${n}</div>
          <div class="kpi-sub">${pct(n,total)} del total · ${pct(n,gestionados)} de gestionados</div>
        </div>`;
      }).join('')}
    </div>`;
}

function filtrarLeadsSPPorEstado(estado) {
  const sel = document.getElementById('crmsp-leads-filter-estado');
  if (sel) sel.value = estado;
  renderLeadsSP();
}

// Ordenación de la tabla de Leads — mismo patrón que las demás tablas del
// módulo (crmspSortCol / CRMSPPRES_TABLA_COLS).
let crmspLeadsSortCol = null;
let crmspLeadsSortDir = 1;

const CRMSP_LEADS_TABLA_CAMPOS = {
  empresa:         l => l.empresa || '',
  poblacion:       l => l.poblacion || '',
  responsable:     l => l.responsable || '',
  estado:          l => CRMSP_LEADS_ESTADO_LABELS[l.estado] || l.estado || 'Sin contactar',
  prescriptor:     l => l.prescriptor || '',
  autodiagnostico: l => l.auditoriaPublicaCompletada ? 1 : 0,
};

const CRMSP_LEADS_TABLA_COLS = [
  { key:'empresa',         label:'Empresa',             align:'left',   width:'22%' },
  { key:'poblacion',       label:'Municipio',           align:'left',   width:'10%' },
  { key:'responsable',     label:'Responsable interno', align:'left',   width:'11%' },
  { key:'estado',          label:'Estado',              align:'center', width:'12%' },
  { key:'prescriptor',     label:'Prescriptor',         align:'left',   width:'14%' },
  { key:'autodiagnostico', label:'Autodiagnóstico',     align:'center', width:'12%' },
];

function crmspLeadsOrdenarTabla(col) {
  if (crmspLeadsSortCol === col) crmspLeadsSortDir *= -1;
  else { crmspLeadsSortCol = col; crmspLeadsSortDir = 1; }
  renderLeadsSP();
}

// Repara leads marcados "Pasado a CRM" cuyo contacto vinculado ya no existe
// (se borró la propuesta) o nunca llegó a existir de verdad (datos de
// prueba/importados que ya traían el estado así, sin el vínculo real
// detrás) — se detectan y se devuelven a "Contactado" automáticamente cada
// vez que se abre la pantalla de Leads, para no dejar el dato inconsistente
// esperando a que alguien lo note.
// Seguimiento del autodiagnóstico — mismo campo/vocabulario tanto en Leads
// como en Contactos Comerciales (data.leadsSP[].seguimientoAutodiagnostico y
// data.contactosSP[].seguimientoAutodiagnostico). Se gestiona desde el menú
// de Autodiagnóstico (renderCRMSPAuditoria), no desde las tablas de Leads ni
// Contactos — ahí solo se ve como información, no se edita.
const CRMSP_SEGUIMIENTO_AUDITORIA_ESTADOS = ['Enviado', 'Sin Respuesta', 'Solicita Llamada', 'Quiere Contratar'];
const CRMSP_SEGUIMIENTO_AUDITORIA_COLOR = {
  'Enviado':          { bg:'#F3F4F6', color:'#6B7280' },
  'Sin Respuesta':    { bg:'#FEF3C7', color:'#92400E' },
  'Solicita Llamada': { bg:'#E0E7FF', color:'#3730A3' },
  'Quiere Contratar': { bg:'#FEE2E2', color:'#991B1B' },
};
// Etiqueta que se muestra al usuario — distinta de la clave que se guarda
// (esa no cambia, para no romper datos ya guardados). "Enviado" se
// muestra más descriptivo: dice explícitamente que está a la espera.
const CRMSP_SEGUIMIENTO_AUDITORIA_LABEL = {
  'Enviado': 'Enviado · a la espera de respuesta',
  'Sin Respuesta': 'Sin Respuesta',
  'Solicita Llamada': 'Solicita Llamada',
  'Quiere Contratar': 'Quiere Contratar',
};
// Prioridad para ordenar el menú de Autodiagnóstico: lo más urgente arriba.
const CRMSP_SEGUIMIENTO_AUDITORIA_PRIORIDAD = { 'Quiere Contratar':4, 'Solicita Llamada':3, 'Sin Respuesta':2, 'Enviado':1, '':0 };

function _badgeSeguimientoAuditoriaSP(estado) {
  if (!estado) return `<span style="font-size:11px;color:var(--muted);">—</span>`;
  const c = CRMSP_SEGUIMIENTO_AUDITORIA_COLOR[estado] || {bg:'#F3F4F6', color:'#6B7280'};
  const icono = estado === 'Quiere Contratar' ? '🔥 ' : estado === 'Solicita Llamada' ? '📞 ' : '';
  const label = CRMSP_SEGUIMIENTO_AUDITORIA_LABEL[estado] || estado;
  return `<span style="font-size:11px;padding:3px 8px;border-radius:10px;background:${c.bg};color:${c.color};font-weight:700;white-space:nowrap;">${icono}${esc(label)}</span>`;
}

// Genera (si hace falta) el token público y devuelve la entidad (lead o
// contacto) ya con publicToken asegurado — para poder mandarle el enlace
// de autodiagnóstico a cualquiera de las dos, no solo a los leads.
function _crmspAsegurarPublicTokenSP(entidad) {
  if (!entidad.publicToken) entidad.publicToken = crmspGenerarTokenPublico();
  return entidad.publicToken;
}

// Punto único para "enviar autodiagnóstico" — usado tanto desde la ficha de
// Lead como desde la de Contacto Comercial (y desde el propio menú de
// Autodiagnóstico). Copia el enlace público y, si el seguimiento todavía no
// ha avanzado (nadie ha respondido todavía), lo marca como "Enviado" para
// que quede trazabilidad de que se ha mandado.
function crmspEnviarAutodiagnosticoSP(tipo, id) {
  const lista = tipo === 'lead' ? data.leadsSP : data.contactosSP;
  const idx = (lista||[]).findIndex(x => x.id === id);
  if (idx < 0) { showToast('No se ha encontrado la ficha — guárdala primero'); return; }
  const entidad = lista[idx];
  _crmspAsegurarPublicTokenSP(entidad);
  // No pisa un seguimiento que ya haya avanzado (p. ej. si ya ha pedido
  // contratar y alguien vuelve a copiar el enlace, no queremos "degradarlo"
  // de vuelta a "Enviado").
  if (!entidad.seguimientoAutodiagnostico || entidad.seguimientoAutodiagnostico === 'Sin Respuesta') {
    entidad.seguimientoAutodiagnostico = 'Enviado';
    entidad.fechaEnvioAutodiagnostico = fechaLocalISO(new Date());
    entidad.enviadoPorAutodiagnostico = currentUserNombre || '';
  }
  saveData([tipo === 'lead' ? 'leadsSP' : 'contactosSP']);
  const link = getLinkAuditoriaPublicaSP(entidad);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(link).then(() => showToast('Enlace copiado — pégalo en el email o WhatsApp de presentación'));
  } else {
    prompt('Copia este enlace:', link);
  }
  if (typeof renderLeadsSP === 'function') renderLeadsSP();
  if (typeof renderCRMSPAuditoria === 'function') renderCRMSPAuditoria();
}

// Cambio de seguimiento hecho a mano por el equipo desde el propio menú de
// Autodiagnóstico (dropdown inline en cada fila).
function crmspCambiarSeguimientoAutodiagnosticoSP(tipo, id, valor) {
  const lista = tipo === 'lead' ? data.leadsSP : data.contactosSP;
  const idx = (lista||[]).findIndex(x => x.id === id);
  if (idx < 0) return;
  lista[idx].seguimientoAutodiagnostico = valor || '';
  saveData([tipo === 'lead' ? 'leadsSP' : 'contactosSP']);
  showToast('Seguimiento actualizado ✓');
}

// Edición rápida en línea desde el propio menú de Autodiagnóstico — para
// no tener que abrir la ficha completa solo para corregir el nombre de la
// empresa, la persona de contacto o el responsable interno.
function crmspAuditoriaEditarCampoInline(tipo, id, campo, valor) {
  const lista = tipo === 'lead' ? data.leadsSP : data.contactosSP;
  const idx = (lista||[]).findIndex(x => x.id === id);
  if (idx < 0) return;
  const val = String(valor||'').trim();
  if ((lista[idx][campo]||'') === val) return; // sin cambios reales, no gastar un guardado
  lista[idx][campo] = val;
  saveData([tipo === 'lead' ? 'leadsSP' : 'contactosSP']);
  showToast('Guardado ✓');
}

function _repararLeadsSPHuerfanos() {
  const leads = data.leadsSP || [];
  const idsContactosReales = new Set((data.contactosSP||[]).map(c => c.id));
  let reparados = 0;
  leads.forEach(l => {
    if (l.estado === 'Pasado a CRM' && (!l.contactoCrmId || !idsContactosReales.has(l.contactoCrmId))) {
      l.estado = 'Contactado';
      l.contactoCrmId = null;
      reparados++;
    }
  });
  if (reparados > 0) saveData(['leadsSP']);
}

function renderLeadsSP() {
  const el = document.getElementById('crmsp-leads-list');
  if (!el) return;
  _repararLeadsSPHuerfanos();
  renderLeadsSPResumen();
  let leads = data.leadsSP || [];
  const fEmpresa = _normalizarBusqueda(document.getElementById('crmsp-leads-filter-empresa')?.value?.trim() || '');
  const fEstado = document.getElementById('crmsp-leads-filter-estado')?.value || '';
  const fPrescriptor = document.getElementById('crmsp-leads-filter-prescriptor')?.value || '';
  const fPoblacion = document.getElementById('crmsp-leads-filter-poblacion')?.value || '';
  const fResp = document.getElementById('crmsp-leads-filter-resp')?.value || '';
  if (fEmpresa) leads = leads.filter(l => _normalizarBusqueda(l.empresa||'').includes(fEmpresa));
  if (fEstado === '__gestionados__') leads = leads.filter(l => (l.estado||'Sin contactar') !== 'Sin contactar');
  else if (fEstado) leads = leads.filter(l => l.estado === fEstado);
  if (fPrescriptor) leads = leads.filter(l => _prescriptorCoincide(l.prescriptor, fPrescriptor));
  if (fPoblacion) leads = leads.filter(l => l.poblacion === fPoblacion);
  if (fResp) leads = leads.filter(l => l.responsable === fResp);

  if (crmspLeadsSortCol) {
    const getVal = CRMSP_LEADS_TABLA_CAMPOS[crmspLeadsSortCol];
    leads = leads.slice().sort((a,b) => {
      const va = getVal(a), vb = getVal(b);
      if (typeof va === 'number' && typeof vb === 'number') return (va - vb) * crmspLeadsSortDir;
      return String(va).localeCompare(String(vb), 'es', {sensitivity:'base'}) * crmspLeadsSortDir;
    });
  }

  // Poblar las opciones de municipio y comercial a partir de los leads
  // existentes (igual que se hace con el resto de filtros del módulo) —
  // se reconstruye en cada render para que los valores nuevos aparezcan,
  // conservando la selección actual.
  const selPoblacion = document.getElementById('crmsp-leads-filter-poblacion');
  if (selPoblacion) {
    const municipios = [...new Set((data.leadsSP||[]).map(l=>l.poblacion).filter(Boolean))].sort();
    selPoblacion.innerHTML = '<option value="">Todos los municipios</option>' + municipios.map(m=>`<option value="${esc(m)}" ${fPoblacion===m?'selected':''}>${esc(m)}</option>`).join('');
  }
  const selResp = document.getElementById('crmsp-leads-filter-resp');
  if (selResp) {
    const comerciales = [...new Set((data.leadsSP||[]).map(l=>l.responsable).filter(Boolean))].sort();
    selResp.innerHTML = '<option value="">Todos los responsables internos</option>' + comerciales.map(r=>`<option value="${esc(r)}" ${fResp===r?'selected':''}>${esc(r)}</option>`).join('');
  }

  const contador = document.getElementById('crmsp-leads-contador');
  if (contador) contador.textContent = leads.length + ' lead(s)';

  if (!leads.length) {
    el.innerHTML = '<p style="font-size:13px;color:var(--muted);padding:20px;">No hay leads que coincidan con los filtros. Usa "Nuevo lead" o "Importar leads" arriba para añadirlos.</p>';
    return;
  }

  const thHTML = CRMSP_LEADS_TABLA_COLS.map(colDef => {
    const activa = crmspLeadsSortCol === colDef.key;
    const flecha = activa ? (crmspLeadsSortDir === 1 ? ' ▲' : ' ▼') : '';
    return `<th style="text-align:${colDef.align};width:${colDef.width};cursor:pointer;user-select:none;${activa?'color:var(--purple);':''}" onclick="crmspLeadsOrdenarTabla('${colDef.key}')" title="Ordenar por ${esc(colDef.label)}">${esc(colDef.label)}${flecha}</th>`;
  }).join('');

  const filas = leads.map(l => {
    const hechaAuditoria = !!l.auditoriaPublicaCompletada;
    const ec = CRMSP_LEADS_ESTADO_COLOR[l.estado||'Sin contactar'] || {bg:'#F3F4F6',color:'#6B7280'};
    const lbl = CRMSP_LEADS_ESTADO_LABELS[l.estado] || l.estado || 'Sin contactar';
    return `<tr onclick="abrirModalLeadSP('${l.id}')" class="crm-tr" style="cursor:pointer;">
      <td style="text-align:left;padding:14px 12px;">
        <div style="font-weight:600;font-size:13px;">${esc(l.empresa||'—')}</div>
        <div style="font-size:11px;color:var(--muted);">${esc(l.contacto||'')} ${l.telefono?'· '+esc(l.telefono):''} ${l.email?'· '+esc(l.email):''}</div>
      </td>
      <td style="text-align:left;padding:14px 12px;">${esc(l.poblacion||'—')}</td>
      <td style="text-align:left;padding:14px 12px;">${esc(l.responsable||'—')}</td>
      <td style="text-align:center;padding:14px 12px;"><span style="font-size:11px;padding:3px 8px;border-radius:10px;background:${ec.bg};color:${ec.color};font-weight:600;white-space:nowrap;">${esc(lbl)}</span></td>
      <td style="text-align:left;padding:14px 12px;">${l.prescriptor ? `<span style="font-size:11px;padding:3px 8px;border-radius:10px;background:#EDE9FE;color:#5B21B6;white-space:nowrap;" title="Prescriptor"><i class="ti ti-user-star" style="font-size:11px;"></i> ${esc(l.prescriptor)}</span>` : '—'}</td>
      <td style="text-align:center;white-space:nowrap;padding:14px 12px;">
        ${hechaAuditoria
          ? `<div style="color:#065F46;font-size:11px;font-weight:600;" title="Autodiagnóstico realizado">✓ Autodiagnóstico${l.auditoriaPublicaRespuesta?.fecha ? ' · '+fmtDate(l.auditoriaPublicaRespuesta.fecha) : ''}</div>`
          : '<div style="color:var(--muted);font-size:11px;">Sin responder</div>'}
        ${l.seguimientoAutodiagnostico ? `<div style="margin-top:3px;">${_badgeSeguimientoAuditoriaSP(l.seguimientoAutodiagnostico)}</div>` : ''}
      </td>
      <td class="crm-col-actions" onclick="event.stopPropagation();" style="text-align:right;white-space:nowrap;padding:14px 12px;">
        <div style="display:grid;grid-template-columns:repeat(4,28px);gap:2px;justify-items:center;">
          <span>${hechaAuditoria ? `<button onclick="abrirModalAuditoriaSP('${l.id}','lead')" class="btn-sm" title="Editar encuesta de autodiagnóstico" style="padding:0 8px;"><i class="ti ti-eye" style="font-size:12px;" aria-hidden="true"></i></button>` : ''}</span>
          <span><button onclick="crmspEnviarAutodiagnosticoSP('lead','${l.id}')" class="btn-sm" title="Enviar autodiagnóstico" style="padding:0 8px;"><i class="ti ti-link" style="font-size:12px;" aria-hidden="true"></i></button></span>
          <span>${l.estado!=='Pasado a CRM' ? `<button onclick="convertirLeadACRMSP('${l.id}')" class="btn-sm" title="Pasado a CRM" style="padding:0 8px;color:#0F7A5C;"><i class="ti ti-arrow-big-right-lines" style="font-size:12px;" aria-hidden="true"></i></button>` : ''}</span>
          <span><button onclick="abrirModalLeadSP('${l.id}')" class="btn-sm" title="Editar" style="padding:0 8px;"><i class="ti ti-edit" style="font-size:12px;" aria-hidden="true"></i></button></span>
        </div>
      </td>
    </tr>`;
  }).join('');

  const tablaHTML = `<div class="crm-table-wrap"><table class="crm-table" style="table-layout:fixed;min-width:900px;">
    <thead><tr>${thHTML}<th style="text-align:right;width:15%;">Acciones</th></tr></thead>
    <tbody>${filas}</tbody>
  </table></div>`;

  // ── VISTA MÓVIL: tarjetas apiladas ── (sin esto la tabla desaparece en
  // pantallas de móvil por la regla global .crm-table-wrap{display:none} y
  // no queda nada en su lugar — mismo caso que ya resolvimos en los leads
  // de Comunidades).
  const cardsHTML = `<div class="crm-cards-mob">
    ${leads.map(l => {
      const hechaAuditoria = !!l.auditoriaPublicaCompletada;
      const ec = CRMSP_LEADS_ESTADO_COLOR[l.estado||'Sin contactar'] || {bg:'#F3F4F6',color:'#6B7280'};
      const lbl = CRMSP_LEADS_ESTADO_LABELS[l.estado] || l.estado || 'Sin contactar';
      return `<div class="crm-card-mob" onclick="abrirModalLeadSP('${l.id}')">
        <div class="crm-card-mob-header">
          <div>
            <div class="crm-cell-main">${esc(l.empresa||'Sin nombre')}</div>
            ${l.contacto ? `<div class="crm-cell-sub">${esc(l.contacto)}</div>` : ''}
          </div>
          <span style="background:${ec.bg};color:${ec.color};font-size:10px;font-weight:600;padding:2px 8px;border-radius:20px;flex-shrink:0;white-space:nowrap;">${esc(lbl)}</span>
        </div>
        <div class="crm-card-mob-body">
          ${l.telefono ? `<div class="crm-cell-sub"><i class="ti ti-phone" style="font-size:10px;"></i> ${esc(l.telefono)}</div>` : ''}
          ${l.email ? `<div class="crm-cell-sub"><i class="ti ti-mail" style="font-size:10px;"></i> ${esc(l.email)}</div>` : ''}
          ${l.poblacion ? `<div class="crm-cell-sub"><i class="ti ti-map-pin" style="font-size:10px;"></i> ${esc(l.poblacion)}</div>` : ''}
          ${l.responsable ? `<div class="crm-cell-sub" style="color:var(--purple);"><i class="ti ti-user" style="font-size:10px;"></i> ${esc(l.responsable)}</div>` : ''}
          ${l.prescriptor ? `<div class="crm-cell-sub" style="color:#5B21B6;"><i class="ti ti-user-star" style="font-size:10px;"></i> ${esc(l.prescriptor)}</div>` : ''}
          <div class="crm-cell-sub">Autodiagnóstico: ${hechaAuditoria ? '✓ Respondida' : 'Pendiente'}</div>
        </div>
        <div class="crm-card-mob-actions" onclick="event.stopPropagation()">
          ${hechaAuditoria ? `<button onclick="abrirModalAuditoriaSP('${l.id}','lead')" class="btn-sm"><i class="ti ti-edit" style="font-size:12px;"></i> Editar encuesta</button>` : ''}
          <button onclick="crmspEnviarAutodiagnosticoSP('lead','${l.id}')" class="btn-sm"><i class="ti ti-link" style="font-size:12px;"></i> Enviar</button>
          ${l.estado!=='Pasado a CRM' ? `<button onclick="convertirLeadACRMSP('${l.id}')" class="btn-sm" style="color:#0F7A5C;"><i class="ti ti-arrow-big-right-lines" style="font-size:12px;"></i> Pasado a CRM</button>` : ''}
          <button onclick="abrirModalLeadSP('${l.id}')" class="btn-sm"><i class="ti ti-edit" style="font-size:12px;"></i> Editar</button>
        </div>
      </div>`;
    }).join('')}
  </div>`;

  el.innerHTML = tablaHTML + cardsHTML;
}

function convertirLeadACRMSP(leadId) {
  const lead = (data.leadsSP||[]).find(l => l.id === leadId);
  if (!lead) return;
  const hoy = new Date().toISOString().slice(0,10);
  const obj = {
    id: 'crmsp' + Date.now(),
    empresa: lead.empresa || '', cif: lead.cif || '', contacto: lead.contacto || '', telefono: lead.telefono || '', email: lead.email || '',
    origen: lead.origen || '', prescriptor: lead.prescriptor || '', etapa: 'Lead Migrado - Pdte. Contacto', probabilidad: '', responsable: lead.responsable || '', numEmpleados: 0,
    serviciosOfertados: [], importePropuesta: 0,
    publicToken: lead.publicToken || null,
    seguimientoAutodiagnostico: lead.seguimientoAutodiagnostico || '',
    // Primer apunte de seguimiento automático, igual que en el CRM de
    // comunidades, para que quede trazabilidad de cuándo entró el contacto.
    seguimiento: [{ fecha: hoy, texto: 'Lead pasado a CRM' }],
  };
  // Si el lead ya respondió la auditoría pública, se traslada tal cual al
  // nuevo contacto — así no hay que volver a preguntarle nada.
  if (lead.auditoriaPublicaCompletada && lead.auditoriaPublicaRespuesta) {
    obj.auditoria = lead.auditoriaPublicaRespuesta;
    obj.auditoriaRealizada = true;
    obj.numEmpleados = lead.auditoriaPublicaRespuesta.numTrabajadores || 0;
  }
  if (!Array.isArray(data.contactosSP)) data.contactosSP = [];
  data.contactosSP.push(obj);
  lead.estado = 'Pasado a CRM';
  lead.contactoCrmId = obj.id;
  // Sin este apunte, el contacto no aparecía en "Nuevos contactos" de
  // Estadísticas (ni en Empresas Potenciales ni en Prescriptores) — antes
  // solo se registraba al crear la ficha a mano desde "Nueva propuesta".
  if (!Array.isArray(data.crmSPActividad)) data.crmSPActividad = [];
  data.crmSPActividad.push({ id: uid(), contactoId: obj.id, tipo: 'nuevo_contacto', fecha: hoy, comercial: obj.responsable, origen: obj.origen });
  saveData(['contactosSP','leadsSP','crmSPActividad']);
  renderLeadsSP();
  showToast('Lead convertido en propuesta ✓');
}

/* ═══════════════════════════════════════════════════
   ALTA / IMPORTACIÓN DE LEADS + ENLACE PÚBLICO DE AUDITORÍA
   ═══════════════════════════════════════════════════ */
// Token largo y aleatorio — es lo único que da acceso al formulario
// público, así que no puede ser adivinable (nada de IDs correlativos).
function crmspGenerarTokenPublico() {
  return Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,10) + Math.random().toString(36).slice(2,10);
}

function abrirModalLeadSP(id) {
  const l = id ? (data.leadsSP||[]).find(x=>x.id===id) || {} : {};
  const origenOpts = CRMSP_ORIGENES.map(o => `<option value="${esc(o)}" ${l.origen===o?'selected':''}>${esc(o)}</option>`).join('');
  const body = `<div class="crm-form-grid" style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px;">
    <div class="form-group" style="grid-column:1/-1;"><label>Estado</label>
      <select id="lead-estado">
        ${CRMSP_LEADS_ESTADOS.map(e=>`<option value="${e}" ${l.estado===e?'selected':''}>${esc(CRMSP_LEADS_ESTADO_LABELS[e]||e)}</option>`).join('')}
      </select>
    </div>
    <div class="form-group"><label>Nombre de la Empresa *</label><input type="text" id="lead-empresa" value="${esc(l.empresa||'')}"></div>
    <div class="form-group"><label>CIF</label><input type="text" id="lead-cif" value="${esc(l.cif||'')}" autocomplete="off"></div>
    <div class="form-group"><label>Persona de contacto</label><input type="text" id="lead-contacto" value="${esc(l.contacto||'')}"></div>
    <div class="form-group"><label>Teléfono</label><input type="text" id="lead-telefono" value="${esc(l.telefono||'')}"></div>
    <div class="form-group"><label>Email</label><input type="email" id="lead-email" value="${esc(l.email||'')}"></div>
    <div class="form-group"><label>Dirección</label><input type="text" id="lead-direccion" value="${esc(l.direccion||'')}" autocomplete="off"></div>
    <div class="form-group"><label>Municipio</label><input type="text" id="lead-poblacion" value="${esc(l.poblacion||'')}" placeholder="Ciudad" autocomplete="off"></div>
    <div class="form-group"><label>Responsable interno</label>
      <select id="lead-resp"><option value="">— Selecciona —</option>${getUsuariosNombresCRMSP().map(n=>`<option value="${esc(n)}" ${l.responsable===n?'selected':''}>${esc(n)}</option>`).join('')}</select>
    </div>
    <div class="form-group"><label>Origen</label><select id="lead-origen"><option value="">— Selecciona —</option>${origenOpts}</select></div>
    <div class="form-group"><label>Prescriptor</label>
      <select id="lead-prescriptor">
        <option value="">— Sin prescriptor —</option>
        ${(data.prescriptoresSP||[]).slice().sort((a,b)=>(a.nombre||'').localeCompare(b.nombre||'')).map(p => `<option value="${esc(p.nombre)}" ${l.prescriptor===p.nombre?'selected':''}>${esc(p.nombre)}</option>`).join('')}
      </select>
    </div>
    <div class="form-group" style="grid-column:1/-1;"><label>Notas</label><textarea id="lead-notas" style="min-height:60px;">${esc(l.notas||'')}</textarea></div>

    <div class="form-group" style="grid-column:1/-1;">
      <label>Autodiagnóstico de necesidades</label>
      <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12px;background:var(--bg);border:1px solid var(--border);border-radius:var(--r);padding:10px 12px;">
        <span>
          ${l.auditoriaPublicaCompletada
            ? `<span style="color:#065F46;font-weight:600;">✓ Autodiagnóstico realizado</span>${l.auditoriaPublicaRespuesta?.fecha ? ' · '+esc(fmtDate(l.auditoriaPublicaRespuesta.fecha)) : ''}`
            : '<span style="color:var(--muted);">Todavía no ha respondido el autodiagnóstico.</span>'}
        </span>
        <div style="display:flex;gap:6px;flex-wrap:wrap;">
          ${id ? `<button type="button" onclick="crmspEnviarAutodiagnosticoSP('lead','${id}')" class="btn-sm"><i class="ti ti-link" style="font-size:12px;" aria-hidden="true"></i> Enviar autodiagnóstico</button>` : ''}
          ${id ? `<button type="button" onclick="abrirModalAuditoriaSP('${id}','lead')" class="btn-sm"><i class="ti ${l.auditoriaPublicaCompletada?'ti-edit':'ti-clipboard-plus'}" style="font-size:12px;" aria-hidden="true"></i> Editar encuesta</button>` : ''}
          ${!id ? '<span style="font-size:11px;color:var(--muted);">Guarda el lead primero</span>' : ''}
        </div>
      </div>
      <div style="margin-top:8px;">
        <label style="font-size:11px;color:var(--muted);">Seguimiento del autodiagnóstico</label>
        <div style="margin-top:4px;">${_badgeSeguimientoAuditoriaSP(l.seguimientoAutodiagnostico)}</div>
        <div style="font-size:10.5px;color:var(--muted);margin-top:5px;">Se actualiza solo: pasa a "Enviado" al mandar el enlace, y a "Solicita Llamada"/"Quiere Contratar" en cuanto el cliente responde el autodiagnóstico — no se puede editar a mano.</div>
      </div>
    </div>

    ${id ? `<div style="grid-column:1/-1;margin-top:10px;"><button type="button" onclick="eliminarLeadSP('${id}')" style="font-size:12px;color:var(--danger);background:none;border:none;cursor:pointer;"><i class="ti ti-trash" style="font-size:13px;"></i> Eliminar lead</button></div>` : ''}
  </div>`;

  _modalCustomCallback = () => {
    const empresa = document.getElementById('lead-empresa')?.value?.trim();
    if (!empresa) { alert('El nombre de la empresa es obligatorio.'); return; }
    const estadoElegido = document.getElementById('lead-estado')?.value || 'Sin contactar';
    const yaConvertido = !!l.contactoCrmId;
    // Si se elige "Pasado a CRM" a mano y todavía no se había convertido,
    // no basta con guardar el texto del estado — hay que generar también
    // el contacto en Empresas Potenciales (mismo camino que el botón
    // "Pasar a propuesta" de la lista), o si no el lead queda marcado como
    // pasado sin que exista ningún contacto real detrás.
    const disparaConversion = estadoElegido === 'Pasado a CRM' && !yaConvertido;
    const obj = {
      id: id || 'leadsp' + Date.now(),
      empresa,
      cif: document.getElementById('lead-cif')?.value?.trim() || '',
      contacto: document.getElementById('lead-contacto')?.value?.trim() || '',
      telefono: document.getElementById('lead-telefono')?.value?.trim() || '',
      email: document.getElementById('lead-email')?.value?.trim() || '',
      direccion: document.getElementById('lead-direccion')?.value?.trim() || '',
      poblacion: document.getElementById('lead-poblacion')?.value?.trim() || '',
      responsable: document.getElementById('lead-resp')?.value || '',
      origen: document.getElementById('lead-origen')?.value || '',
      prescriptor: document.getElementById('lead-prescriptor')?.value || '',
      estado: disparaConversion ? (l.estado || 'Sin contactar') : estadoElegido,
      notas: document.getElementById('lead-notas')?.value?.trim() || '',
      publicToken: l.publicToken || crmspGenerarTokenPublico(),
      auditoriaPublicaCompletada: l.auditoriaPublicaCompletada || false,
      auditoriaPublicaRespuesta: l.auditoriaPublicaRespuesta || null,
      seguimientoAutodiagnostico: l.seguimientoAutodiagnostico || '', // automático — no se edita desde aquí
      contactoCrmId: l.contactoCrmId || null,
    };
    if (!Array.isArray(data.leadsSP)) data.leadsSP = [];
    const idx = data.leadsSP.findIndex(x=>x.id===obj.id);
    if (idx>=0) data.leadsSP[idx] = obj; else data.leadsSP.push(obj);
    saveData(['leadsSP']);
    closeModal();
    if (disparaConversion) {
      convertirLeadACRMSP(obj.id); // ya hace su propio saveData/render/toast
    } else {
      renderLeadsSP();
      showToast(id ? 'Lead actualizado ✓' : 'Lead creado ✓');
    }
  };

  openModalCustom(id ? 'Editar lead' : 'Nuevo lead', body);
  document.querySelector('.modal')?.classList.add('modal-wide');
}

function eliminarLeadSP(id) {
  if (!confirm('¿Eliminar este lead? Esta acción no se puede deshacer.')) return;
  data.leadsSP = (data.leadsSP||[]).filter(l => l.id !== id);
  saveData(['leadsSP']);
  closeModal();
  renderLeadsSP();
  showToast('Lead eliminado');
}

// Tabla de selección de gestoría antes de importar leads — así cada lead
// importado queda vinculado desde el origen a la gestoría que lo trajo
// (campo "prescriptor", el mismo que ya usa el resto del CRM SP), en vez de
// tener que asignarlo a mano lead a lead después. Sustituye a lo que antes
// era un botón directo a "Importar leads" sin vincular.
function abrirModalSeleccionGestoriaImportarLeadsSP() {
  const body = `
    <p style="font-size:12px;color:var(--muted);margin:0 0 12px;">Elige la gestoría de la que vienen estos leads — quedarán vinculados a ella automáticamente (campo "Prescriptor"), para poder ver después la trazabilidad completa de cada gestoría y sus leads.</p>
    <div class="form-group"><input type="text" id="import-leads-gestoria-buscar" placeholder="🔎 Buscar gestoría..." autocomplete="off" oninput="renderSeleccionGestoriaImportarLeadsSP()"></div>
    <div id="import-leads-gestoria-tabla"></div>
    <div style="margin-top:14px;padding-top:12px;border-top:1px solid var(--border);text-align:center;">
      <button type="button" onclick="closeModal();abrirModalImportarLeadsSP()" style="font-size:12px;color:var(--muted);background:none;border:none;cursor:pointer;text-decoration:underline;">Importar sin vincular a ninguna gestoría</button>
    </div>`;

  _modalCustomCallback = () => { closeModal(); };
  openModalCustom('Importar leads — elige la gestoría', body);
  document.querySelector('.modal')?.classList.remove('modal-wide');
  renderSeleccionGestoriaImportarLeadsSP();
}

function renderSeleccionGestoriaImportarLeadsSP() {
  const el = document.getElementById('import-leads-gestoria-tabla');
  if (!el) return;
  const buscar = _normalizarBusqueda(document.getElementById('import-leads-gestoria-buscar')?.value?.trim() || '');
  let lista = (data.prescriptoresSP||[]).slice();
  if (buscar) lista = lista.filter(g => _normalizarBusqueda(g.nombre||'').includes(buscar));
  lista.sort((a,b) => (a.nombre||'').localeCompare(b.nombre||''));

  if (!lista.length) {
    el.innerHTML = `<p style="font-size:13px;color:var(--muted);padding:16px 0;text-align:center;">${(data.prescriptoresSP||[]).length ? 'Ninguna gestoría coincide con la búsqueda.' : 'Todavía no hay ninguna gestoría dada de alta en Prescriptores.'}</p>`;
    return;
  }

  const filas = lista.map(g => {
    const ec = CRMSPPRES_ETAPA_COLOR[g.etapa] || {bg:'#F3F4F6',color:'#6B7280'};
    const nLeads = (data.leadsSP||[]).filter(l => _prescriptorCoincide(l.prescriptor, g.nombre)).length;
    return `<tr onclick="closeModal();abrirModalImportarLeadsSP('${esc(g.nombre).replace(/'/g,"\\'")}')" style="cursor:pointer;">
      <td style="text-align:left;font-weight:600;">${esc(g.nombre)}</td>
      <td style="text-align:center;"><span style="font-size:11px;padding:3px 8px;border-radius:10px;background:${ec.bg};color:${ec.color};font-weight:600;">${esc(g.etapa)}</span></td>
      <td style="text-align:center;">${nLeads}</td>
    </tr>`;
  }).join('');

  el.innerHTML = `<div class="crm-table-wrap" style="max-height:320px;"><table class="crm-table">
    <thead><tr><th style="text-align:left;">Gestoría</th><th style="text-align:center;">Estado</th><th style="text-align:center;" title="Leads ya vinculados a esta gestoría">Leads vinculados</th></tr></thead>
    <tbody>${filas}</tbody>
  </table></div>`;
}

// Alias de cabeceras compatibles con leadsSP, reutilizando el mismo Excel
// "Pipeline clientes" que ya se usa para importar Empresas Potenciales —
// aquí solo se toman los campos que un lead puede tener (sin etapa de
// pipeline, probabilidad, servicios ni importe, que son ya propios del
// CRM y se rellenan al convertir el lead con "Pasar a propuesta").
const LEADSP_IMPORT_CAMPOS = {
  empresa:     ['nombredelaempresa', 'empresa', 'nombreempresa', 'razonsocial'],
  cif:         ['cif', 'nif'],
  contacto:    ['personadecontacto', 'contacto', 'nombrecontacto'],
  telefono:    ['telefono', 'tel', 'movil'],
  email:       ['email', 'correo', 'correoelectronico', 'mail'],
  direccion:   ['direccion', 'domicilio'],
  poblacion:   ['municipio', 'poblacion', 'ciudad'],
  origen:      ['origen'],
  prescriptor: ['prescriptor', 'gestoria'],
  responsable: ['responsable', 'comercial'],
  comentarios: ['comentariosgeneralesdelcliente', 'comentariosgenerales', 'comentarios', 'observaciones', 'notas'],
};

let _leadsSPImportExcelPendiente = null;

function abrirModalImportarLeadsSP(prescriptorNombre) {
  _leadsSPImportExcelPendiente = null;
  const contextoHTML = prescriptorNombre ? `<div style="display:flex;align-items:center;gap:8px;background:#EFF6FF;border:1px solid #BFDBFE;border-radius:var(--r);padding:8px 12px;margin-bottom:12px;font-size:12px;color:#1D4ED8;">
    <i class="ti ti-link" style="font-size:14px;flex-shrink:0;"></i>
    <span>Estos leads quedarán vinculados a <strong>${esc(prescriptorNombre)}</strong> (campo Prescriptor), para poder ver su trazabilidad después.</span>
  </div>` : '';
  const body = `
    ${contextoHTML}
    <div style="font-size:11px;font-weight:700;color:var(--purple);text-transform:uppercase;letter-spacing:0.05em;margin:0 0 10px;padding-bottom:6px;border-bottom:2px solid var(--purple-l);">Opción A · Subir Excel</div>
    <p style="font-size:12px;color:var(--muted);margin:0 0 10px;">Mismo formato que el de Empresas Potenciales: Nombre de la empresa, CIF, Persona de contacto, Teléfono, Email, Origen, Prescriptor, Responsable, Comentarios generales del cliente (las columnas de pipeline/servicios/importe no aplican a un lead — se usan al convertirlo con "Pasar a propuesta").</p>
    <div class="form-group"><input type="file" id="import-leadssp-file" accept=".xlsx,.xls"></div>
    <div id="import-leadssp-preview" style="font-size:12px;color:var(--muted);margin-bottom:16px;"></div>

    <div style="font-size:11px;font-weight:700;color:var(--purple);text-transform:uppercase;letter-spacing:0.05em;margin:0 0 10px;padding-bottom:6px;border-bottom:2px solid var(--purple-l);">Opción B · Pegar texto</div>
    <p style="font-size:12px;color:var(--muted);margin:0 0 12px;">Uno por línea, separado por punto y coma:<br><code>Empresa;Persona de contacto;Email;Teléfono</code><br>Los campos que no tengas se pueden dejar vacíos, pero mantén los 4 separadores.</p>
    <div class="form-group"><textarea id="import-leads-texto" placeholder="Comunidad Els Til.lers;Juan Pérez;juan@ejemplo.com;600111222&#10;Otra Empresa SL;;info@otra.com;" style="min-height:120px;font-family:monospace;font-size:12px;"></textarea></div>`;

  _modalCustomCallback = () => {
    if (!Array.isArray(data.leadsSP)) data.leadsSP = [];
    let creados = 0;

    (_leadsSPImportExcelPendiente || []).forEach(l => { data.leadsSP.push(l); creados++; });

    const texto = document.getElementById('import-leads-texto')?.value || '';
    const lineas = texto.split('\n').map(l=>l.trim()).filter(Boolean);
    lineas.forEach(linea => {
      const [empresa, contacto, email, telefono] = linea.split(';').map(v => (v||'').trim());
      if (!empresa) return;
      data.leadsSP.push({
        id: 'leadsp' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
        empresa, cif: '', contacto: contacto||'', email: email||'', telefono: telefono||'',
        origen: '', prescriptor: prescriptorNombre || '', responsable: '', estado: 'Sin contactar', notas: '',
        publicToken: crmspGenerarTokenPublico(),
        auditoriaPublicaCompletada: false, auditoriaPublicaRespuesta: null,
      });
      creados++;
    });

    if (!creados) { showToast('No hay ningún lead que importar (sube un Excel o pega texto)'); return; }
    saveData(['leadsSP']);
    closeModal();
    _leadsSPImportExcelPendiente = null;
    renderLeadsSP();
    showToast(`${creados} lead(s) importado(s)${prescriptorNombre?` y vinculado(s) a ${prescriptorNombre}`:''} ✓`);
  };

  openModalCustom(prescriptorNombre ? `Importar leads — ${prescriptorNombre}` : 'Importar leads', body);
  document.querySelector('.modal')?.classList.remove('modal-wide');

  document.getElementById('import-leadssp-file')?.addEventListener('change', e => {
    const file = e.target.files[0];
    if (file) _procesarExcelImportLeadsSP(file, prescriptorNombre);
  });
}

function _procesarExcelImportLeadsSP(file, prescriptorNombre) {
  const preview = document.getElementById('import-leadssp-preview');
  if (preview) preview.innerHTML = 'Leyendo archivo...';

  const reader = new FileReader();
  reader.onload = e => {
    try {
      const wb = XLSX.read(e.target.result, { type: 'array' });
      const nombreHoja = wb.SheetNames.find(n => _normalizarCabecera(n).includes('pipeline')) || wb.SheetNames[0];
      const filas = XLSX.utils.sheet_to_json(wb.Sheets[nombreHoja], { defval: '' });

      const pendientes = [];
      filas.forEach((fila, i) => {
        const m = _mapearFilaImportGenerico(fila, LEADSP_IMPORT_CAMPOS);
        if (!m.empresa) return; // sin nombre de empresa no hay fila válida
        pendientes.push({
          id: 'leadsp' + Date.now() + '_' + i + Math.random().toString(36).slice(2,6),
          empresa: m.empresa,
          cif: m.cif || '',
          contacto: m.contacto || '',
          telefono: m.telefono || '',
          email: m.email || '',
          direccion: m.direccion || '',
          poblacion: m.poblacion || '',
          origen: m.origen || '',
          // Si se ha elegido una gestoría en el paso anterior, manda sobre
          // lo que traiga la columna "Prescriptor" del Excel (es justo lo
          // que se pidió al elegirla) — si no se eligió ninguna (import "sin
          // vincular"), se respeta el valor de esa columna, fila a fila.
          prescriptor: prescriptorNombre || m.prescriptor || '',
          responsable: m.responsable || '',
          estado: 'Sin contactar',
          notas: m.comentarios || '',
          publicToken: crmspGenerarTokenPublico(),
          auditoriaPublicaCompletada: false, auditoriaPublicaRespuesta: null,
        });
      });

      _leadsSPImportExcelPendiente = pendientes;
      const preview = document.getElementById('import-leadssp-preview');
      if (!preview) return;
      preview.innerHTML = pendientes.length
        ? `<strong style="color:var(--purple);">${pendientes.length} lead(s)</strong> detectado(s) en el Excel y listo(s) para importar. Pulsa "Guardar" para confirmar.`
        : `<span style="color:var(--danger);">No se ha encontrado ninguna fila con "Nombre de la empresa" en la hoja "${esc(nombreHoja)}".</span>`;
    } catch (err) {
      _leadsSPImportExcelPendiente = null;
      const preview = document.getElementById('import-leadssp-preview');
      if (preview) preview.innerHTML = `<span style="color:var(--danger);">Error leyendo el archivo: ${esc(err?.message || err)}</span>`;
    }
  };
  reader.readAsArrayBuffer(file);
}

function getLinkAuditoriaPublicaSP(lead) {
  const base = location.origin + location.pathname;
  return `${base}?auditoria=${encodeURIComponent(lead.publicToken)}&empresa=${encodeURIComponent(lead.empresa||'')}&contacto=${encodeURIComponent(lead.contacto||'')}`;
}


// Mapeo de las claves del cuestionario público de autodiagnóstico a las
// claves reales del tarifario — el cuestionario usa nombres más simples
// ("rgpd") que no coinciden 1:1 con las claves del catálogo de precios.
const CRMSP_AUDITORIA_A_TARIFA = {
  rgpd: 'consult_lopd_empresa',
  lssice: 'lssice',
  registro_horario: 'registro_horario',
  prl: 'prl_autogestion',
  acoso: 'acoso_adaptacion',
};

// Decide qué paquete encaja mejor con el perfil respondido en el
// autodiagnóstico — mismos segmentos que ya usan las notas de cada
// paquete en Tarifas 2026 (Esencial: sin empleados · Profesional: con
// empleados · Profesional Plus: actividad de alimentación).
function crmspPaqueteSugeridoPorRespuesta(r) {
  // OJO: manejaAlimentos se guarda como 'Si'/'No' (con mayúscula) tanto
  // desde el modal interno como desde el formulario público — comparar en
  // minúsculas aquí hacía que este caso nunca se detectase.
  if (String(r?.manejaAlimentos||'').toLowerCase() === 'si') return 'paquete_profesional_plus';
  if (Number(r?.numTrabajadores) >= 1) return 'paquete_profesional';
  return 'paquete_esencial';
}

// Obligaciones normativas evaluables a partir de las respuestas del
// autodiagnóstico — cada una indica si aplica a esta empresa concreta
// (según su perfil) y si ya la tiene cubierta (según los "servicios
// contratados actualmente" que ha marcado). Se usan tanto para el
// informe de resultados público (grado de cumplimiento) como para el
// PDF descargable. No incluye "formación RGPD" porque no es en sí misma
// una obligación legal (es un servicio recomendado, no exigible).
const CRMSP_AUDITORIA_OBLIGACIONES = [
  { key:'rgpd', label:'Protección de Datos (RGPD/LOPDGDD)', aplica: () => true },
  { key:'lssice', label:'Adaptación LSSICE (web / comercio electrónico)', aplica: r => r?.tieneWeb === 'Si' },
  { key:'registro_horario', label:'Registro horario', aplica: r => Number(r?.numTrabajadores) >= 1 },
  { key:'prl', label:'Prevención de Riesgos Laborales', aplica: r => Number(r?.numTrabajadores) >= 1 },
  { key:'acoso', label:'Prevención del Acoso Sexual y por Razón de Sexo', aplica: r => Number(r?.numTrabajadores) >= 1 },
];

// Descripciones para el paquete recomendado en la página pública de
// resultados — se generan a partir de SP_TARIFAS_2026 (fuente única de
// precios/contenido, la misma que usan las propuestas internas), nunca
// hardcodeadas aquí, para que si cambia un precio o el detalle de un
// paquete en Tarifas 2026 el informe público se actualice solo.
function crmspInfoPaquetePublicoSP(paqueteKey, r) {
  const item = getSPTarifaItem(paqueteKey);
  if (!item) return null;
  // Los paquetes "paquete_compuesto" no tienen un precio fijo: se calculan
  // según el nº de empleados/usuarios de la respuesta del autodiagnóstico
  // (misma función que usan las propuestas internas).
  const inputs = { empleados: Number(r?.numTrabajadores)||0, usuarios: Number(r?.numUsuarios)||0 };
  const calc = calcularPrecioTarifaSP(paqueteKey, inputs);
  return {
    key: paqueteKey,
    nombre: spNombreCliente(item.nombre),
    nota: item.nota || '',
    precio: calc.precio,
    iva: !!item.iva,
    bullets: (item.detalleServicios||'').split('·').map(s=>s.trim()).filter(Boolean),
  };
}

// Desglose "por separado" del paquete recomendado — cada servicio incluido
// en el paquete (item.componentes, la misma lista que se usa para calcular
// el precio del paquete) con su precio individual real de Tarifas 2026
// (según el nº de trabajadores y usuarios que ha indicado el cliente), para
// poder mostrar después el ahorro real de contratar el paquete frente a
// contratarlos uno a uno.
function crmspDesglosePreciosPaqueteSP(paqueteKey, r) {
  const item = getSPTarifaItem(paqueteKey);
  const componentes = item?.componentes || [];
  const inputsComunes = { empleados: Number(r?.numTrabajadores)||0, usuarios: Number(r?.numUsuarios)||0 };
  const items = componentes.map(tarifaKey => {
    const tItem = getSPTarifaItem(tarifaKey);
    const calc = calcularPrecioTarifaSP(tarifaKey, inputsComunes);
    return { label: tItem ? spNombreCliente(tItem.nombre) : tarifaKey, precio: calc.precio, iva: calc.iva };
  }).filter(it => it.precio != null); // fuera de tramo / a consultar → no se suma, no se inventa
  const sumaSeparado = items.reduce((acc,it) => acc + it.precio, 0);
  return {
    items,
    sumaSeparado,
    // Nota honesta para lo que el paquete incluye pero no tiene tarifa
    // individual computable (evita insinuar que el paquete "sale más caro"
    // cuando en realidad trae más cosas gratis dentro del precio cerrado).
    notaExtras: paqueteKey === 'paquete_profesional_plus'
      ? 'Incluye además mantenimiento APPCC, plan de alérgenos y carnets de manipulador, sin coste añadido.'
      : (paqueteKey === 'paquete_esencial' || paqueteKey === 'paquete_profesional')
        ? 'Incluye además certificado digital, notificaciones, plataforma y gestor, sin coste añadido.'
        : '',
  };
}

// Evalúa el grado de cumplimiento a partir de una respuesta de
// autodiagnóstico (público o interno) — usada para pintar el informe de
// resultados nada más enviar el formulario, sin esperar a que nadie del
// equipo lo revise.
function evaluarAutodiagnosticoPublicoSP(r) {
  const contratados = Array.isArray(r?.serviciosInteres) ? r.serviciosInteres : [];
  const areas = CRMSP_AUDITORIA_OBLIGACIONES
    .map(o => ({ key:o.key, label:o.label, cumple: contratados.includes(o.key) }))
    .filter((_, i) => CRMSP_AUDITORIA_OBLIGACIONES[i].aplica(r));
  const totalAplican = areas.length;
  const totalCumplen = areas.filter(a=>a.cumple).length;
  const porcentaje = totalAplican ? Math.round((totalCumplen/totalAplican)*100) : 100;
  const paqueteKey = crmspPaqueteSugeridoPorRespuesta(r);
  const paquete = crmspInfoPaquetePublicoSP(paqueteKey, r);
  if (paquete) paquete.desglose = crmspDesglosePreciosPaqueteSP(paqueteKey, r);
  return {
    areas, totalAplican, totalCumplen, porcentaje, paqueteKey, paquete,
    // Seguridad alimentaria no se cuenta en el % (no hay checkbox propio
    // que confirme si ya la tienen cubierta), pero si aplica se avisa
    // igualmente como nota informativa — la incluye Profesional Plus.
    seguridadAlimentaria: String(r?.manejaAlimentos||'').toLowerCase() === 'si',
    // Contexto para la caja de "¿quién puede autogestionar la
    // prevención?" en el informe — solo tiene sentido mostrarla si la
    // empresa tiene empleados (si no, la PRL ni siquiera les aplica).
    mostrarAutogestion: Number(r?.numTrabajadores) >= 1,
  };
}

// Genera automáticamente una propuesta (el paquete que mejor encaja según
// las respuestas) — deja todo listo en la ficha para que solo haga falta
// revisarlo y enviarlo con un clic, en vez de armarlo desde cero a mano.
function crmspAutoGenerarPropuestaDesdeAuditoria(obj, r) {
  const paqueteKey = crmspPaqueteSugeridoPorRespuesta(r);
  const paquete = getSPTarifaItem(paqueteKey);
  if (!paquete) return;
  obj.serviciosOfertados = [{
    key: paqueteKey, nombre: paquete.nombre, inputs: {},
    precio: paquete.precio, precioTarifa: paquete.precio,
    detalle: 'Paquete sugerido automáticamente a partir del autodiagnóstico',
    iva: paquete.iva, comisionPrescriptor: 0, comisionManual: false,
  }];
  obj.importePropuesta = paquete.precio;
  obj.propuestaAutoGenerada = true;
  obj.propuestaAutoGeneradaFecha = new Date().toISOString().slice(0,10);
}

// Procesa una respuesta de autodiagnóstico recién llegada (o cambiada):
// marca el lead como respondido, lo convierte automáticamente en contacto
// CRM si todavía no lo estaba (para no depender de que alguien pulse
// "Pasar a propuesta" a mano), y genera la propuesta sugerida. Devuelve
// true si se ha procesado algo nuevo — la usan tanto el botón manual como
// la escucha en tiempo real, para no duplicar la lógica en dos sitios.
// Mismo procesamiento que _procesarRespuestaAuditoriaSP, pero para un
// CONTACTO que nunca pasó por la fase de lead (se creó directamente desde
// "Contactos Comerciales" y se le envió el autodiagnóstico desde su
// propia ficha). Los contactos guardan la respuesta en "auditoria" (no
// "auditoriaPublicaRespuesta", que es el campo que usan los leads) — por
// eso hacía falta esta rama aparte en vez de reutilizar la misma lógica.
function _procesarRespuestaAuditoriaContactoDirectoSP(token, respuesta) {
  const contacto = (data.contactosSP||[]).find(c => c.publicToken === token);
  if (!contacto) return false;

  const yaCompletada = !!contacto.auditoriaRealizada;
  const interesCambio = yaCompletada
    && contacto.auditoria?.interesContratacion !== respuesta.interesContratacion;

  contacto.auditoria = respuesta;

  if (interesCambio) {
    contacto.seguimientoAutodiagnostico = respuesta.interesContratacion === true ? 'Quiere Contratar'
      : respuesta.interesContratacion === false ? 'Solicita Llamada'
      : contacto.seguimientoAutodiagnostico;
  }

  if (yaCompletada) return interesCambio ? 'interes' : false;

  contacto.auditoriaRealizada = true;
  crmspAutoGenerarPropuestaDesdeAuditoria(contacto, respuesta);
  _publicarPropuestaPublicaSP(contacto);
  return true;
}

function _procesarRespuestaAuditoriaSP(token, respuesta) {
  if (!respuesta) return false;
  const lead = (data.leadsSP||[]).find(l => l.publicToken === token);

  // Si no hay ningún lead con ese token, puede ser un CONTACTO creado
  // directamente en "Contactos Comerciales" (sin pasar nunca por un
  // lead) — a esos también se les puede enviar el autodiagnóstico desde
  // su propia ficha. Antes, si no aparecía en leadsSP, la respuesta del
  // cliente se descartaba sin más y nunca llegaba a nadie.
  if (!lead) return _procesarRespuestaAuditoriaContactoDirectoSP(token, respuesta);

  const yaCompletada = !!lead.auditoriaPublicaCompletada;
  // El cliente puede enviar el formulario y, unos segundos/minutos después,
  // pulsar "Quiero contratarlo" o "Prefiero que me llaméis" desde el
  // informe de resultados — eso llega como un CAMBIO posterior sobre el
  // mismo nodo (interesContratacion), no como una respuesta nueva. Hay que
  // seguir sincronizando esa respuesta aunque el lead ya estuviera
  // procesado, o el equipo nunca vería quién ha pedido contratar.
  const interesCambio = yaCompletada
    && lead.auditoriaPublicaRespuesta?.interesContratacion !== respuesta.interesContratacion;

  lead.auditoriaPublicaRespuesta = respuesta;
  const contactoVinculado = lead.contactoCrmId ? (data.contactosSP||[]).find(c => c.id === lead.contactoCrmId) : null;
  if (contactoVinculado) contactoVinculado.auditoria = respuesta;

  if (interesCambio) {
    // El cliente ha elegido en el informe de resultados — esto es lo que
    // decide el estado de seguimiento, no falta esperar a que nadie del
    // equipo lo revise a mano.
    const nuevoEstado = respuesta.interesContratacion === true ? 'Quiere Contratar'
      : respuesta.interesContratacion === false ? 'Solicita Llamada'
      : lead.seguimientoAutodiagnostico;
    lead.seguimientoAutodiagnostico = nuevoEstado;
    if (contactoVinculado) contactoVinculado.seguimientoAutodiagnostico = nuevoEstado;
  }

  if (yaCompletada) return interesCambio ? 'interes' : false;

  lead.auditoriaPublicaCompletada = true;
  lead.estado = lead.estado === 'Sin contactar' ? 'Contactado' : lead.estado;

  if (!Array.isArray(data.contactosSP)) data.contactosSP = [];
  let contacto = lead.contactoCrmId ? data.contactosSP.find(c => c.id === lead.contactoCrmId) : null;

  if (!contacto) {
    const hoy = new Date().toISOString().slice(0,10);
    contacto = {
      id: 'crmsp' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
      empresa: lead.empresa || respuesta.empresa || '', cif: lead.cif || '',
      contacto: lead.contacto || respuesta.contacto || '', telefono: lead.telefono || respuesta.telefono || '',
      email: lead.email || respuesta.email || '', direccion: lead.direccion || '', poblacion: lead.poblacion || '',
      origen: lead.origen || 'Autodiagnóstico', prescriptor: lead.prescriptor || '',
      etapa: 'Lead Migrado - Pdte. Contacto', probabilidad: '', numEmpleados: respuesta.numTrabajadores || 0,
      responsable: lead.responsable || '', fechaPropuesta: '', fechaProximaAccion: '',
      serviciosOfertados: [], importePropuesta: 0, comentariosGenerales: '', seguimiento: [],
      auditoria: null, auditoriaRealizada: false, motivoDescarte: null, motivoDescarteDetalle: '',
      publicToken: lead.publicToken, auditoriaPublicaCompletada: false, auditoriaPublicaRespuesta: null,
      seguimientoAutodiagnostico: lead.seguimientoAutodiagnostico || '',
    };
    data.contactosSP.push(contacto);
    lead.contactoCrmId = contacto.id;
    if (!Array.isArray(data.crmSPActividad)) data.crmSPActividad = [];
    data.crmSPActividad.push({ id: uid(), contactoId: contacto.id, tipo: 'nuevo_contacto', fecha: hoy, comercial: contacto.responsable, origen: contacto.origen });
  }

  contacto.auditoria = respuesta;
  contacto.auditoriaRealizada = true;
  crmspAutoGenerarPropuestaDesdeAuditoria(contacto, respuesta);
  _publicarPropuestaPublicaSP(contacto);
  return true;
}

// Escucha en tiempo real — desde que se activa (justo tras el login), toda
// respuesta nueva del autodiagnóstico se procesa sola, sin que nadie tenga
// que pulsar ningún botón de sincronizar.
let _refEscuchaAuditoriasSP = null;

function iniciarEscuchaAuditoriasPublicasSP() {
  if (!fbConnected || _refEscuchaAuditoriasSP) return;
  // OJO: "auditoriasPublicas" vive en la RAÍZ de la base de datos (el
  // formulario público, sin login, escribe ahí con otra instancia de la
  // app de Firebase) — no dentro de "holding-data", que es donde vive
  // fbRef. Referenciarlo con fbRef.child(...) apunta al sitio equivocado
  // y nunca encuentra nada.
  const ref = firebase.database().ref('auditoriasPublicas');
  _refEscuchaAuditoriasSP = ref;
  const onRespuesta = snap => {
    const resultado = _procesarRespuestaAuditoriaSP(snap.key, snap.val());
    if (!resultado) return;
    saveData(['leadsSP','contactosSP','crmSPActividad']);
    if (typeof renderLeadsSP === 'function') renderLeadsSP();
    if (typeof renderCRMSPFiltrosTabla === 'function') renderCRMSPFiltrosTabla();
    if (resultado === 'interes') {
      const lead = (data.leadsSP||[]).find(l => l.publicToken === snap.key);
      const contactoDirecto = !lead ? (data.contactosSP||[]).find(c => c.publicToken === snap.key) : null;
      const quiere = lead ? lead.auditoriaPublicaRespuesta?.interesContratacion : contactoDirecto?.auditoria?.interesContratacion;
      const nombre = lead?.empresa || contactoDirecto?.empresa || 'Un cliente';
      showToast(quiere
        ? `🔥 ${nombre} quiere contratar — contactad en menos de 48h`
        : `${nombre} pide que le llaméis para hacer seguimiento`);
    } else {
      showToast('Nuevo autodiagnóstico recibido — propuesta generada automáticamente ✓');
    }
  };
  ref.on('child_added', onRespuesta);
  ref.on('child_changed', onRespuesta);
  iniciarEscuchaPropuestasAceptadasSP();
}

// Detecta cuándo el cliente acepta la propuesta desde la página pública
// (?propuesta=<token>) y lo refleja en la ficha del contacto — sin que
// nadie tenga que ir a comprobarlo a mano.
let _refEscuchaPropuestasSP = null;

function iniciarEscuchaPropuestasAceptadasSP() {
  if (!fbConnected || _refEscuchaPropuestasSP) return;
  const ref = firebase.database().ref('propuestasPublicas');
  _refEscuchaPropuestasSP = ref;
  ref.on('child_changed', snap => {
    const prop = snap.val();
    if (!prop || !prop.aceptada) return;
    const contacto = (data.contactosSP||[]).find(c => c.publicToken === snap.key);
    if (!contacto || contacto.propuestaAceptada) return;
    contacto.propuestaAceptada = true;
    contacto.propuestaAceptadaFecha = prop.fechaAceptacion || new Date().toISOString().slice(0,10);
    saveData(['contactosSP']);
    if (typeof renderCRMSPFiltrosTabla === 'function') renderCRMSPFiltrosTabla();
    showToast(`✓ ${contacto.empresa} ha aceptado la propuesta — pendiente de formalizar la contratación`);
  });
}

// Botón manual de "Sincronizar" — se deja como red de seguridad (por si la
// escucha en tiempo real no llegó a activarse, p. ej. por haber entrado
// justo antes del login), pero ya no hace falta usarlo en el día a día.
async function sincronizarAuditoriasPublicasSP() {
  if (!fbConnected) { showToast('Necesitas conexión a Firebase para sincronizar'); return; }
  try {
    const snap = await firebase.database().ref('auditoriasPublicas').once('value');
    const val = snap.val() || {};
    let nuevas = 0, interesActualizado = 0;
    Object.keys(val).forEach(token => {
      const resultado = _procesarRespuestaAuditoriaSP(token, val[token]);
      if (resultado === true) nuevas++;
      else if (resultado === 'interes') interesActualizado++;
    });
    if (nuevas > 0 || interesActualizado > 0) {
      saveData(['leadsSP','contactosSP','crmSPActividad']);
      renderLeadsSP();
      if (typeof renderCRMSPFiltrosTabla === 'function') renderCRMSPFiltrosTabla();
      if (typeof renderCRMSPAuditoria === 'function') renderCRMSPAuditoria();
    }
    showToast(nuevas > 0 || interesActualizado > 0
      ? `${nuevas} autodiagnóstico(s) nuevo(s) · ${interesActualizado} interés(es) actualizado(s) ✓`
      : 'No hay respuestas nuevas');
  } catch (err) {
    showToast('Error al sincronizar: ' + (err?.message || err));
  }
}

/* ═══════════════════════════════════════════════════
   OKR (versión simplificada, propia del módulo)
   ═══════════════════════════════════════════════════ */
// Métricas disponibles para el OKR de CRM Serv. Profesionales — mismo
// patrón que CRM_OKR_METRICAS (Comunidades), con su propio color.
const CRMSP_OKR_METRICAS = [
  { key:'nuevos_contactos',      label:'Nuevos contactos',           formato:'num', color:'#F59E0B' },
  { key:'contactos_seguimiento', label:'Contactos de seguimiento',   formato:'num', color:'#1D4ED8' },
  { key:'propuestas_enviadas',   label:'Propuestas enviadas',        formato:'num', color:'#6D28D9' },
  { key:'clientes_captados',     label:'Clientes captados',          formato:'num', color:'#0F7A5C' },
  { key:'facturacion',           label:'Facturación captada',        formato:'eur', color:'#3457B2' },
];

function getCRMSPOkrObjetivo(key) {
  const raw = (data.crmSPOkrObjetivos || {})[key];
  if (raw && typeof raw === 'object') {
    return {
      final: { valor: Number(raw.final?.valor) || 0, fecha: raw.final?.fecha || '' },
      metas: Array.isArray(raw.metas) ? raw.metas.map(m => ({ valor: Number(m.valor)||0, fecha: m.fecha||'' })) : [],
      fechaCreacion: raw.fechaCreacion || '',
    };
  }
  return { final: { valor: Number(raw) || 0, fecha: '' }, metas: [], fechaCreacion: '' };
}

function getCRMSPOkrRealValor(key) {
  const contactos = getCRMSPVisibles();
  const captados = contactos.filter(c => c.etapa === 'Cliente Captado');
  // Estas dos se calculan sobre los propios contactos (no sobre el log de
  // actividad crmSPActividad), para que no arrastren el hueco histórico de
  // los contactos que se importaron o se convirtieron desde un lead antes
  // de que ese registro se corrigiera.
  if (key === 'nuevos_contactos') return contactos.length;
  if (key === 'contactos_seguimiento') return contactos.reduce((s,c) => s + (c.seguimiento?.length || 0), 0);
  if (key === 'propuestas_enviadas') return contactos.filter(c => !!c.fechaPropuesta).length;
  if (key === 'clientes_captados') return captados.length;
  if (key === 'facturacion') return captados.reduce((s,c) => s + (c.importeCerrado || c.importePropuesta || 0), 0);
  return 0;
}

// Reutiliza tal cual crmOkrFmt/crmOkrBarra/crmOkrEstadoCheckpoint/crmOkrProyeccion
// (definidas en el bloque del CRM Comunidades) — son genéricas, no dependen de nada
// propio de ese módulo.
function crmSPOkrMetricaHTML(m) {
  const objetivo = getCRMSPOkrObjetivo(m.key);
  const real = getCRMSPOkrRealValor(m.key);
  const puedeEditar = can('canConfig');
  const checkpoints = [...objetivo.metas.map(x => ({ ...x, esFinal: false })), { ...objetivo.final, esFinal: true }]
    .filter(cp => cp.valor > 0)
    .sort((a,b) => (a.fecha||'9999').localeCompare(b.fecha||'9999'));

  return `<div style="margin-bottom:18px;padding-bottom:16px;border-bottom:1px solid var(--border);">
    <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px;">
      <span style="font-size:12px;font-weight:600;">${esc(m.label)}</span>
      <span style="font-size:13px;display:flex;align-items:center;gap:8px;">
        <b style="color:${m.color};">${crmOkrFmt(real, m.formato)}</b>
        <span style="color:var(--muted);">/ ${objetivo.final.valor ? crmOkrFmt(objetivo.final.valor, m.formato) + (objetivo.final.fecha ? ' ('+fmtFechaCorta(new Date(objetivo.final.fecha+'T00:00:00').getTime())+')' : '') : 'sin objetivo'}</span>
        ${puedeEditar ? `<button onclick="abrirModalObjetivoOkrSP('${m.key}')" class="btn-sm" style="padding:2px 8px;" title="Editar objetivo"><i class="ti ti-edit" style="font-size:11px;"></i></button>` : ''}
      </span>
    </div>
    ${crmOkrBarra(real, objetivo.final.valor, m.color)}
    ${checkpoints.length ? `<div style="display:flex;flex-direction:column;gap:8px;margin-top:10px;">
      ${checkpoints.map(cp => {
        const est = crmOkrEstadoCheckpoint(real, cp.valor, cp.fecha);
        const avancePct = cp.valor > 0 ? Math.round(Math.min(100, real / cp.valor * 100)) : 0;
        const proy = crmOkrProyeccion(real, cp.valor, cp.fecha, objetivo.fechaCreacion);
        const proyColor = proy ? (proy.pct >= 100 ? '#0F7A5C' : proy.pct >= 70 ? '#3457B2' : '#A85C48') : null;
        return `<div style="background:var(--bg);border:1px solid var(--border);border-radius:10px;padding:9px 11px;">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:7px;">
            <span style="font-size:11px;font-weight:600;">${cp.esFinal ? '🏁 Meta final' : '🚩 Meta volante'} — ${crmOkrFmt(cp.valor, m.formato)}${cp.fecha ? ' · '+fmtFechaCorta(new Date(cp.fecha+'T00:00:00').getTime()) : ''}</span>
            <span style="font-size:10px;font-weight:700;padding:3px 9px;border-radius:12px;background:${est.bg};color:${est.color};white-space:nowrap;">${est.label}</span>
          </div>
          <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
            <div style="flex:1;min-width:60px;height:7px;background:var(--border);border-radius:5px;overflow:hidden;">
              <div style="height:100%;width:${avancePct}%;background:linear-gradient(90deg, ${m.color}99, ${m.color});border-radius:5px;"></div>
            </div>
            <span style="font-size:10px;font-weight:700;color:${m.color};white-space:nowrap;">${avancePct}% avance</span>
            ${proy ? `<span style="font-size:10px;font-weight:700;color:${proyColor};white-space:nowrap;" title="Según el ritmo mantenido desde que se activó esta meta, es lo que se proyecta alcanzar en esa fecha">≈ ${proy.pct}% proyección</span>` : ''}
          </div>
        </div>`;
      }).join('')}
    </div>` : ''}
  </div>`;
}

function renderCRMSPOkr() {
  const el = document.getElementById('crmsp-okr-content');
  if (!el) return;
  el.innerHTML = `<div class="dash-card">
    <div class="dash-card-header"><i class="ti ti-target" aria-hidden="true"></i><span>Objetivos CRM Serv. Profesionales</span></div>
    <div style="margin-top:14px;">
      ${CRMSP_OKR_METRICAS.map(crmSPOkrMetricaHTML).join('')}
    </div>
    ${!can('canConfig') ? '<p style="font-size:11px;color:var(--muted);margin-top:4px;">Solo Admin puede modificar los objetivos.</p>' : ''}
  </div>`;
}

// Reutiliza el mismo modal/estado temporal de metas volantes que usa el
// CRM Comunidades (_okrMetasTemp, _leerOkrMetasTempDesdeDOM,
// _renderOkrMetasTempList, _anadirMetaOkrTemp, _quitarMetaOkrTemp — son
// genéricas, no dependen de nada propio de ese módulo).
let _okrSPEditandoKey = null;

function abrirModalObjetivoOkrSP(key) {
  if (!can('canConfig')) return;
  const m = CRMSP_OKR_METRICAS.find(x => x.key === key);
  if (!m) return;
  const objetivo = getCRMSPOkrObjetivo(key);
  _okrSPEditandoKey = key;
  _okrMetasTemp = objetivo.metas.map(x => ({ ...x }));

  const body = `
    <p style="font-size:13px;font-weight:600;margin-bottom:12px;">${esc(m.label)} — CRM Serv. Profesionales</p>
    <div style="background:var(--bg);border-radius:var(--r);padding:12px;margin-bottom:14px;">
      <div style="font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;margin-bottom:8px;">🏁 Objetivo final</div>
      <div class="form-row">
        <div class="form-group" style="margin:0;"><label>Valor${m.formato==='eur'?' (€)':''}</label><input type="number" min="0" id="okrsp-final-valor" value="${objetivo.final.valor||''}"></div>
        <div class="form-group" style="margin:0;"><label>Fecha</label><input type="date" id="okrsp-final-fecha" value="${esc(objetivo.final.fecha||'')}"></div>
      </div>
    </div>
    <div>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
        <span style="font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;">🚩 Metas volantes (opcional)</span>
        <button type="button" onclick="_anadirMetaOkrTemp()" class="btn-sm"><i class="ti ti-plus" aria-hidden="true"></i> Añadir meta</button>
      </div>
      <div id="okr-metas-list"></div>
    </div>`;
  document.getElementById('modal-title').textContent = 'Editar objetivo';
  document.getElementById('modal-body').innerHTML = body;
  document.getElementById('modal-bg').style.display = 'flex';
  document.querySelector('.modal')?.classList.remove('modal-wide');
  const hdrActions = document.getElementById('modal-header-actions');
  if (hdrActions) hdrActions.innerHTML = '';
  _renderOkrMetasTempList();
  _modalCustomCallback = () => {
    _okrMetasTemp = _leerOkrMetasTempDesdeDOM();
    const valorFinal = parseFloat(document.getElementById('okrsp-final-valor')?.value) || 0;
    const fechaFinal = document.getElementById('okrsp-final-fecha')?.value || '';
    if (!data.crmSPOkrObjetivos) data.crmSPOkrObjetivos = {};
    data.crmSPOkrObjetivos[_okrSPEditandoKey] = {
      final: { valor: valorFinal, fecha: fechaFinal },
      metas: _okrMetasTemp.filter(x => x.valor > 0),
      fechaCreacion: objetivo.fechaCreacion || new Date().toISOString().slice(0,10),
    };
    saveData(['crmSPOkrObjetivos']);
    logAction('EDITAR', 'OKR CRM Serv. Prof.', `Objetivo "${m.label}" actualizado`);
    closeModal();
    renderCRMSPOkr();
    showToast('Objetivo guardado');
  };
}

/* ═══════════════════════════════════════════════════
   ESTADÍSTICAS (versión simplificada, propia del módulo)
   ═══════════════════════════════════════════════════ */
let crmspStatsFiltro = { comercial: '', origen: '', periodo: 'mes' }; // hoy | semana | mes | anio | todo

function crmspStatsSetComercial(v) { crmspStatsFiltro.comercial = v; renderCRMSPEstadisticas(); }
function crmspStatsSetOrigen(v) { crmspStatsFiltro.origen = v; renderCRMSPEstadisticas(); }
function crmspStatsSetPeriodo(p) { crmspStatsFiltro.periodo = p; renderCRMSPEstadisticas(); }
function crmspStatsLimpiarFiltros() {
  crmspStatsFiltro = { comercial: '', origen: '', periodo: 'mes' };
  renderCRMSPEstadisticas();
}

// Conversión "de cohorte" para Servicios Profesionales — mismo cálculo que
// crmCohorteConversion (comunidades): de los contactos que ENTRARON o
// tuvieron SEGUIMIENTO en el periodo, cuántos de esos contactos concretos
// han acabado convirtiéndose en cliente, sin importar cuándo pasó la
// conversión en sí.
function crmSPCohorteConversion(comercial, desdeStr, origen) {
  const idsContactosReales = new Set((data.contactosSP||[]).map(c=>c.id));
  const contactoPorId = {};
  (data.contactosSP||[]).forEach(c => { contactoPorId[c.id] = c; });
  const filtroBase = a => idsContactosReales.has(a.contactoId) && a.fecha && (!desdeStr || a.fecha >= desdeStr) && (!comercial || a.comercial === comercial) && (!origen || a.origen === origen);
  const idsNuevos = new Set((data.crmSPActividad || []).filter(a => a.tipo === 'nuevo_contacto' && filtroBase(a)).map(a => a.contactoId));
  const idsSeguimiento = new Set((data.crmSPActividad || []).filter(a => a.tipo === 'seguimiento' && filtroBase(a)).map(a => a.contactoId));
  const idsConvertidos = new Set((data.crmSPActividad || []).filter(a => a.tipo === 'conversion' && idsContactosReales.has(a.contactoId) && contactoPorId[a.contactoId]?.etapa === 'Cliente Captado' && (!comercial || a.comercial === comercial) && (!origen || a.origen === origen)).map(a => a.contactoId));
  const convDeNuevos = [...idsNuevos].filter(id => idsConvertidos.has(id)).length;
  const convDeSeguimiento = [...idsSeguimiento].filter(id => idsConvertidos.has(id)).length;
  return {
    nuevos: idsNuevos.size, seguimiento: idsSeguimiento.size,
    convDeNuevos, convDeSeguimiento,
    tasaNuevos: idsNuevos.size ? (convDeNuevos / idsNuevos.size * 100) : 0,
    tasaSeguimiento: idsSeguimiento.size ? (convDeSeguimiento / idsSeguimiento.size * 100) : 0,
  };
}

let chartCRMSPActividad = null;
let chartCRMSPSeguimiento = null;
let chartCRMSPCaptados = null;

// Mismo formato que Estadísticas de Comunidades (renderCRMEstadisticas):
// mismos filtros (comercial, origen, periodo), mismos KPIs, mismas 3
// gráficas y la misma tabla "por comercial" — para que ambos CRMs se lean
// exactamente igual.
// Repara el histórico de actividad (crmSPActividad) para los contactos que
// no tengan su apunte de "nuevo_contacto"/"seguimiento"/"conversion"/
// "descarte" — usando las fechas que ya tienen guardadas en su propia
// ficha. Es idempotente (nunca duplica lo que ya existe) y silenciosa: se
// llama sola cada vez que se entra en Estadísticas, sin que nadie tenga que
// acordarse de pulsar ningún botón.
function _autoRepararHistoricoActividadSP() {
  if (!Array.isArray(data.contactosSP) || !data.contactosSP.length) return;
  if (!Array.isArray(data.crmSPActividad)) data.crmSPActividad = [];
  const yaTiene = (contactoId, tipo) => data.crmSPActividad.some(a => a.contactoId === contactoId && a.tipo === tipo);
  let creados = 0;

  data.contactosSP.forEach(c => {
    if (!yaTiene(c.id, 'nuevo_contacto')) {
      const fechaSeg0 = (c.seguimiento||[]).map(s=>s.fecha).filter(Boolean).sort()[0];
      const fecha = c.fechaPropuesta || fechaSeg0 || fechaLocalISO(new Date());
      data.crmSPActividad.push({ id: uid(), contactoId: c.id, tipo: 'nuevo_contacto', fecha, comercial: c.responsable, origen: c.origen });
      creados++;
    }
    // Reconciliar por fecha, no solo por presencia: un contacto puede tener
    // más de un apunte de seguimiento el mismo día (p.ej. "Propuesta
    // enviada" y una nota manual el mismo día). Antes solo se comprobaba si
    // YA EXISTÍA algún apunte ese día (booleano), así que un segundo apunte
    // el mismo día nunca se traspasaba al histórico y las estadísticas
    // quedaban permanentemente por debajo del total real del OKR. Ahora se
    // cuenta cuántos apuntes tiene el contacto en cada fecha y cuántos hay
    // ya registrados en el histórico, y solo se crean los que falten.
    const segsPorFecha = {};
    (c.seguimiento||[]).forEach(s => { if (s.fecha) segsPorFecha[s.fecha] = (segsPorFecha[s.fecha]||0) + 1; });
    Object.entries(segsPorFecha).forEach(([fecha, total]) => {
      const yaRegistrados = data.crmSPActividad.filter(a => a.contactoId === c.id && a.tipo === 'seguimiento' && a.fecha === fecha).length;
      for (let i = yaRegistrados; i < total; i++) {
        data.crmSPActividad.push({ id: uid(), contactoId: c.id, tipo: 'seguimiento', fecha, comercial: c.responsable, origen: c.origen });
        creados++;
      }
    });
    if (c.etapa === 'Cliente Captado' && !yaTiene(c.id, 'conversion')) {
      data.crmSPActividad.push({ id: uid(), contactoId: c.id, tipo: 'conversion', fecha: c.fechaPropuesta || fechaLocalISO(new Date()), comercial: c.responsable, origen: c.origen });
      creados++;
    }
    if (c.etapa === 'Descartado' && !yaTiene(c.id, 'descarte')) {
      data.crmSPActividad.push({ id: uid(), contactoId: c.id, tipo: 'descarte', fecha: c.fechaPropuesta || fechaLocalISO(new Date()), comercial: c.responsable, origen: c.origen });
      creados++;
    }
  });

  if (creados > 0) saveData(['crmSPActividad']);
}

function renderCRMSPEstadisticas() {
  const el = document.getElementById('crmsp-stats-content');
  if (!el) return;
  _autoRepararHistoricoActividadSP();

  const comerciales = getUsuariosNombresCRMSP();
  const desde = crmStatsRangoDesde(crmspStatsFiltro.periodo);
  const desdeStr = desde ? fechaLocalISO(desde) : null;

  const idsContactosReales = new Set((data.contactosSP||[]).map(c=>c.id));
  const contactoPorId = {};
  (data.contactosSP||[]).forEach(c => { contactoPorId[c.id] = c; });
  let actividad = (data.crmSPActividad || []).filter(a => idsContactosReales.has(a.contactoId));
  actividad = actividad.filter(a => a.fecha && (!desdeStr || a.fecha >= desdeStr));
  if (crmspStatsFiltro.comercial) actividad = actividad.filter(a => a.comercial === crmspStatsFiltro.comercial);
  if (crmspStatsFiltro.origen) actividad = actividad.filter(a => a.origen === crmspStatsFiltro.origen);

  const nuevos = actividad.filter(a => a.tipo === 'nuevo_contacto');
  const segs   = actividad.filter(a => a.tipo === 'seguimiento');
  const conversiones = actividad.filter(a => a.tipo === 'conversion' && contactoPorId[a.contactoId]?.etapa === 'Cliente Captado');
  const descartes     = actividad.filter(a => a.tipo === 'descarte' && contactoPorId[a.contactoId]?.etapa === 'Descartado');
  const cohorte = crmSPCohorteConversion(crmspStatsFiltro.comercial, desdeStr, crmspStatsFiltro.origen);

  const PERIODOS = [['hoy','Hoy'],['semana','Esta semana'],['mes','Este mes'],['anio','Este año'],['todo','Todo']];

  el.innerHTML = `
    <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px;">
      <select onchange="crmspStatsSetComercial(this.value)" class="select-sm">
        <option value="">Todos los comerciales</option>
        ${comerciales.map(n => `<option value="${esc(n)}" ${crmspStatsFiltro.comercial===n?'selected':''}>${esc(n)}</option>`).join('')}
      </select>
      <select onchange="crmspStatsSetOrigen(this.value)" class="select-sm">
        <option value="">Todos los orígenes</option>
        ${CRMSP_ORIGENES.map(o => `<option value="${esc(o)}" ${crmspStatsFiltro.origen===o?'selected':''}>${esc(o)}</option>`).join('')}
      </select>
      <div style="display:flex;gap:4px;background:var(--bg);border:1px solid var(--border);border-radius:var(--r);padding:3px;">
        ${PERIODOS.map(([k,label]) => `<button type="button" onclick="crmspStatsSetPeriodo('${k}')" style="font-size:12px;padding:5px 12px;border-radius:6px;border:none;cursor:pointer;white-space:nowrap;background:${crmspStatsFiltro.periodo===k?'var(--purple)':'transparent'};color:${crmspStatsFiltro.periodo===k?'#fff':'var(--fg)'};font-weight:${crmspStatsFiltro.periodo===k?'600':'400'};">${label}</button>`).join('')}
      </div>
      <button onclick="crmspStatsLimpiarFiltros()" style="font-size:11px;color:var(--muted);background:none;border:1px solid var(--border);border-radius:var(--r);cursor:pointer;padding:4px 10px;"><i class="ti ti-x"></i> Limpiar</button>
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-bottom:20px;">
      <div class="dash-card" style="padding:16px;">
        <div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px;">Clientes captados</div>
        <div style="font-size:28px;font-weight:700;color:#0F7A5C;">${conversiones.length}</div>
      </div>
      <div class="dash-card" style="padding:16px;">
        <div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px;">Conversión · nuevos contactos (no cuenta contactos de seguimiento)</div>
        <div style="font-size:28px;font-weight:700;color:${cohorte.tasaNuevos>=30?'#0F7A5C':cohorte.tasaNuevos>=10?'#3457B2':'#A85C48'};">${cohorte.tasaNuevos.toFixed(0)}%</div>
        <div style="font-size:10px;color:var(--muted);margin-top:2px;">${cohorte.convDeNuevos} captados de ${cohorte.nuevos} entrados en el periodo</div>
      </div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-bottom:20px;">
      <div class="dash-card" style="padding:16px;">
        <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px;">
          <div style="font-size:12px;font-weight:600;color:var(--purple);"><i class="ti ti-user-plus" style="font-size:13px;"></i> Nuevos contactos</div>
          <div style="font-size:20px;font-weight:700;color:var(--purple);">${nuevos.length}</div>
        </div>
        <div style="height:180px;"><canvas id="chart-crmsp-nuevos"></canvas></div>
      </div>
      <div class="dash-card" style="padding:16px;">
        <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px;">
          <div style="font-size:12px;font-weight:600;color:#1D4ED8;"><i class="ti ti-phone-outgoing" style="font-size:13px;"></i> Contactos de seguimiento</div>
          <div style="font-size:20px;font-weight:700;color:#1D4ED8;">${segs.length}</div>
        </div>
        <div style="height:180px;"><canvas id="chart-crmsp-seguimiento"></canvas></div>
      </div>
    </div>

    <div class="dash-card" style="padding:16px;margin-bottom:20px;">
      <div style="font-size:12px;font-weight:600;margin-bottom:10px;"><i class="ti ti-chart-bar" style="font-size:13px;color:#0F7A5C;"></i> Clientes captados en el tiempo</div>
      <div style="height:160px;"><canvas id="chart-crmsp-captados"></canvas></div>
    </div>

    ${!crmspStatsFiltro.comercial ? `
    <div class="dash-card" style="padding:0;overflow:hidden;">
      <table style="width:100%;border-collapse:collapse;font-size:13px;">
        <thead><tr style="background:var(--bg);">
          <th style="text-align:left;padding:10px 14px;font-size:10px;text-transform:uppercase;color:var(--muted);">Comercial</th>
          <th style="text-align:right;padding:10px 14px;font-size:10px;text-transform:uppercase;color:var(--muted);">Nuevos</th>
          <th style="text-align:right;padding:10px 14px;font-size:10px;text-transform:uppercase;color:var(--muted);">Seguimientos</th>
          <th style="text-align:right;padding:10px 14px;font-size:10px;text-transform:uppercase;color:var(--muted);">Captados</th>
          <th style="text-align:right;padding:10px 14px;font-size:10px;text-transform:uppercase;color:var(--muted);">Descartados</th>
          <th style="text-align:right;padding:10px 14px;font-size:10px;text-transform:uppercase;color:var(--muted);">Conv. · nuevos</th>
        </tr></thead>
        <tbody>
          ${comerciales.map(nombre => {
            const n = nuevos.filter(a=>a.comercial===nombre).length;
            const s = segs.filter(a=>a.comercial===nombre).length;
            const c = conversiones.filter(a=>a.comercial===nombre).length;
            const d = descartes.filter(a=>a.comercial===nombre).length;
            if (!n && !s && !c && !d) return '';
            const coh = crmSPCohorteConversion(nombre, desdeStr, crmspStatsFiltro.origen);
            return `<tr style="border-top:1px solid var(--border);">
              <td style="padding:9px 14px;">${esc(nombre)}</td>
              <td style="padding:9px 14px;text-align:right;font-weight:600;">${n}</td>
              <td style="padding:9px 14px;text-align:right;font-weight:600;">${s}</td>
              <td style="padding:9px 14px;text-align:right;font-weight:600;color:#0F7A5C;">${c}</td>
              <td style="padding:9px 14px;text-align:right;font-weight:600;color:#A85C48;">${d}</td>
              <td style="padding:9px 14px;text-align:right;font-weight:600;">${coh.tasaNuevos.toFixed(0)}%</td>
            </tr>`;
          }).join('') || `<tr><td colspan="6" style="padding:16px;text-align:center;color:var(--muted);">Sin actividad registrada en este periodo.</td></tr>`}
        </tbody>
      </table>
    </div>` : ''}
  `;

  chartCRMSPActividad   = destroyChart(chartCRMSPActividad);
  chartCRMSPSeguimiento = destroyChart(chartCRMSPSeguimiento);
  chartCRMSPCaptados    = destroyChart(chartCRMSPCaptados);
  const agrupaPorMes = crmspStatsFiltro.periodo === 'anio' || crmspStatsFiltro.periodo === 'todo';
  const clave = (fecha) => agrupaPorMes ? fecha.slice(0,7) : fecha;
  const claves = [...new Set(actividad.map(a => clave(a.fecha)))].sort();
  const labels = claves.map(k => agrupaPorMes ? k : fmtDate(k));

  const miniChart = (canvasId, serie, valores, color) => {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return null;
    return new Chart(canvas, {
      type: 'bar',
      data: { labels, datasets: [{ label: serie, data: valores, backgroundColor: color, borderRadius: 4, maxBarThickness: 34 }] },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: { y: { beginAtZero: true, ticks: { precision: 0 } } }
      }
    });
  };

  const nuevosPorClave = claves.map(k => nuevos.filter(a => clave(a.fecha) === k).length);
  const segsPorClave   = claves.map(k => segs.filter(a => clave(a.fecha) === k).length);
  const convPorClave   = claves.map(k => conversiones.filter(a => clave(a.fecha) === k).length);
  chartCRMSPActividad   = miniChart('chart-crmsp-nuevos', 'Nuevos contactos', nuevosPorClave, '#4C45A5');
  chartCRMSPSeguimiento = miniChart('chart-crmsp-seguimiento', 'Seguimientos', segsPorClave, '#1D4ED8');
  chartCRMSPCaptados    = miniChart('chart-crmsp-captados', 'Clientes captados', convPorClave, '#0F7A5C');
}


