/* ═══════════════════════════════════════════════════
   SUBMENÚ "TARIFAS 2026" — catálogo consultable del CRM Serv.
   Profesionales, con calculadora en vivo para los servicios con tramos.
   Reutiliza el mismo motor que el modal de propuesta (calcularPrecioTarifaSP)
   para no duplicar la lógica de precios.
   ═══════════════════════════════════════════════════ */
let crmspTarifasAbierto = null; // grupo actualmente desplegado (acordeón)

function crmspTarifasToggleGrupo(grupo) {
  crmspTarifasAbierto = crmspTarifasAbierto === grupo ? null : grupo;
  renderCRMSPTarifas();
}

function renderCRMSPTarifas() {
  const el = document.getElementById('crmsp-tarifas-content');
  if (!el) return;
  const puedeEditar = can('canConfig');

  // Agrupar el catálogo igual que en la plantilla de propuesta (misma
  // fuente: SP_OFERTA_GRUPOS), para que "lo que ves aquí" sea justo lo que
  // se ofrece luego al cliente.
  const gruposOrden = [];
  const gruposMap = {};
  SP_TARIFAS_2026.forEach(s => {
    const meta = SP_OFERTA_GRUPOS[s.key] || { grupo: s.key, titulo: s.nombre };
    if (!gruposMap[meta.grupo]) { gruposMap[meta.grupo] = { titulo: meta.titulo, items: [] }; gruposOrden.push(meta.grupo); }
    gruposMap[meta.grupo].items.push(s);
  });

  // Mismo orden que al generar la propuesta: primero los grupos con
  // servicios que sí ofrecemos, luego los que no ofrecemos actualmente.
  const gruposOrdenados = gruposOrden.slice().sort((a, b) => {
    const da = gruposMap[a].items.every(i => i.disponible !== false);
    const db = gruposMap[b].items.every(i => i.disponible !== false);
    if (da === db) return 0;
    return da ? -1 : 1;
  });

  const cardsHTML = gruposOrdenados.map(g => {
    const grupo = gruposMap[g];
    const abierto = crmspTarifasAbierto === g;
    const esGrupoPaquete = grupo.items.some(i => i.esPaquete);

    const filasHTML = grupo.items.map(s => {
      const disponible = s.disponible !== false;
      const badge = !disponible ? `<span style="font-size:11px;font-weight:600;color:#92400E;background:#FFFBEB;border:1px solid #FDE68A;border-radius:10px;padding:2px 8px;white-space:nowrap;margin-left:10px;">Servicio actualmente no ofrecido</span>` : '';
      const notaHTML = s.nota ? `<span style="font-size:11px;color:var(--muted);font-weight:400;margin-left:10px;">${esc(s.nota)}</span>` : '';
      const efectivo = getSPTarifaItem(s.key);
      const campos = spTarifaPriceFields(efectivo);
      const hayOverride = !!(data.crmSPTarifas && data.crmSPTarifas[s.key]);

      if (!campos.length) return ''; // no debería pasar, todos los tipos tienen al menos un campo de precio

      // Un solo campo de precio (fijo, o binaria con 2 campos): tabla simple label/valor.
      const filasTabla = campos.map(f => {
        const valorActual = spGetPath(efectivo, f.path);
        return `<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 0;gap:10px;">
          <span style="font-size:12.5px;color:var(--muted);flex:1;">${esc(f.label)}</span>
          <input type="number" min="0" step="0.01" data-path="${f.path}" value="${valorActual!=null?valorActual:''}" style="width:110px;font-size:12.5px;text-align:right;">
        </div>`;
      }).join('');

      const accionesHTML = puedeEditar ? `<div style="display:flex;gap:10px;justify-content:flex-end;margin-top:8px;">
        ${hayOverride ? `<button type="button" onclick="restaurarTarifaSP('${s.key}')" style="font-size:11px;color:var(--muted);background:none;border:none;cursor:pointer;">Restaurar de fábrica</button>` : ''}
        <button type="button" onclick="guardarEdicionTarifaSP('${s.key}')" class="btn-sm"><i class="ti ti-device-floppy" style="font-size:12px;" aria-hidden="true"></i> Guardar cambios</button>
      </div>` : '';

      return `<div class="calc-row ${puedeEditar ? 'tarifa2026-edit' : ''}" data-key="${s.key}" style="padding:10px 0;border-bottom:1px solid var(--border);">
        <div style="display:flex;align-items:center;justify-content:space-between;font-size:13px;font-weight:600;margin-bottom:6px;">
          <span>${esc(s.nombre)}${hayOverride?' <span title="Precios modificados manualmente" style="color:var(--purple);">✎</span>':''}</span>
          ${notaHTML}${badge}
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:2px 24px;">${filasTabla}</div>
        ${s.detalleServicios ? `<div style="font-size:11.5px;color:var(--muted);margin-top:8px;padding-top:8px;border-top:1px dashed var(--border);line-height:1.5;">${esc(s.detalleServicios)}</div>` : ''}
        ${accionesHTML}
      </div>`;
    }).join('');

    return `<div class="dash-card" style="margin-bottom:10px;${esGrupoPaquete ? 'background:#FFF7ED;border:1px solid #FDE1C2;' : ''}">
      <div class="dash-card-header" style="cursor:pointer;justify-content:space-between;" onclick="crmspTarifasToggleGrupo('${g}')">
        <span style="display:flex;align-items:center;gap:8px;"><i class="ti ${esGrupoPaquete?'ti-package':'ti-receipt-2'}" style="${esGrupoPaquete?'color:#C2660D;':''}" aria-hidden="true"></i>${esc(grupo.titulo)}</span>
        <i class="ti ${abierto?'ti-chevron-up':'ti-chevron-down'}" style="font-size:14px;color:var(--muted);" aria-hidden="true"></i>
      </div>
      ${abierto ? `<div style="margin-top:12px;">${filasHTML}</div>` : ''}
    </div>`;
  }).join('');

  el.innerHTML = `<p style="font-size:12px;color:var(--muted);margin:0 0 14px;">Catálogo completo de Tarifas 2026, con todos los tramos por empleados/usuarios.${puedeEditar ? ' Puedes modificar cualquier precio y guardarlo — se usará automáticamente al generar propuestas.' : ''}</p>
    ${cardsHTML}`;
}

function recalcularTarifa2026Row(key) {
  const row = document.querySelector(`.calc-row[data-key="${key}"]`);
  const resultEl = document.getElementById('tarifa2026-result-' + key);
  if (!row || !resultEl) return;
  const s = SP_TARIFAS_2026.find(x => x.key === key);
  const inputs = {};
  row.querySelectorAll('.tarifa2026-input').forEach(inp => {
    const campo = inp.dataset.campo;
    inputs[campo] = inp.type === 'checkbox' ? inp.checked : inp.value;
  });
  const res = calcularPrecioTarifaSP(key, inputs);
  resultEl.textContent = res.precio != null ? fmtEUR(res.precio) + (s.iva ? ' + IVA' : '') : 'Consultar';
}

/* ═══════════════════════════════════════════════════
   AUDITORÍA — cuestionario de necesidades del cliente potencial,
   adaptado de la plantilla que ya usaba el equipo (Apps Script). Se
   rellena desde dentro del panel (en visita/llamada, o junto con el
   cliente) y queda guardado en el propio contacto comercial
   (data.contactosSP[].auditoria). No es un formulario público en esta
   fase — para poder enviarlo a que lo rellene el cliente por su cuenta
   haría falta una URL pública sin login, que es una pieza de
   infraestructura aparte (lo dejo anotado, no lo monto en este paso).
   ═══════════════════════════════════════════════════ */
const CRMSP_AUDITORIA_SECTORES = ['Comercio','Oficinas y Servicios','Educación y Formación','Hostelería y Turismo','Estética y Bienestar','Servicios Técnicos','Otro'];

// Servicios de interés — alineados con los servicios que realmente se
// contratan hoy (ver Tarifas 2026), no con el listado antiguo completo.
// requiereEmpleados: true = solo tiene sentido si la empresa tiene personal
// contratado (registro horario, PRL, acoso solo aplican con trabajadores);
// se muestran en un bloque aparte con un aviso, en vez de mezclados con el
// resto (ver abrirModalAuditoriaSP, generarAuditoriaHTMLSP y
// renderAuditoriaPublicaPage).
const CRMSP_AUDITORIA_SERVICIOS = [
  { key:'rgpd', label:'Protección de Datos (RGPD/LOPDGDD)', requiereEmpleados:false },
  { key:'lssice', label:'Adaptación LSSICE (web / comercio electrónico)', requiereEmpleados:false },
  { key:'registro_horario', label:'Control de Registro Horario', requiereEmpleados:true },
  { key:'prl', label:'Prevención de Riesgos Laborales (Autogestión)', requiereEmpleados:true },
  { key:'acoso', label:'Prevención del Acoso Sexual y por Razón de Sexo', requiereEmpleados:true },
];
const CRMSP_AUDITORIA_SERVICIOS_SIN_EMPLEADOS = CRMSP_AUDITORIA_SERVICIOS.filter(s => !s.requiereEmpleados);
const CRMSP_AUDITORIA_SERVICIOS_CON_EMPLEADOS = CRMSP_AUDITORIA_SERVICIOS.filter(s => s.requiereEmpleados);

// Bloque informativo sobre autogestión de la prevención (PRL) — requisito
// legal para poder acogerse: hasta 10 trabajadores (25 si un único centro),
// el empresario trabaja habitualmente en el centro, tiene formación de
// nivel básico y la actividad no está en el Anexo I (actividades
// peligrosas). Se muestra al principio del documento y del formulario
// público, no en el modal interno (ese es solo para el equipo, no necesita
// texto comercial/explicativo).
const CRMSP_AUDITORIA_AUTOGESTION_TITULO = '¿Quién puede autogestionar la prevención?';
const CRMSP_AUDITORIA_AUTOGESTION_TEXTO = 'Moore Market ofrece servicios de autogestión en materias de obligado cumplimiento. El empresario puede asumir personalmente la prevención si la empresa tiene hasta 10 trabajadores (o hasta 25 trabajadores si tiene un único centro de trabajo), siempre que el empresario trabaje de forma habitual en el centro, tenga la formación necesaria (nivel básico) y la actividad NO esté en el Anexo I (actividades peligrosas).';
// Frase de transición hacia la propuesta, justo antes del paquete
// recomendado — en singular si la empresa no tiene empleados (autónomo),
// en plural si sí los tiene (ver esSingular en
// renderResultadoAutodiagnosticoPublicoSP).
const CRMSP_AUDITORIA_INTRO_COMERCIAL_PLURAL = 'Ahora que ya conoces tu situación, podemos ofreceros una solución integral para cumplir con las principales obligaciones normativas, con condiciones preferentes y sin que vuestro equipo tenga que asumir ninguna carga de gestión. Nos encargamos de todo el proceso para que vuestra empresa esté siempre al día con sus obligaciones legales.';
const CRMSP_AUDITORIA_INTRO_COMERCIAL_SINGULAR = 'Ahora que ya conoces tu situación, podemos ofrecerte una solución integral para cumplir con las principales obligaciones normativas, con condiciones preferentes y sin que tengas que asumir ninguna carga de gestión. Nos encargamos de todo el proceso para que tu empresa esté siempre al día con sus obligaciones legales.';
const CRMSP_AUDITORIA_COMPROMISO_TITULO = 'Compromiso operativo';
const CRMSP_AUDITORIA_COMPROMISO_TEXTO = 'Desde Moore Market nos encargamos de todo el ciclo de principio a fin: recopilación de datos, gestión documental, implantación, seguimiento y mantenimiento continuo de los servicios.\nGarantizamos una implantación ágil, sencilla y completamente libre de carga de trabajo para vuestro equipo.';

let crmspAuditoriaFiltroEmpresa = '';
let crmspAuditoriaFiltroEstado = '';

function limpiarFiltrosAuditoriaSP() {
  const elE = document.getElementById('crmsp-auditoria-filter-empresa'); if (elE) elE.value = '';
  const elT = document.getElementById('crmsp-auditoria-filter-tipo'); if (elT) elT.value = '';
  const elS = document.getElementById('crmsp-auditoria-filter-estado'); if (elS) elS.value = '';
  renderCRMSPAuditoria();
}

// Menú de Autodiagnóstico — hub único de seguimiento tanto para Leads como
// para Contactos Comerciales (antes cada uno se seguía por su lado: los
// leads en su propia tabla, los contactos aquí). Un lead ya convertido en
// contacto (l.contactoCrmId) no se vuelve a listar aparte — a partir de la
// conversión su seguimiento se lleva desde su ficha de Contacto.
// Pasa a "Sin Respuesta" automáticamente los autodiagnósticos que llevan
// más de una semana en "Enviado" sin que el cliente haya contestado — ya
// no hay ningún control manual para marcarlo (a petición expresa: todo el
// seguimiento tiene que ir solo, sin que nadie del equipo tenga que
// tocarlo a mano), así que tiene que actualizarse solo en algún punto, y
// el más natural es cada vez que se abre este hub. Mismo patrón de
// "autorreparación al renderizar" que ya se usa para el histórico de
// actividad (ver _autoRepararHistoricoActividadSP).
const CRMSP_AUDITORIA_DIAS_SIN_RESPUESTA = 7;
function _autoActualizarSinRespuestaAutodiagnosticoSP() {
  const hoy = new Date();
  let cambios = false;
  [...(data.leadsSP||[]), ...(data.contactosSP||[])].forEach(x => {
    // Estado imposible: no se puede estar en "Solicita Llamada" ni "Quiere
    // Contratar" (eso solo lo decide el cliente al final del cuestionario)
    // si en realidad el autodiagnóstico no se ha completado todavía — por
    // ejemplo, datos que quedaron así de antes de quitar el desplegable
    // manual con el que se podía elegir cualquier valor a mano. Se
    // corrige solo a "pendiente de envío" en vez de dejarlo inconsistente.
    const completada = !!(x.auditoriaPublicaCompletada || x.auditoriaRealizada);
    if (!completada && (x.seguimientoAutodiagnostico === 'Solicita Llamada' || x.seguimientoAutodiagnostico === 'Quiere Contratar')) {
      x.seguimientoAutodiagnostico = '';
      cambios = true;
      return;
    }
    if (x.seguimientoAutodiagnostico !== 'Enviado' || !x.fechaEnvioAutodiagnostico) return;
    const dias = Math.floor((hoy - new Date(x.fechaEnvioAutodiagnostico + 'T00:00:00')) / 86400000);
    if (dias >= CRMSP_AUDITORIA_DIAS_SIN_RESPUESTA) {
      x.seguimientoAutodiagnostico = 'Sin Respuesta';
      cambios = true;
    }
  });
  if (cambios) saveData(['leadsSP', 'contactosSP']);
}

let crmspAuditoriaSortCol = null;
let crmspAuditoriaSortDir = 1; // 1 = ascendente, -1 = descendente

function crmspAuditoriaOrdenarTabla(col) {
  if (crmspAuditoriaSortCol === col) crmspAuditoriaSortDir *= -1;
  else { crmspAuditoriaSortCol = col; crmspAuditoriaSortDir = 1; }
  renderCRMSPAuditoria();
}

// Accessors para ordenar por cabecera — el mismo patrón que CRMSP_TABLA_CAMPOS
// (tabla de Detalle Propuestas), aplicado aquí al hub de Autodiagnóstico.
const CRMSP_AUDITORIA_TABLA_CAMPOS = {
  tipo:        x => x.tipo,
  empresa:     x => x.empresa || '',
  contacto:    x => x.contacto || '',
  responsable: x => x.responsable || '',
  origen:      x => x.comercial || '',
  respuesta:   x => x.completada ? 1 : 0,
  fechaEnvio:  x => x.fechaEnvio || '',
  seguimiento: x => CRMSP_SEGUIMIENTO_AUDITORIA_PRIORIDAD[x.seguimiento] || 0,
};

function renderCRMSPAuditoria() {
  const el = document.getElementById('crmsp-auditoria-content');
  if (!el) return;

  _autoActualizarSinRespuestaAutodiagnosticoSP();

  const leads = (data.leadsSP||[]).filter(l => !l.contactoCrmId).map(l => ({
    tipo: 'lead', id: l.id, empresa: l.empresa, contacto: l.contacto, responsable: l.responsable,
    completada: !!l.auditoriaPublicaCompletada, fecha: l.auditoriaPublicaRespuesta?.fecha || '',
    comercial: l.auditoriaPublicaRespuesta?.comercial || '', enviadoPor: l.enviadoPorAutodiagnostico || '',
    seguimiento: l.seguimientoAutodiagnostico || '', fechaEnvio: l.fechaEnvioAutodiagnostico || '',
  }));
  const contactos = getCRMSPVisibles().map(c => ({
    tipo: 'contacto', id: c.id, empresa: c.empresa, contacto: c.contacto, responsable: c.responsable,
    completada: !!c.auditoriaRealizada, fecha: c.auditoria?.fecha || '',
    comercial: c.auditoria?.comercial || '', enviadoPor: c.enviadoPorAutodiagnostico || '',
    seguimiento: c.seguimientoAutodiagnostico || '', fechaEnvio: c.fechaEnvioAutodiagnostico || '',
  }));

  let todos = [...leads, ...contactos];

  const fEmpresa = _normalizarBusqueda(document.getElementById('crmsp-auditoria-filter-empresa')?.value?.trim() || '');
  const fTipo = document.getElementById('crmsp-auditoria-filter-tipo')?.value || '';
  const fEstado = document.getElementById('crmsp-auditoria-filter-estado')?.value || '';
  if (fEmpresa) todos = todos.filter(x => _normalizarBusqueda(x.empresa||'').includes(fEmpresa));
  if (fTipo) todos = todos.filter(x => x.tipo === fTipo);
  if (fEstado === 'sin_enviar') todos = todos.filter(x => !x.seguimiento);
  // "Pendientes de contacto" = ya han respondido el autodiagnóstico y han
  // pedido explícitamente que les llamemos o contratar — son los casos con
  // una acción de equipo pendiente de verdad, no solo enviados sin respuesta.
  else if (fEstado === 'pendientes_contacto') todos = todos.filter(x => x.completada && (x.seguimiento === 'Solicita Llamada' || x.seguimiento === 'Quiere Contratar'));
  else if (fEstado) todos = todos.filter(x => x.seguimiento === fEstado);

  if (crmspAuditoriaSortCol) {
    const getVal = CRMSP_AUDITORIA_TABLA_CAMPOS[crmspAuditoriaSortCol];
    if (getVal) {
      todos = todos.slice().sort((a,b) => {
        const va = getVal(a), vb = getVal(b);
        if (typeof va === 'number' && typeof vb === 'number') return (va - vb) * crmspAuditoriaSortDir;
        return String(va).localeCompare(String(vb), 'es', {sensitivity:'base'}) * crmspAuditoriaSortDir;
      });
    }
  } else {
    todos.sort((a,b) => {
      const pa = CRMSP_SEGUIMIENTO_AUDITORIA_PRIORIDAD[a.seguimiento] || 0;
      const pb = CRMSP_SEGUIMIENTO_AUDITORIA_PRIORIDAD[b.seguimiento] || 0;
      if (pb !== pa) return pb - pa;
      return (a.empresa||'').localeCompare(b.empresa||'');
    });
  }

  const contador = document.getElementById('crmsp-auditoria-contador');
  if (contador) contador.textContent = todos.length + ' resultado(s)';

  if (!todos.length) {
    el.innerHTML = '<p style="font-size:13px;color:var(--muted);padding:20px;">No hay leads ni contactos que coincidan con los filtros.</p>';
    return;
  }

  const thCols = [
    { key:'tipo',        label:'Tipo',         width:'6%' },
    { key:'empresa',     label:'Empresa',      width:'20%', minWidth:'200px' },
    { key:'contacto',    label:'Contacto',     width:'12%', minWidth:'110px' },
    { key:'responsable', label:'Responsable',  width:'10%', minWidth:'100px' },
    { key:'origen',      label:'Origen',       width:'12%' },
    { key:'respuesta',   label:'Respuesta',    width:'8%', center:true },
    { key:'fechaEnvio',  label:'Fecha envío',  width:'8%', center:true },
    { key:'seguimiento', label:'Seguimiento',  width:'14%' },
  ];
  const thHTML = thCols.map(col => {
    const activa = crmspAuditoriaSortCol === col.key;
    const flecha = activa ? (crmspAuditoriaSortDir === 1 ? ' ▲' : ' ▼') : '';
    return `<th style="width:${col.width};${col.minWidth?`min-width:${col.minWidth};`:''}${col.center?'text-align:center;':''}cursor:pointer;user-select:none;${activa?'color:var(--purple);':''}" onclick="crmspAuditoriaOrdenarTabla('${col.key}')" title="Ordenar por ${esc(col.label)}">${esc(col.label)}${flecha}</th>`;
  }).join('');

  el.innerHTML = `<div class="crm-table-wrap"><table class="crm-table crm-table-compact">
    <thead><tr>
      ${thHTML}
      <th style="width:10%;">Acciones</th>
    </tr></thead>
    <tbody>
      ${todos.map(x => {
        const tipoBadge = x.tipo === 'lead'
          ? `<span style="font-size:10px;padding:2px 7px;border-radius:8px;background:#DBEAFE;color:#1E40AF;font-weight:700;white-space:nowrap;">LEAD</span>`
          : `<span style="font-size:10px;padding:2px 7px;border-radius:8px;background:#EDE9FE;color:#5B21B6;font-weight:700;white-space:nowrap;">CONTACTO</span>`;
        // Si nadie del equipo eligió un "Responsable" al rellenarla, es que
        // la contestó el propio cliente desde el enlace público (el
        // formulario público no pide ese campo) — si hay un nombre, es que
        // alguien del equipo la rellenó o la editó a mano. Mientras
        // todavía no hay respuesta, se muestra igualmente quién lo mandó
        // (en vez de un guion sin más información).
        const origenBadge = !x.completada
          ? (x.enviadoPor
            ? `<span style="font-size:11px;color:#55647a;white-space:nowrap;" title="Enviado por el equipo, pendiente de que el cliente responda">📤 Enviado por ${esc(x.enviadoPor)}</span>`
            : '<span style="color:var(--muted);font-size:11px;">—</span>')
          : (x.comercial
            ? `<span style="font-size:11px;color:#7C3AED;white-space:nowrap;" title="Rellenada/editada por el equipo">✏️ Editada por ${esc(x.comercial)}</span>`
            : `<span style="font-size:11px;color:#0F7A5C;white-space:nowrap;" title="Respondida por el propio cliente desde el enlace público">🤖 Autogenerado (cliente)</span>`);
        return `<tr>
          <td>${tipoBadge}</td>
          <td><input type="text" class="crmsp-aud-input" value="${esc(x.empresa)}" title="${esc(x.empresa)}" onblur="crmspAuditoriaEditarCampoInline('${x.tipo}','${x.id}','empresa', this.value)"></td>
          <td><input type="text" class="crmsp-aud-input" value="${esc(x.contacto||'')}" placeholder="—" onblur="crmspAuditoriaEditarCampoInline('${x.tipo}','${x.id}','contacto', this.value)"></td>
          <td>
            <select class="crmsp-aud-input" onchange="crmspAuditoriaEditarCampoInline('${x.tipo}','${x.id}','responsable', this.value)">
              <option value="">—</option>
              ${getUsuariosNombresCRMSP().map(n=>`<option value="${esc(n)}" ${x.responsable===n?'selected':''}>${esc(n)}</option>`).join('')}
            </select>
          </td>
          <td>${origenBadge}</td>
          <td style="text-align:center;">
            <span style="font-size:11px;padding:3px 10px;border-radius:10px;background:${x.completada?'#D1FAE5':'#F3F4F6'};color:${x.completada?'#065F46':'#6B7280'};font-weight:600;white-space:nowrap;">${x.completada?'✓ Respondido':'Sin responder'}</span>
            ${x.completada && x.fecha ? `<div style="font-size:10px;color:var(--muted);margin-top:2px;">${esc(fmtDate(x.fecha))}</div>` : ''}
          </td>
          <td style="text-align:center;white-space:nowrap;">
            ${x.fechaEnvio ? esc(fmtDate(x.fechaEnvio)) : '<span style="color:var(--muted);">—</span>'}
          </td>
          <td>
            ${_badgeSeguimientoAuditoriaSP(x.seguimiento)}
          </td>
          <td>
            <div style="display:flex;gap:6px;flex-wrap:wrap;">
              <button onclick="crmspEnviarAutodiagnosticoSP('${x.tipo}','${x.id}')" class="btn-sm" title="Enviar / copiar enlace"><i class="ti ti-link" style="font-size:12px;" aria-hidden="true"></i></button>
              <button onclick="abrirModalAuditoriaSP('${x.id}','${x.tipo}')" class="btn-sm"><i class="ti ${x.completada?'ti-edit':'ti-clipboard-plus'}" style="font-size:12px;" aria-hidden="true"></i></button>
            </div>
          </td>
        </tr>`;
      }).join('')}
    </tbody>
  </table></div>

  <div class="crm-cards-mob">
    ${todos.map(x => {
      const tipoBadge = x.tipo === 'lead'
        ? `<span style="font-size:10px;padding:2px 7px;border-radius:8px;background:#DBEAFE;color:#1E40AF;font-weight:700;white-space:nowrap;">LEAD</span>`
        : `<span style="font-size:10px;padding:2px 7px;border-radius:8px;background:#EDE9FE;color:#5B21B6;font-weight:700;white-space:nowrap;">CONTACTO</span>`;
      const origenBadge = !x.completada
        ? (x.enviadoPor ? `<div style="margin-top:2px;"><span style="font-size:10px;color:#55647a;">📤 Enviado por ${esc(x.enviadoPor)}</span></div>` : '')
        : (x.comercial
          ? `<div style="margin-top:2px;"><span style="font-size:10px;color:#7C3AED;">✏️ Editada por ${esc(x.comercial)}</span></div>`
          : `<div style="margin-top:2px;"><span style="font-size:10px;color:#0F7A5C;">🤖 Autogenerado (cliente)</span></div>`);
      return `<div class="crm-card-mob">
        <div class="crm-card-mob-header">
          <div style="flex:1;">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">${tipoBadge}</div>
            <input type="text" class="crmsp-aud-input" style="font-weight:600;font-size:14px;" value="${esc(x.empresa)}" onblur="crmspAuditoriaEditarCampoInline('${x.tipo}','${x.id}','empresa', this.value)">
            <input type="text" class="crmsp-aud-input" placeholder="Persona de contacto" style="margin-top:2px;" value="${esc(x.contacto||'')}" onblur="crmspAuditoriaEditarCampoInline('${x.tipo}','${x.id}','contacto', this.value)">
            ${origenBadge}
          </div>
          <span style="font-size:11px;padding:3px 10px;border-radius:10px;background:${x.completada?'#D1FAE5':'#F3F4F6'};color:${x.completada?'#065F46':'#6B7280'};font-weight:600;white-space:nowrap;flex-shrink:0;">${x.completada?'✓ Respondido':'Sin responder'}</span>
        </div>
        <div class="crm-card-mob-body">
          <select class="crmsp-aud-input" style="margin-bottom:6px;" onchange="crmspAuditoriaEditarCampoInline('${x.tipo}','${x.id}','responsable', this.value)">
            <option value="">— Responsable —</option>
            ${getUsuariosNombresCRMSP().map(n=>`<option value="${esc(n)}" ${x.responsable===n?'selected':''}>${esc(n)}</option>`).join('')}
          </select>
          <div style="margin-top:6px;">${_badgeSeguimientoAuditoriaSP(x.seguimiento)}</div>
          ${x.fechaEnvio ? `<div style="font-size:11px;color:var(--muted);margin-top:4px;"><i class="ti ti-send" style="font-size:11px;"></i> Enviado: ${esc(fmtDate(x.fechaEnvio))}</div>` : ''}
          <div style="display:flex;gap:8px;margin-top:8px;">
            <button onclick="crmspEnviarAutodiagnosticoSP('${x.tipo}','${x.id}')" class="btn-sm" style="flex:1;"><i class="ti ti-link" style="font-size:12px;" aria-hidden="true"></i> Enviar</button>
            <button onclick="abrirModalAuditoriaSP('${x.id}','${x.tipo}')" class="btn-sm" style="flex:1;"><i class="ti ${x.completada?'ti-edit':'ti-clipboard-plus'}" style="font-size:12px;" aria-hidden="true"></i> ${x.completada?'Editar':'Rellenar'}</button>
          </div>
        </div>
      </div>`;
    }).join('')}
  </div>`;
}

function abrirModalAuditoriaSP(id, tipo) {
  tipo = tipo === 'lead' ? 'lead' : 'contacto';
  const c = tipo === 'lead' ? (data.leadsSP||[]).find(x => x.id === id) : (data.contactosSP||[]).find(x => x.id === id);
  if (!c) { showToast(tipo === 'lead' ? 'Lead no encontrado' : 'Propuesta no encontrada'); return; }
  const a = (tipo === 'lead' ? c.auditoriaPublicaRespuesta : c.auditoria) || {};
  const serviciosMarcados = Array.isArray(a.serviciosInteres) ? a.serviciosInteres : [];

  const radioGroup = (nombre, valorActual, etiqueta) => `
    <div class="form-group"><label>${etiqueta}</label>
      <div style="display:flex;gap:16px;margin-top:4px;">
        <label style="display:flex;align-items:center;gap:6px;font-weight:400;font-size:13px;cursor:pointer;"><input type="radio" name="${nombre}" value="Si" ${valorActual==='Si'?'checked':''}> Sí</label>
        <label style="display:flex;align-items:center;gap:6px;font-weight:400;font-size:13px;cursor:pointer;"><input type="radio" name="${nombre}" value="No" ${valorActual==='No'?'checked':''}> No</label>
      </div>
    </div>`;

  const body = `
    <p style="font-size:12px;color:var(--muted);margin:0 0 14px;">Rellénala durante la visita/llamada con <strong>${esc(c.empresa)}</strong>, o corrige aquí lo que haya contestado desde el enlace público. Sirve para detectar qué necesita realmente antes de preparar la propuesta.</p>

    <div style="font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.05em;margin:8px 0 10px;padding-bottom:6px;border-bottom:2px solid var(--purple-l);">Perfil de la empresa</div>
    <div class="crm-form-grid" style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px;">
      <div class="form-group"><label>Sector / Actividad</label>
        <select id="aud-sector">
          <option value="">— Selecciona —</option>
          ${CRMSP_AUDITORIA_SECTORES.map(s => `<option value="${esc(s)}" ${a.sector===s?'selected':''}>${esc(s)}</option>`).join('')}
        </select>
      </div>
      <div class="form-group"><label>Tipo</label>
        <select id="aud-tipoPersona">
          <option value="">— Selecciona —</option>
          <option value="Persona Física" ${a.tipoPersona==='Persona Física'?'selected':''}>Persona Física</option>
          <option value="Persona Jurídica" ${a.tipoPersona==='Persona Jurídica'?'selected':''}>Persona Jurídica</option>
        </select>
      </div>
      <div class="form-group"><label>Número de trabajadores</label>
        <input type="number" min="0" id="aud-numTrabajadores" value="${a.numTrabajadores ?? ''}">
      </div>
      <div class="form-group"><label>Número de usuarios con acceso a datos</label>
        <input type="number" min="0" id="aud-numUsuarios" value="${a.numUsuarios ?? ''}">
      </div>
    </div>

    <div style="font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.05em;margin:16px 0 10px;padding-bottom:6px;border-bottom:2px solid var(--purple-l);">Situación actual</div>
    <div class="crm-form-grid" style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px;">
      <div class="form-group">
        <label>¿Maneja alimentos (restauración, alimentación)? <span style="font-weight:400;color:var(--muted);font-size:11px;">Sector Turismo Hostelería</span></label>
        <div style="display:flex;gap:16px;margin-top:4px;">
          <label style="display:flex;align-items:center;gap:6px;font-weight:400;font-size:13px;cursor:pointer;"><input type="radio" name="aud-alimentos" value="Si" ${a.manejaAlimentos==='Si'?'checked':''}> Sí</label>
          <label style="display:flex;align-items:center;gap:6px;font-weight:400;font-size:13px;cursor:pointer;"><input type="radio" name="aud-alimentos" value="No" ${a.manejaAlimentos==='No'?'checked':''}> No</label>
        </div>
      </div>
      ${radioGroup('aud-web', a.tieneWeb, '¿Tiene página web / tienda online?')}
    </div>

    <div style="font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.05em;margin:16px 0 10px;padding-bottom:6px;border-bottom:2px solid var(--purple-l);">Servicios contratados actualmente</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px 16px;margin-bottom:8px;">
      ${CRMSP_AUDITORIA_SERVICIOS_SIN_EMPLEADOS.map(s => `<label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer;">
        <input type="checkbox" class="aud-servicio-check" value="${s.key}" ${serviciosMarcados.includes(s.key)?'checked':''}> ${esc(s.label)}
      </label>`).join('')}
    </div>
    <div style="font-size:11px;color:var(--muted);margin:10px 0 6px;padding-top:8px;border-top:1px dashed var(--border);">Estos 3 servicios <strong>no aplican si la empresa no tiene empleados</strong>:</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px 16px;margin-bottom:8px;">
      ${CRMSP_AUDITORIA_SERVICIOS_CON_EMPLEADOS.map(s => `<label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer;">
        <input type="checkbox" class="aud-servicio-check" value="${s.key}" ${serviciosMarcados.includes(s.key)?'checked':''}> ${esc(s.label)}
      </label>`).join('')}
    </div>

    <div class="form-group" style="margin-top:10px;"><label>Notas</label>
      <textarea id="aud-notas" placeholder="Observaciones, necesidades detectadas, urgencia..." style="min-height:70px;">${esc(a.notas||'')}</textarea>
    </div>
    <div class="form-group"><label>Responsable</label>
      <select id="aud-comercial">
        <option value="">— Selecciona —</option>
        ${getUsuariosNombresCRMSP().map(n => `<option value="${esc(n)}" ${(a.comercial || c.responsable || currentUserNombre || '')===n?'selected':''}>${esc(n)}</option>`).join('')}
      </select>
    </div>`;

  _modalCustomCallback = () => {
    const motivoRadio = (nombre) => document.querySelector(`input[name="${nombre}"]:checked`)?.value || '';
    const serviciosInteres = Array.from(document.querySelectorAll('.aud-servicio-check:checked')).map(chk => chk.value);
    const auditoria = {
      empresa: c.empresa || a.empresa || '',
      contacto: c.contacto || a.contacto || '',
      telefono: c.telefono || a.telefono || '',
      email: c.email || a.email || '',
      sector: document.getElementById('aud-sector')?.value || '',
      tipoPersona: document.getElementById('aud-tipoPersona')?.value || '',
      numTrabajadores: Number(document.getElementById('aud-numTrabajadores')?.value) || 0,
      numUsuarios: Number(document.getElementById('aud-numUsuarios')?.value) || 0,
      manejaAlimentos: motivoRadio('aud-alimentos'),
      tieneWeb: motivoRadio('aud-web'),
      serviciosInteres,
      notas: document.getElementById('aud-notas')?.value?.trim() || '',
      comercial: document.getElementById('aud-comercial')?.value?.trim() || '',
      fecha: a.fecha || new Date().toISOString().slice(0,10),
      interesContratacion: a.interesContratacion ?? null,
    };

    if (tipo === 'lead') {
      // Reutiliza exactamente el mismo camino que sigue la respuesta cuando
      // la rellena el propio cliente (crea/actualiza el contacto vinculado
      // y genera la propuesta automáticamente) — así rellenarla a mano
      // desde aquí tiene el mismo efecto que si el cliente la respondiera.
      const token = _crmspAsegurarPublicTokenSP(c);
      _procesarRespuestaAuditoriaSP(token, auditoria);
      saveData(['leadsSP','contactosSP','crmSPActividad']);
      logAction('EDITAR', 'Autodiagnóstico (lead)', c.empresa);
      closeModal();
      renderLeadsSP();
      if (typeof renderCRMSPAuditoria === 'function') renderCRMSPAuditoria();
    } else {
      const idx = (data.contactosSP||[]).findIndex(x => x.id === id);
      if (idx < 0) return;
      data.contactosSP[idx].auditoria = auditoria;
      data.contactosSP[idx].auditoriaRealizada = true;
      if (!Array.isArray(data.contactosSP[idx].seguimiento)) data.contactosSP[idx].seguimiento = [];
      data.contactosSP[idx].seguimiento.push({ fecha: auditoria.fecha, texto: 'Autodiagnóstico de necesidades rellenado' });
      saveData(['contactosSP']);
      logAction('EDITAR', 'Autodiagnóstico CRM Serv. Prof.', c.empresa);
      closeModal();
      renderCRMSP();
      if (typeof renderCRMSPAuditoria === 'function') renderCRMSPAuditoria();
    }
    showToast('Autodiagnóstico guardado ✓');
  };

  openModalCustom('Autodiagnóstico de cliente — ' + c.empresa, body);
  document.querySelector('.modal')?.classList.add('modal-wide');
  const hdrActions = document.getElementById('modal-header-actions');
  if (hdrActions) hdrActions.innerHTML = '';
}


/* ═══════════════════════════════════════════════════
   FORMULARIO PÚBLICO DE AUDITORÍA (?auditoria=<token>)
   Sin login. Se activa desde el guard al principio de DOMContentLoaded,
   que corta la carga normal de la app. Solo puede ESCRIBIR (nunca leer)
   en el nodo Firebase "auditoriasPublicas/<token>" — ver la nota de
   Reglas de Seguridad más abajo en abrirModalReglasAuditoriaPublica().
   ═══════════════════════════════════════════════════ */
// ═══════════════════════════════════════════════════════════════════
// CONFIGURACIÓN DE LA PORTADA DEL AUTODIAGNÓSTICO — TEXTO 100% EDITABLE
// ═══════════════════════════════════════════════════════════════════
// Todo el copy de la landing (portada) vive aquí, en un único objeto.
// Para cambiar cualquier texto de la portada NO hace falta tocar el HTML
// de renderAuditoriaPublicaPage — basta con editar los valores de este
// objeto. Esto es intencional: separa "qué se dice" de "cómo se pinta",
// para que el equipo de marketing/ventas pueda iterar el mensaje sin
// depender de que un desarrollador toque la plantilla cada vez.
//
// heroImagen: mockup fotorrealista de un portátil con la pantalla del
// autodiagnóstico ya integrada (checklist + 72% + botón "Ver resultados").
// Al venir todo "quemado" en la propia imagen, no hace falta ninguna
// tarjeta superpuesta encima. Alojada en el propio proyecto (img/), no en
// caliente contra un banco de imágenes.
// Iconos en SVG puro, sin depender de vendor/tabler-icons — en pruebas, la
// fuente de iconos no cargaba en esta página pública en concreto (aunque sí
// funciona en el resto del CRM), dejando círculos vacíos. Usar SVG inline
// garantiza que se vean siempre, en cualquier entorno, sin depender de que
// cargue ningún archivo de fuente externo.
const CRMSP_AUD_ICONOS_SVG = {
  'shield-check': '<path d="M12 3l7 3v6c0 5-3.5 8-7 9-3.5-1-7-4-7-9V6l7-3z"/><path d="M9 12l2 2 4-4"/>',
  'trending-up':  '<path d="M3 17l6-6 4 4 8-8"/><path d="M17 5h4v4"/>',
  'clock':        '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/>',
  'users':        '<circle cx="8" cy="8" r="3"/><circle cx="16" cy="9" r="2.5"/><path d="M2 20c0-3.5 2.7-6 6-6s6 2.5 6 6"/><path d="M14 14.5c2.6.3 5 2 5.5 5.5"/>',
  'lock':         '<rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V7a4 4 0 018 0v4"/>',
  'file-text':    '<path d="M6 3h9l4 4v14H6z"/><path d="M15 3v4h4"/><path d="M9 12h7M9 16h7"/>',
  'chart-pie':    '<path d="M12 3v9l7 4A9 9 0 1012 3z"/>',
  'search':       '<circle cx="10" cy="10" r="6.5"/><path d="M19.5 19.5l-5-5"/>',
  'clipboard-check':'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V3a1 1 0 011-1h4a1 1 0 011 1v1"/><path d="M9 13l2 2 4-4"/>',
  'clipboard-list':'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V3a1 1 0 011-1h4a1 1 0 011 1v1"/><path d="M9 12h7M9 16h7M9 8h3"/>',
  'building':     '<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M8 7h2M14 7h2M8 11h2M14 11h2M8 15h2M14 15h2"/>',
  'building-store':'<path d="M4 9l1-5h14l1 5"/><path d="M4 9v11h16V9"/><path d="M9 20v-6h6v6"/>',
  'briefcase':    '<rect x="3" y="8" width="18" height="12" rx="2"/><path d="M8 8V6a2 2 0 012-2h4a2 2 0 012 2v2"/><path d="M3 13h18"/>',
  'user':         '<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.5 3.5-7 8-7s8 2.5 8 7"/>',
  'ban':          '<circle cx="12" cy="12" r="9"/><path d="M5.5 5.5l13 13"/>',
  'world':        '<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.5 2.5 3.8 6 3.8 9s-1.3 6.5-3.8 9c-2.5-2.5-3.8-6-3.8-9s1.3-6.5 3.8-9z"/>',
  'mail':         '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 7l9 6 9-6"/>',
  'helmet':       '<path d="M4 14a8 8 0 0116 0"/><path d="M2 14h20"/><path d="M2 14v3a2 2 0 002 2h1"/><path d="M22 14v3a2 2 0 01-2 2h-1"/>',
  'soup':         '<path d="M4 12h16a8 4 0 01-16 0z"/><path d="M8 12V9M12 12V7M16 12V9"/>',
  'circle-check': '<circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-6"/>',
  'circle':       '<circle cx="12" cy="12" r="9"/>',
};
function audIconoSVG(nombre, cls) {
  const inner = CRMSP_AUD_ICONOS_SVG[nombre] || CRMSP_AUD_ICONOS_SVG['circle'];
  return `<svg${cls?` class="${cls}"`:''} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="width:1em;height:1em;display:inline-block;vertical-align:-0.15em;">${inner}</svg>`;
}

// Config de la portada (copy + orden de bullets/pasos/áreas) — vive en un
// JSON aparte (config/autodiagnostico-landing.json), no incrustado aquí.
// El equipo de marketing/ventas puede editar ese JSON directamente sin
// tocar código, y de cara a la futura migración a Python es exactamente
// el mismo objeto que se serviría desde el backend (por ejemplo como
// respuesta de un endpoint /api/autodiagnostico/config, o cargado por el
// propio servidor al renderizar la plantilla).
let _audLandingConfigCache = null;
async function _fetchAudLandingConfig() {
  if (_audLandingConfigCache) return _audLandingConfigCache;
  try {
    const r = await fetch('config/autodiagnostico-landing.json');
    if (!r.ok) throw new Error('HTTP ' + r.status);
    _audLandingConfigCache = await r.json();
  } catch (e) {
    console.error('No se pudo cargar config/autodiagnostico-landing.json, usando contenido mínimo de reserva.', e);
    // Reserva mínima para que la página nunca se quede completamente en
    // blanco si el JSON no carga (p.ej. desplegado sin ese archivo) — no
    // es el copy real, solo evita una pantalla rota.
    _audLandingConfigCache = {
      headerTag: 'Dirigido a empresas y autónomos', heroImagen: '',
      kicker: 'Cumplimiento normativo', tituloNegro: '¿Tu empresa cumple con la normativa?', tituloAzul: '',
      subtitulo: '', bullets: [], ctaPrincipal: 'Realizar autodiagnóstico →', trust: '',
      comoFunciona: { titulo: '¿Cómo funciona?', pasos: [] },
      areasIncluidas: { titulo: 'Áreas de cumplimiento incluidas', items: [] },
      audiencia: { titulo: '¿A quién va dirigido?', items: [] },
      statsBar: { titulo: '', items: [] },
      ctaFinal: { titulo: '', subtitulo: '', subtituloDestacado: '', boton: 'Empezar →', trust: '' },
    };
  }
  return _audLandingConfigCache;
}



async function renderAuditoriaPublicaPage(token, empresa, contacto) {
  document.title = 'Autodiagnóstico gratuito de cumplimiento normativo — Moore Market';
  document.documentElement.style.background = '#eef2f6';

  // El CSS y el texto de la portada viven en archivos aparte
  // (css/autodiagnostico.css y config/autodiagnostico-landing.json), no
  // incrustados aquí — así se pueden editar sin tocar app.js, y de cara a
  // una futura migración a Python el HTML/CSS ya está separado de la
  // lógica, listo para servirse como plantilla o archivo estático normal.
  if (!document.getElementById('aud-pub-css')) {
    const link = document.createElement('link');
    link.id = 'aud-pub-css';
    link.rel = 'stylesheet';
    link.href = 'css/autodiagnostico.css';
    document.head.appendChild(link);
  }

  const sectorCards = CRMSP_AUDITORIA_SECTORES.map((s,i) => `
    <div class="opt-card">
      <input type="radio" name="pub-sector-radio" id="sec-${i}" value="${esc(s)}" onchange="_audPubSectorSeleccionado('${esc(s)}')">
      <label for="sec-${i}"><span class="opt-check"></span>${esc(s)}</label>
    </div>`).join('');

  const cfg = await _fetchAudLandingConfig();

  // Escena fotográfica del portátil con el autodiagnóstico ya en pantalla
  // (checklist, 72% y botón vienen "quemados" en la propia imagen, así que
  // no hace falta ninguna tarjeta superpuesta encima).
  const heroVisualHTML = `
    <div class="hero-photo">
      <img src="${esc(cfg.heroImagen)}" alt="Portátil mostrando el resultado del autodiagnóstico de cumplimiento">
    </div>`;

  document.body.innerHTML = `
    <div class="progress-outer" id="aud-progress-outer">
      <div class="progress-inner">
        <div class="progress-top-row">
          <button type="button" class="progress-back" id="aud-back-btn" onclick="_audPubBack()">← Atrás</button>
          <span class="progress-step-lbl" id="aud-step-lbl"></span>
        </div>
        <div class="progress-bar-bg"><div class="progress-bar-fill" id="aud-progress-fill" style="width:0%;"></div></div>
      </div>
    </div>

    <!-- PANTALLA 0 — Portada (a todo el ancho, dos columnas en escritorio) -->
    <div class="aud-screen active" data-screen="intro">

      <!-- Cabecera -->
      <div class="landing-header">
        <img src="${SP_OFERTA_LOGO_B64}" alt="Moore Market" style="width:110px;">
        <div class="landing-header-tag">${audIconoSVG('users')} ${esc(cfg.headerTag)}</div>
      </div>

      <!-- Héroe — 2 columnas: texto unificado | foto centrada -->
      <div class="hero-wrap">
        <div class="hero-col-texto">
          <div class="hero-kicker">${esc(cfg.kicker)}</div>
          <h1 class="hero-title">${esc(cfg.tituloNegro)}<br><span class="hero-title-accent">${esc(cfg.tituloAzul)}</span></h1>
          <div class="hero-sub">${empresa ? `Hola${contacto?' '+esc(contacto):''}, este autodiagnóstico es para <strong>${esc(empresa)}</strong>. ` : ''}${esc(cfg.subtitulo)}</div>
          <div class="hero-bullets">
            ${cfg.bullets.map(b => `<div class="hb-item">${audIconoSVG(b.icono)} ${esc(b.texto)}</div>`).join('')}
          </div>
          <div class="hero-btns">
            <button type="button" class="cta-empezar" onclick="_audPubGoto('sector')">${esc(cfg.ctaPrincipal)}</button>
          </div>
          <div class="hero-trust">${audIconoSVG('lock')}&nbsp; ${esc(cfg.trust)}</div>
        </div>

        <div class="hero-col-imagen">${heroVisualHTML}</div>
      </div>

      <!-- Segunda sección — "cómo funciona" + las 2 cajas, con más espacio -->
      <div class="landing-section landing-como-funciona">
        <h2 class="hc-titulo">${esc(cfg.comoFunciona.titulo)}</h2>
        <div class="hc-steps-row">
          ${cfg.comoFunciona.pasos.map((p,i) => `
            <div class="hc-step-col">
              <div class="hc-icon-wrap"><div class="hc-icon">${audIconoSVG(p.icono)}</div><span class="hc-num-badge">${i+1}</span></div>
              <div class="hc-step-text"><strong>${esc(p.titulo)}</strong><p>${esc(p.texto)}</p></div>
            </div>`).join('')}
        </div>
        <div class="hc-boxes-row">
          <div class="hc-box">
            <h3 class="hc-box-titulo">${esc(cfg.areasIncluidas.titulo)}</h3>
            ${cfg.areasIncluidas.items.map(a => `<div class="hc-area-item">${audIconoSVG(a.icono)} ${esc(a.texto)}</div>`).join('')}
          </div>
          <div class="hc-box">
            <h3 class="hc-box-titulo">${esc(cfg.audiencia.titulo)}</h3>
            ${cfg.audiencia.items.map(a => `
              <div class="hc-audiencia-item">
                <img class="hc-audiencia-foto" src="${esc(a.foto)}" alt="">
                <div><strong>${esc(a.titulo)}</strong><p>${esc(a.texto)}</p></div>
              </div>`).join('')}
          </div>
        </div>
      </div>

      <!-- Pie de página — barra de estadísticas + CTA final -->
      <div class="landing-stats-bar">
        <h3 class="landing-h3" style="text-align:center;margin-bottom:20px;">${esc(cfg.statsBar.titulo)}</h3>
        <div class="landing-section landing-stats-row">
          ${cfg.statsBar.items.map(s => `<div class="stat-item">${audIconoSVG(s.icono)}<span>${esc(s.texto)}</span></div>`).join('')}
        </div>
      </div>

      <div class="landing-cta-final">
        <div class="landing-section lcf-row">
          <div class="lcf-left">
            ${audIconoSVG('shield-check')}
            <div>
              <strong>${esc(cfg.ctaFinal.titulo)}</strong>
              <p>${esc(cfg.ctaFinal.subtitulo)}<span class="lcf-accent">${esc(cfg.ctaFinal.subtituloDestacado)}</span></p>
            </div>
          </div>
          <div class="lcf-right">
            <button type="button" class="cta-empezar" onclick="_audPubGoto('sector')">${esc(cfg.ctaFinal.boton)}</button>
            <div class="lcf-trust">${audIconoSVG('lock')} ${esc(cfg.ctaFinal.trust)}</div>
          </div>
        </div>
      </div>
    </div>

    <div class="wrap">
      <div class="logo-row"><img src="${SP_OFERTA_LOGO_B64}" alt="Moore Market"></div>

      <!-- PANTALLA 1 — Sector -->
      <div class="aud-screen" data-screen="sector">
        <div class="card-panel">
          <div class="q-icon">${audIconoSVG('building-store')}</div>
          <h2 class="q">¿A qué se dedica tu empresa?</h2>
          <div class="q-sub">Elige el sector que más se acerque a vuestra actividad</div>
          <input type="hidden" id="pub-sector">
          <div class="opt-grid">${sectorCards}</div>
        </div>
      </div>

      <!-- PANTALLA 2 — Tipo de persona -->
      <div class="aud-screen" data-screen="tipo">
        <div class="card-panel">
          <div class="q-icon">${audIconoSVG('briefcase')}</div>
          <h2 class="q">¿Cómo estáis dados de alta?</h2>
          <div class="q-sub">&nbsp;</div>
          <input type="hidden" id="pub-tipoPersona">
          <div class="opt-grid opt-1col">
            <div class="opt-card"><input type="radio" name="pub-tipo-radio" id="tipo-0" value="Persona Física" onchange="_audPubSetHiddenYAvanzar('pub-tipoPersona','Persona Física','plantilla')"><label for="tipo-0"><span class="opt-check"></span>Autónomo / Persona Física</label></div>
            <div class="opt-card"><input type="radio" name="pub-tipo-radio" id="tipo-1" value="Persona Jurídica" onchange="_audPubSetHiddenYAvanzar('pub-tipoPersona','Persona Jurídica','plantilla')"><label for="tipo-1"><span class="opt-check"></span>Sociedad (S.L., S.A....)</label></div>
          </div>
        </div>
      </div>

      <!-- PANTALLA 3 — Plantilla: trabajadores + usuarios con acceso a datos, en la misma pantalla -->
      <div class="aud-screen" data-screen="plantilla">
        <div class="card-panel">
          <div class="q-icon">${audIconoSVG('users')}</div>
          <h2 class="q">Cuéntanos sobre tu plantilla</h2>
          <div class="q-sub">&nbsp;</div>

          <div class="field-lbl" style="text-align:left;font-size:13px;font-weight:700;color:#173A5C;margin-bottom:2px;">¿Cuántos trabajadores tenéis?</div>
          <div class="field-hint" style="margin:0 0 6px;">Sin contar a los socios/autónomos que no están de alta como empleados</div>
          <div class="stepper-row" style="margin:10px 0 24px;">
            <button type="button" class="stepper-btn" onclick="_audPubStep('pub-numTrabajadores',-1)">−</button>
            <span class="stepper-num" id="pub-numTrabajadores-display">0</span>
            <button type="button" class="stepper-btn" onclick="_audPubStep('pub-numTrabajadores',1)">+</button>
          </div>
          <input type="hidden" id="pub-numTrabajadores" value="0">

          <div class="field-lbl" style="text-align:left;font-size:13px;font-weight:700;color:#173A5C;margin-bottom:2px;">¿Cuántas personas acceden a datos de clientes?</div>
          <div class="field-hint" style="margin:0 0 6px;">Empleados, socios o colaboradores con acceso a datos personales (clientes, proveedores...)</div>
          <div class="stepper-row" style="margin:10px 0 4px;">
            <button type="button" class="stepper-btn" onclick="_audPubStep('pub-numUsuarios',-1)">−</button>
            <span class="stepper-num" id="pub-numUsuarios-display">0</span>
            <button type="button" class="stepper-btn" onclick="_audPubStep('pub-numUsuarios',1)">+</button>
          </div>
          <input type="hidden" id="pub-numUsuarios" value="0">

          <button type="button" class="continue-btn" onclick="_audPubGoto('web')">Continuar</button>
        </div>
      </div>

      <!-- PANTALLA 5 — Web / tienda online (+ alimentos si el sector es Hostelería y Turismo) -->
      <div class="aud-screen" data-screen="web">
        <div class="card-panel">
          <div class="q-icon">${audIconoSVG('world')}</div>
          <h2 class="q">Cuéntanos algo más de tu operativa</h2>
          <div class="q-sub">&nbsp;</div>

          <div class="field-lbl" style="text-align:left;font-size:13px;font-weight:700;color:#173A5C;margin-bottom:8px;">¿Tenéis página web o tienda online?</div>
          <div class="opt-grid" style="margin-bottom:22px;">
            <div class="opt-card"><input type="radio" name="pub-web" id="web-si" value="Si" onchange="_audPubValidarWebAlimentos()"><label for="web-si"><span class="opt-check"></span>Sí</label></div>
            <div class="opt-card"><input type="radio" name="pub-web" id="web-no" value="No" onchange="_audPubValidarWebAlimentos()"><label for="web-no"><span class="opt-check"></span>No</label></div>
          </div>

          <div id="web-alimentos-wrap" style="display:none;">
            <div class="field-lbl" style="text-align:left;font-size:13px;font-weight:700;color:#173A5C;margin-bottom:8px;">¿Manejáis alimentos? <span style="font-weight:400;color:#8b98a8;">Restauración, hostelería, venta o manipulación de alimentos</span></div>
            <div class="opt-grid">
              <div class="opt-card"><input type="radio" name="pub-alimentos" id="alim-si" value="Si" onchange="_audPubValidarWebAlimentos()"><label for="alim-si"><span class="opt-check"></span>Sí</label></div>
              <div class="opt-card"><input type="radio" name="pub-alimentos" id="alim-no" value="No" onchange="_audPubValidarWebAlimentos()"><label for="alim-no"><span class="opt-check"></span>No</label></div>
            </div>
          </div>

          <button type="button" class="continue-btn" id="web-continue-btn" onclick="_audPubGoto('servicios')" disabled>Continuar</button>
        </div>
      </div>

      <!-- PANTALLA 6 — Servicios contratados actualmente -->
      <div class="aud-screen" data-screen="servicios">
        <div class="card-panel">
          <div class="q-icon">${audIconoSVG('clipboard-list')}</div>
          <h2 class="q">¿Qué tenéis ya contratado?</h2>
          <div class="field-hint">Marca lo que ya tengáis (con nosotros o con otro proveedor) — así sabremos qué os falta. Si no tenéis nada, deja todo sin marcar y continúa.</div>
          <div id="pub-servicios">
            ${CRMSP_AUDITORIA_SERVICIOS_SIN_EMPLEADOS.map((s,i) => `
              <div class="check-card"><input type="checkbox" id="serv-${i}" value="${s.key}"><label for="serv-${i}"><span class="chk-box"></span>${esc(s.label)}</label></div>`).join('')}
            <div id="pub-servicios-con-wrap" style="display:none;">
              ${CRMSP_AUDITORIA_SERVICIOS_CON_EMPLEADOS.map((s,i) => `
                <div class="check-card"><input type="checkbox" id="servc-${i}" value="${s.key}"><label for="servc-${i}"><span class="chk-box"></span>${esc(s.label)}</label></div>`).join('')}
            </div>
          </div>
          <button type="button" class="continue-btn" onclick="_audPubGoto('contacto')">Continuar</button>
        </div>
      </div>

      <!-- PANTALLA 7 — Datos de contacto + envío -->
      <div class="aud-screen" data-screen="contacto">
        <div class="card-panel">
          <div class="q-icon">${audIconoSVG('mail')}</div>
          <h2 class="q" id="contacto-q-titulo">¡Ya casi está! Dinos dónde enviarte el resultado</h2>
          <div class="q-sub" id="contacto-q-sub">&nbsp;</div>
          <div id="aud-pub-form-wrap">
            <form id="aud-pub-form" onsubmit="return false;">
              <div class="field"><label class="field-lbl">Nombre de la empresa *</label><input type="text" id="pub-empresa" value="${esc(empresa||'')}"></div>
              <div class="field"><label class="field-lbl">Persona de contacto</label><input type="text" id="pub-contacto" value="${esc(contacto||'')}"></div>
              <div class="field"><label class="field-lbl">Teléfono</label><input type="text" id="pub-telefono"></div>
              <div class="field"><label class="field-lbl">Email *</label><input type="email" id="pub-email"></div>
              <div class="field"><label class="field-lbl">¿Algo más que debamos saber? (opcional)</label><textarea id="pub-notas" placeholder="Cuéntanos brevemente qué necesitáis o qué os preocupa..."></textarea></div>
              <button class="submit-btn" id="pub-submit-btn" onclick="enviarAuditoriaPublicaSP('${esc(token)}')">Ver mi resultado ahora →</button>
              <div class="status" id="pub-status"></div>
            </form>
          </div>
        </div>
      </div>

      <div class="disclaimer">Tus datos se usan únicamente para prepararte una propuesta de cumplimiento normativo adaptada a tu empresa. Moore Market · Legal y Cumplimiento Normativo.</div>
    </div>`;

  _audPubGoto('intro');
}

/* ═══════════════════════════════════════
   NAVEGACIÓN DEL ASISTENTE PASO A PASO
   Una pregunta grande por pantalla, con avance automático al elegir en
   preguntas de una sola respuesta (igual que los comparadores tipo
   precio.com) — solo hace falta pulsar "Continuar" en las pantallas de
   selección múltiple o de números.
   ═══════════════════════════════════════ */
// Orden de pantallas — la pregunta de alimentos ya no es una pantalla
// propia: vive dentro de "web" y se muestra u oculta ahí mismo según el
// sector (ver _audPubGoto y _audPubValidarWebAlimentos).
function _audPubStepsSP() {
  return ['sector','tipo','plantilla','web','servicios','contacto'];
}

function _audPubGoto(screenId) {
  document.querySelectorAll('.aud-screen').forEach(el => el.classList.remove('active'));
  const target = document.querySelector(`.aud-screen[data-screen="${screenId}"]`);
  if (target) target.classList.add('active');

  // Al entrar en la pantalla "web", se decide si hace falta también la
  // pregunta de alimentos (solo si el sector elegido es Hostelería y
  // Turismo) y se revalida el botón de continuar.
  if (screenId === 'web') {
    const sector = document.getElementById('pub-sector')?.value || '';
    const esHosteleria = sector === 'Hostelería y Turismo';
    const wrapAlimentos = document.getElementById('web-alimentos-wrap');
    if (wrapAlimentos) wrapAlimentos.style.display = esHosteleria ? '' : 'none';
    if (!esHosteleria) {
      document.querySelectorAll('input[name="pub-alimentos"]').forEach(r => { r.checked = false; });
    }
    _audPubValidarWebAlimentos();
  }

  const pasos = _audPubStepsSP();
  const idx = pasos.indexOf(screenId);
  const progressOuter = document.getElementById('aud-progress-outer');
  const backBtn = document.getElementById('aud-back-btn');
  const lbl = document.getElementById('aud-step-lbl');
  const fill = document.getElementById('aud-progress-fill');

  if (screenId === 'intro' || idx < 0) {
    // En la portada no hay progreso que mostrar todavía — se oculta del
    // todo la barra en vez de dejarla vacía, para no restarle protagonismo
    // al héroe de dos columnas.
    if (progressOuter) progressOuter.classList.add('hidden');
    if (backBtn) backBtn.classList.remove('show');
    if (lbl) lbl.textContent = '';
    if (fill) fill.style.width = '0%';
  } else {
    if (progressOuter) progressOuter.classList.remove('hidden');
    if (backBtn) backBtn.classList.add('show');
    if (lbl) lbl.textContent = `Paso ${idx+1} de ${pasos.length}`;
    if (fill) fill.style.width = Math.round(((idx+1)/pasos.length)*100) + '%';
  }
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// Habilita el botón "Continuar" de la pantalla "web" solo cuando están
// respondidas todas las preguntas que tocan en ella: la de web siempre, y
// la de alimentos solo si está visible (sector Hostelería y Turismo).
function _audPubValidarWebAlimentos() {
  const webResp = document.querySelector('input[name="pub-web"]:checked');
  const wrapAlimentos = document.getElementById('web-alimentos-wrap');
  const alimentosVisible = wrapAlimentos && wrapAlimentos.style.display !== 'none';
  const alimentosResp = document.querySelector('input[name="pub-alimentos"]:checked');
  const btn = document.getElementById('web-continue-btn');
  if (!btn) return;
  btn.disabled = !webResp || (alimentosVisible && !alimentosResp);
}

function _audPubBack() {
  const actual = document.querySelector('.aud-screen.active')?.dataset.screen;
  const pasos = _audPubStepsSP();
  const idx = pasos.indexOf(actual);
  if (idx <= 0) { _audPubGoto('intro'); return; }
  _audPubGoto(pasos[idx-1]);
}

// Sector: además de avanzar, decide si hay que enseñar la pregunta de
// alimentos más adelante (ver _audPubStepsSP).
function _audPubSectorSeleccionado(valor) {
  document.getElementById('pub-sector').value = valor;
  _audPubGoto('tipo');
}

function _audPubSetHiddenYAvanzar(inputId, valor, siguiente) {
  const el = document.getElementById(inputId);
  if (el) el.value = valor;
  _audPubGoto(siguiente);
}

// Contador +/- de trabajadores / usuarios — nunca baja de 0.
function _audPubStep(inputId, delta) {
  const input = document.getElementById(inputId);
  const display = document.getElementById(inputId + '-display');
  const nuevo = Math.max(0, (Number(input.value)||0) + delta);
  input.value = nuevo;
  if (display) display.textContent = nuevo;
  if (inputId === 'pub-numTrabajadores') toggleAuditoriaPublicaServiciosSP();
}

// Los 3 servicios que solo aplican con personal contratado (registro
// horario, PRL, acoso) solo se muestran si la empresa tiene al menos 1
// trabajador — si no, se ocultan y se desmarcan.
function toggleAuditoriaPublicaServiciosSP() {
  const num = Number(document.getElementById('pub-numTrabajadores')?.value) || 0;
  const wrap = document.getElementById('pub-servicios-con-wrap');
  if (!wrap) return;
  wrap.style.display = num >= 1 ? '' : 'none';
  if (num < 1) {
    wrap.querySelectorAll('input[type=checkbox]').forEach(chk => { chk.checked = false; });
  }
}

async function enviarAuditoriaPublicaSP(token) {
  const btn = document.getElementById('pub-submit-btn');
  const status = document.getElementById('pub-status');
  const empresa = document.getElementById('pub-empresa')?.value?.trim();
  const email = document.getElementById('pub-email')?.value?.trim();
  if (!empresa || !email) {
    status.className = 'status err';
    status.textContent = 'Indica al menos el nombre de la empresa y el email.';
    return;
  }

  const radioValue = (nombre) => document.querySelector(`input[name="${nombre}"]:checked`)?.value || '';
  const serviciosInteres = Array.from(document.querySelectorAll('#pub-servicios input:checked')).map(chk => chk.value);

  const respuesta = {
    empresa,
    contacto: document.getElementById('pub-contacto')?.value?.trim() || '',
    telefono: document.getElementById('pub-telefono')?.value?.trim() || '',
    email,
    sector: document.getElementById('pub-sector')?.value || '',
    tipoPersona: document.getElementById('pub-tipoPersona')?.value || '',
    numTrabajadores: Number(document.getElementById('pub-numTrabajadores')?.value) || 0,
    numUsuarios: Number(document.getElementById('pub-numUsuarios')?.value) || 0,
    manejaAlimentos: radioValue('pub-alimentos'),
    tieneWeb: radioValue('pub-web'),
    serviciosInteres,
    notas: document.getElementById('pub-notas')?.value?.trim() || '',
    fecha: new Date().toISOString().slice(0,10),
    comercial: '', // se rellena solo si un comercial la completa junto al cliente desde el panel interno
    interesContratacion: null, // null = todavía no ha elegido; true/false una vez pulsa un botón del informe
  };

  btn.disabled = true;
  btn.textContent = 'Enviando...';
  status.className = 'status';
  status.textContent = '';

  try {
    if (typeof firebase === 'undefined' || !firebase.initializeApp) throw new Error('Firebase no disponible');
    let app;
    try { app = firebase.app('auditoriaPublica'); } catch (e) { app = firebase.initializeApp(FIREBASE_CONFIG, 'auditoriaPublica'); }
    await app.database().ref('auditoriasPublicas/' + token).set(respuesta);

    // Deja publicada de inmediato una propuesta con el paquete sugerido —
    // así el enlace ?propuesta=<token> (mismo token) ya funciona aunque
    // nadie del equipo haya abierto el panel todavía. Si algún día alguien
    // revisa la ficha a mano y cambia la propuesta, esa versión posterior
    // sustituye a esta automática sin problema (mismo nodo).
    _publicarPropuestaAutomaticaPublicaSP(app, token, respuesta).catch(err => {
      console.warn('No se pudo publicar la propuesta automática:', err?.message || err);
    });

    renderResultadoAutodiagnosticoPublicoSP(token, respuesta);
  } catch (err) {
    btn.disabled = false;
    btn.textContent = 'Enviar mi autodiagnóstico gratuito';
    status.className = 'status err';
    status.textContent = 'No se pudo enviar. Revisa tu conexión e inténtalo de nuevo. (' + (err?.message || err) + ')';
  }
}

// Publica automáticamente, desde el propio navegador del cliente (sin
// intervención del equipo), una propuesta con el paquete sugerido según
// sus respuestas — reutiliza el mismo nodo público (propuestasPublicas)
// y el mismo token que la auditoría, igual que hace el panel interno en
// _publicarPropuestaPublicaSP, pero sin depender de tener el panel
// abierto ni de data.contactosSP (esta instancia de Firebase es anónima).
async function _publicarPropuestaAutomaticaPublicaSP(app, token, respuesta) {
  const paqueteKey = crmspPaqueteSugeridoPorRespuesta(respuesta);
  const paquete = getSPTarifaItem(paqueteKey);
  if (!paquete) return;
  const payload = {
    empresa: respuesta.empresa || '',
    contacto: respuesta.contacto || '',
    servicios: [{ nombre: spNombreCliente(paquete.nombre), precio: paquete.precio, iva: !!paquete.iva }],
    total: paquete.precio || 0,
    fecha: new Date().toISOString().slice(0,10),
    origen: 'autodiagnostico_directo',
  };
  await app.database().ref('propuestasPublicas/' + token).update(payload);
}

// Informe de resultados — se muestra al instante nada más enviar el
// formulario (sin esperar a que nadie del equipo lo revise). Calcula el
// grado de cumplimiento, sugiere el paquete que mejor encaja (con precio
// real de Tarifas 2026) y dos CTAs: contratar directamente o pedir que
// les llamen. Ambas opciones quedan registradas en Firebase para que el
// equipo las vea — ver respuestaInteresAutodiagnosticoPublicoSP.
function renderResultadoAutodiagnosticoPublicoSP(token, respuesta) {
  const ev = evaluarAutodiagnosticoPublicoSP(respuesta);
  const scoreClass = ev.porcentaje >= 80 ? 'high' : ev.porcentaje >= 40 ? 'mid' : 'low';
  const pendientes = ev.totalAplican - ev.totalCumplen;

  const AUD_AREA_ICONS = { rgpd:'lock', lssice:'world', registro_horario:'clock', prl:'helmet', acoso:'shield-check' };
  const checkSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" style="width:12px;height:12px;"><path d="M4 12l5 5L20 6"/></svg>';

  const areasHTML = ev.areas.map(a => `
    <div class="area-row">
      <span class="area-icon ${a.cumple?'ok':'pend'}">${audIconoSVG(AUD_AREA_ICONS[a.key] || 'circle')}</span>
      <span class="area-label">${esc(a.label)}</span>
      ${a.cumple ? '<span class="badge-ok">AL DÍA</span>' : '<span class="badge-pend">PENDIENTE</span>'}
    </div>`).join('');

  // Desglose "por separado" → ahorro del pack. Solo se muestra si hay al
  // menos un servicio computable con tarifa real (ver
  // crmspDesglosePreciosPaqueteSP) y si el pack sale a cuenta frente a
  // contratarlos uno a uno — si no fuera así (el pack trae más cosas
  // incluidas gratis), se omite la comparación en vez de mostrar un
  // "ahorro" negativo que confundiría al cliente.
  const desglose = ev.paquete?.desglose;
  const ahorro = desglose ? desglose.sumaSeparado - ev.paquete.precio : 0;

  // Dos cajas separadas, cada una con su propio borde — misma agrupación
  // que ya usa el informe en PDF: la oferta recomendada (precio +
  // servicios incluidos) a la izquierda, el detalle de precio por
  // servicio + el ahorro a la derecha.
  const cajaOfertaHTML = ev.paquete ? `
    <div class="paquete-box-precio">
      <div class="paquete-ribbon">RECOMENDADO PARA VOSOTROS</div>
      <div class="paquete-nombre">${esc(ev.paquete.nombre)}</div>
      ${ev.paquete.nota ? `<div class="paquete-nota">${esc(ev.paquete.nota)}</div>` : ''}
      <div class="paquete-precio">${fmtEUR(ev.paquete.precio)}${ev.paquete.iva?' + IVA':''} <small>/ año</small></div>
      <div class="paquete-servicios-lista">
        ${ev.paquete.bullets.map(b=>`<div class="paquete-bullet">${checkSvg}<span>${esc(b)}</span></div>`).join('')}
      </div>
    </div>` : '';

  const cajaDetalleHTML = (desglose && desglose.items.length) ? `
    <div class="paquete-box-detalle">
      <div class="informe-section-titulo">Detalle de precio por servicio</div>
      ${desglose.items.map(it => `<div class="desglose-row"><span>${esc(it.label)}</span><span>${fmtEUR(it.precio)}${it.iva?' + IVA':''}</span></div>`).join('')}
      ${desglose.notaExtras ? `<div class="desglose-nota">+ ${esc(desglose.notaExtras)}</div>` : ''}
      <div class="desglose-row desglose-separado"><span>Si los contratases por separado</span><span>${fmtEUR(desglose.sumaSeparado)} + IVA</span></div>
      ${ahorro > 0 ? `<div class="desglose-ahorro">Os ahorráis ${fmtEUR(ahorro)} al año con el pack</div>` : ''}
    </div>` : '';

  const paqueteHTML = (cajaOfertaHTML || cajaDetalleHTML) ? `
    <div class="propuesta-precios-row-pantalla">
      ${cajaOfertaHTML}
      ${cajaDetalleHTML}
    </div>` : '';

  const autogestionHTML = ev.mostrarAutogestion ? `
    <div class="autogestion-box" style="text-align:left;margin-top:18px;margin-bottom:0;">
      <h2>${esc(CRMSP_AUDITORIA_AUTOGESTION_TITULO)}</h2>
      <p>${esc(CRMSP_AUDITORIA_AUTOGESTION_TEXTO)}</p>
    </div>` : '';

  // Frase de transición hacia la propuesta — en singular si la empresa no
  // tiene empleados (autónomo), en plural si sí los tiene.
  const esSingular = Number(respuesta?.numTrabajadores) < 1;
  const introComercialHTML = ev.paquete ? `
    <div class="intro-comercial">
      <span class="intro-comercial-icon">${audIconoSVG('shield-check')}</span>
      <p>${esc(esSingular ? CRMSP_AUDITORIA_INTRO_COMERCIAL_SINGULAR : CRMSP_AUDITORIA_INTRO_COMERCIAL_PLURAL)}</p>
    </div>` : '';

  const compromisoHTML = ev.paquete ? `
    <div class="autogestion-box" style="text-align:left;margin-top:18px;margin-bottom:0;">
      <h2>${esc(CRMSP_AUDITORIA_COMPROMISO_TITULO)}</h2>
      ${CRMSP_AUDITORIA_COMPROMISO_TEXTO.split('\n').map(p => `<p>${esc(p)}</p>`).join('')}
    </div>` : '';

  document.getElementById('aud-pub-form-wrap').innerHTML = `
    <div class="informe-card">
      <div class="informe-header-band" style="background-image:url(${SP_OFERTA_HEADER_BG_B64});">
        <div class="informe-header-inner">
          <div class="informe-header-top">
            <div class="informe-header-eyebrow">MOORE MARKET &middot; LEGAL Y CUMPLIMIENTO NORMATIVO</div>
            <div class="informe-header-pill">INFORME DE AUTODIAGNÓSTICO</div>
          </div>
          <div class="informe-header-titlebox"><h1>Informe de autodiagnóstico normativo</h1></div>
          <div class="informe-header-subtitle">Resultado de vuestro autodiagn&oacute;stico de cumplimiento</div>
          <div class="informe-header-client">${esc(respuesta.empresa)}</div>
          ${respuesta.contacto ? `<div class="informe-header-client">A la atenci&oacute;n de: ${esc(respuesta.contacto)}</div>` : ''}
        </div>
      </div>
      <div class="informe-top-grid" style="${introComercialHTML ? '' : 'grid-template-columns:1fr;max-width:420px;margin-left:auto;margin-right:auto;'}">
        <div class="informe-col-resultado">
          <div class="resultado-box-v2">
            <div class="num ${scoreClass}">${ev.porcentaje}%</div>
            <div class="txt">Grado de cumplimiento normativo estimado, a fecha de ${esc(fmtDate(respuesta.fecha))}.<br>${pendientes>0 ? `<strong>${pendientes} de ${ev.totalAplican} obligaciones sin resolver.</strong>` : '<strong>Todo en regla — enhorabuena.</strong>'}</div>
          </div>
          <div class="informe-section-titulo" style="margin-top:14px;">Áreas evaluadas</div>
          ${areasHTML}
          ${ev.seguridadAlimentaria ? `<div class="alimentaria-nota">🍽️ Al manejar alimentos, también os aplica la normativa de <strong>seguridad alimentaria y APPCC</strong> — incluida en el paquete Profesional Plus.</div>` : ''}
        </div>
        ${introComercialHTML}
      </div>
      <div class="informe-body-pad">
        ${paqueteHTML}
        ${compromisoHTML}
        ${autogestionHTML}
        <div class="cta-row">
          <button class="cta-primary" id="pub-cta-contratar" onclick="respuestaInteresAutodiagnosticoPublicoSP('${esc(token)}', true)">✓ Quiero contratarlo</button>
          <button class="cta-secondary" id="pub-cta-llamar" onclick="respuestaInteresAutodiagnosticoPublicoSP('${esc(token)}', false)">Prefiero que me llaméis</button>
        </div>
        <div class="pdf-link" onclick="descargarInformeAutodiagnosticoPDFSP('${esc(token)}')">📄 Ver informe en PDF</div>
      </div>
    </div>
    <div id="pub-interes-status" class="status"></div>`;

  const tituloEl = document.getElementById('contacto-q-titulo');
  const subEl = document.getElementById('contacto-q-sub');
  const iconEl = document.querySelector('[data-screen="contacto"] .q-icon');
  const panelEl = document.querySelector('[data-screen="contacto"] .card-panel');
  if (tituloEl) tituloEl.textContent = 'Aquí tienes tu informe. Te haremos llegar una copia por mail.';
  if (subEl) subEl.innerHTML = '&nbsp;';
  if (iconEl) iconEl.style.display = 'none';
  // Solo esta pantalla (ya con el informe dentro) rompe el ancho estrecho
  // de 640px del resto del asistente y usa todo el ancho disponible en
  // escritorio — el resto de pasos (preguntas) se quedan como estaban.
  if (panelEl) panelEl.classList.add('card-panel-informe');

  // Se guarda para poder generar el PDF sin tener que volver a leer el
  // formulario (ya no existe en el DOM en este punto).
  window.__ultimoAutodiagnosticoPublico = { token, respuesta, ev };
}

// Registra si el cliente quiere contratar directamente o prefiere que le
// llamen — ambas opciones quedan escritas en el mismo nodo público de la
// auditoría, visibles para el equipo desde el panel interno (ver
// renderLeadsSP / renderCRMSPAuditoria). El compromiso de horario de
// respuesta solo se promete para quien pide contratar ya.
async function respuestaInteresAutodiagnosticoPublicoSP(token, quiereContratar) {
  const btnC = document.getElementById('pub-cta-contratar');
  const btnL = document.getElementById('pub-cta-llamar');
  const status = document.getElementById('pub-interes-status');
  if (btnC) btnC.disabled = true;
  if (btnL) btnL.disabled = true;
  try {
    let app;
    try { app = firebase.app('auditoriaPublica'); } catch (e) { app = firebase.initializeApp(FIREBASE_CONFIG, 'auditoriaPublica'); }
    await app.database().ref('auditoriasPublicas/' + token).update({
      interesContratacion: quiereContratar,
      interesContratacionFecha: new Date().toISOString().slice(0,10),
    });
    const cont = document.querySelector('.cta-row').parentElement;
    document.querySelector('.cta-row').outerHTML = `
      <div class="done-box" style="margin-top:18px;">
        <div class="tick">✅</div>
        <div style="font-size:15px;font-weight:bold;color:#173A5C;margin-bottom:6px;">${quiereContratar ? '¡Perfecto!' : 'Anotado'}</div>
        <div style="font-size:13px;color:#55647a;">${quiereContratar ? 'Nuestro equipo os contactará en menos de 48 horas para formalizar la contratación.' : 'Nuestro equipo os llamará en los próximos días para resolver dudas y ver cómo poneros al día.'}</div>
      </div>`;
  } catch (err) {
    if (btnC) btnC.disabled = false;
    if (btnL) btnL.disabled = false;
    if (status) { status.className = 'status err'; status.textContent = 'No se pudo registrar tu respuesta. Inténtalo de nuevo.'; }
  }
}

// Genera el informe de resultados como una página HTML con el mismo
// lenguaje visual que la propuesta comercial interna (ver
// generarPropuestaHTMLSP) — cabecera con foto, franjas, cajas — en vez del
// PDF plano de antes (texto sin formato, dibujado a mano con jsPDF). Se
// abre en una pestaña nueva con un botón "Descargar / Imprimir PDF" que
// usa window.print(), igual que la propuesta: el navegador genera el PDF
// de verdad, con todo el estilo intacto, sin depender de jsPDF ni de ir
// recalculando posiciones de texto a mano.
function descargarInformeAutodiagnosticoPDFSP(token) {
  const datos = window.__ultimoAutodiagnosticoPublico;
  if (!datos || datos.token !== token) { alert('No se pudo generar el informe. Recarga la página e inténtalo de nuevo.'); return; }
  const { respuesta, ev } = datos;
  const pendientes = ev.totalAplican - ev.totalCumplen;

  const areasHTML = ev.areas.map(a => `
    <div class="servicio-row-inf">
      <span>${esc(a.label)}</span>
      <span class="tag-inf ${a.cumple ? 'ok' : 'pend'}">${a.cumple ? 'AL DÍA' : 'PENDIENTE'}</span>
    </div>`).join('');

  const paqueteHTML = ev.paquete ? `
    <div class="paquete-card recomendado">
      <div class="paquete-badge">RECOMENDADO PARA VOSOTROS</div>
      <h4>${esc(spNombreCliente(ev.paquete.nombre))}</h4>
      <div class="paquete-precio">${fmtEUR(ev.paquete.precio)}${ev.paquete.iva ? ' + IVA' : ''} / año</div>
      <div class="paquete-servicios" style="text-align:left;">
        <ul style="margin:0;padding-left:16px;">${ev.paquete.bullets.map(b => `<li>${esc(b)}</li>`).join('')}</ul>
      </div>
    </div>` : '';

  const desglose = ev.paquete?.desglose;
  const desgloseHTML = (desglose && desglose.items.length) ? `<div class="box">
    <h3>DETALLE DE PRECIO POR SERVICIO</h3>
    ${desglose.items.map(it => `<div class="servicio-row-inf"><span>${esc(it.label)}</span><span style="font-weight:bold;color:#1D7FB5;">${fmtEUR(it.precio)}${it.iva?' + IVA':''}</span></div>`).join('')}
    <div class="servicio-row-inf" style="color:#7C8CA0;"><span>Si los contratases por separado</span><span>${fmtEUR(desglose.sumaSeparado)} + IVA</span></div>
    ${(desglose.sumaSeparado - ev.paquete.precio) > 0 ? `<div class="desglose-ahorro-pdf">Os ahorráis ${fmtEUR(desglose.sumaSeparado - ev.paquete.precio)} al año con el pack</div>` : ''}
  </div>` : '';

  // Oferta recomendada y detalle de precios por separado, lado a lado
  // (antes iban uno debajo del otro) — así se aprovecha todo el ancho de
  // la página en vez de dejar la oferta centrada con espacio vacío a los
  // lados. Si solo hay uno de los dos (p.ej. sin desglose calculable),
  // ese único bloque ocupa toda la fila en vez de quedarse a medias.
  const propuestaPreciosHTML = (paqueteHTML || desgloseHTML) ? `
  <div class="propuesta-precios-row">
    ${paqueteHTML}
    ${desgloseHTML}
  </div>` : '';

  const autogestionHTML = ev.mostrarAutogestion ? `
    <div class="compromiso-box">
      <h3>${esc(CRMSP_AUDITORIA_AUTOGESTION_TITULO).toUpperCase()}</h3>
      <p>${esc(CRMSP_AUDITORIA_AUTOGESTION_TEXTO)}</p>
    </div>` : '';

  // Mismo bloque de "Compromiso operativo" que ya se muestra en pantalla
  // (ver renderResultadoAutodiagnosticoPublicoSP) — antes no se incluía en
  // el PDF descargable.
  const compromisoHTML = ev.paquete ? `
    <div class="compromiso-box">
      <h3>${esc(CRMSP_AUDITORIA_COMPROMISO_TITULO).toUpperCase()}</h3>
      ${CRMSP_AUDITORIA_COMPROMISO_TEXTO.split('\n').map(p => `<p>${esc(p)}</p>`).join('')}
    </div>` : '';

  // Misma frase de transición que ya se muestra en pantalla (ver
  // renderResultadoAutodiagnosticoPublicoSP) — en singular si la empresa
  // no tiene empleados (autónomo), en plural si sí los tiene. Se repite
  // aquí porque el PDF es una función y una plantilla HTML aparte, no
  // comparte el HTML de la pantalla.
  const esSingularPdf = Number(respuesta?.numTrabajadores) < 1;
  const introComercialHTML = ev.paquete ? `
    <div class="intro-comercial-pdf">
      <p>${esc(esSingularPdf ? CRMSP_AUDITORIA_INTRO_COMERCIAL_SINGULAR : CRMSP_AUDITORIA_INTRO_COMERCIAL_PLURAL)}</p>
    </div>` : '';

  const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<title>Informe de autodiagnóstico — ${esc(respuesta.empresa||'')}</title>
<style>
  * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  body { font-family: Arial, sans-serif; background: #eef2f6; margin: 0; padding: 24px; color: #1A2733; }
  #page { width: 794px; min-height: 1000px; background: #ffffff; border: 1px solid #ccc; position: relative; margin: 0 auto; }
  .header { position: relative; height: 182px; background-color: #14283f;
    background-image: url(${SP_OFERTA_HEADER_BG_B64}); background-size: cover; background-position: center 65%; overflow: hidden; padding: 18px 32px; }
  .header .tint { position: absolute; top:0; left:0; right:0; bottom:0; background-color: rgba(8,22,38,0.62); }
  .header .inner { position: relative; }
  .header .top-row { display: table; width: 100%; }
  .header .eyebrow-cell { display: table-cell; vertical-align: top; }
  .header .pill-cell { display: table-cell; vertical-align: top; width: 1%; white-space: nowrap; text-align: right; }
  .header .eyebrow { color: #fff; font-size: 10.5px; letter-spacing: 1.5px; }
  .header .titlebox { display: inline-block; max-width: 100%; background-color: rgba(10,28,48,0.88); padding: 8px 16px; margin-top: 10px; }
  .header h1 { color: #fff; font-size: 20px; margin: 0; line-height: 1.3; font-weight: bold; }
  .header .subtitle { color: #dce8f5; font-size: 11.5px; margin-top: 7px; }
  .header .client { color: #ffffff; font-size: 11px; margin-top: 3px; font-weight: bold; }
  .header .pill { display: inline-block; background: #fff; color: #173A5C; font-size: 10.5px; font-weight: bold; padding: 8px 16px; border-radius: 14px; white-space: nowrap; }
  .body { padding: 18px 32px 24px; }
  .resultado-box { display: flex; align-items: center; gap: 22px; background: #F5F8FC; border: 1px solid #cfe1f0; border-radius: 6px; padding: 18px 22px; margin-bottom: 16px; }
  .resultado-box .num { font-size: 40px; font-weight: bold; color: #173A5C; line-height: 1; flex-shrink: 0; }
  .resultado-box .txt { font-size: 11px; color: #3C4A5A; line-height: 1.5; }
  .resultado-box .txt strong { color: #173A5C; }
  .box { border: 1px solid #cfe1f0; padding: 10px 18px; margin-bottom: 12px; }
  .box h3 { font-size: 12.5px; margin: 0 0 6px; color: #173A5C; }
  .servicio-row-inf { display: flex; justify-content: space-between; gap: 10px; padding: 6px 0; border-bottom: 1px solid #eef1f5; font-size: 10.8px; }
  .servicio-row-inf:last-of-type { border-bottom: none; }
  .desglose-ahorro-pdf { text-align: center; background: #D1FAE5; color: #065F46; font-weight: bold; font-size: 10.5px; border-radius: 6px; padding: 8px; margin-top: 10px; }
  .tag-inf { font-size: 9.5px; font-weight: bold; padding: 2px 9px; border-radius: 10px; white-space: nowrap; }
  .tag-inf.ok { background: #D1FAE5; color: #065F46; }
  .tag-inf.pend { background: #FEF3C7; color: #92400E; }
  .compromiso-box { background: #F8FAFC; border-left: 3px solid #0F2A4A; padding: 9px 16px; margin-top: 4px; margin-bottom: 12px; }
  .compromiso-box h3 { font-size: 10.5px; font-weight: bold; color: #0F2A4A; margin: 0 0 4px; letter-spacing: 0.03em; }
  .compromiso-box p { font-size: 9.5px; color: #3C3C3C; margin: 0; line-height: 1.55; }
  .compromiso-box p + p { margin-top: 6px; }
  .intro-comercial-pdf { background: #EFF6FF; border: 1px solid #BFDBFE; border-radius: 6px; padding: 10px 16px; margin: 4px 0 14px; }
  .intro-comercial-pdf p { font-size: 10px; color: #1A2733; margin: 0; line-height: 1.6; }
  .cta { text-align: center; font-weight: bold; color: #1D7FB5; font-size: 10.5px; margin-top: 14px; }
  .firma-row { display: flex; align-items: center; gap: 10px; margin-top: 20px; }
  .firma-row img { width: 46px; height: auto; flex-shrink: 0; }
  .firma-info { line-height: 1.4; }
  .firma-info .nombre { font-size: 10.5px; font-weight: bold; color: #173A5C; }
  .firma-info .email { font-size: 9px; color: #5B6B7A; }
  .disclaimer { text-align: center; font-size: 8.5px; font-style: italic; color: #8a97a6; margin-top: 10px; }
  .paquetes-row { display: flex; gap: 10px; margin-bottom: 14px; }
  .paquete-card { flex: 1; position: relative; border: 1px solid #cfe1f0; border-radius: 4px; padding: 16px 14px 14px; text-align: center; background: #fff; }
  .paquete-card.recomendado { border: 1.5px solid #1D4ED8; background: #EFF6FF; }
  .paquete-badge { position: absolute; top: -8px; left: 50%; transform: translateX(-50%); background: #1D4ED8; color: #fff; font-size: 8.3px; font-weight: bold; letter-spacing: 0.03em; padding: 3px 9px; border-radius: 8px; white-space: nowrap; }
  .paquete-card h4 { font-size: 11.5px; color: #173A5C; margin: 4px 0 6px; }
  .paquete-precio { font-size: 15px; font-weight: bold; color: #1D7FB5; }
  .paquete-servicios { font-size: 8.7px; color: #3C4A5A; margin-top: 9px; padding-top: 9px; border-top: 1px solid #E3EAF2; line-height: 1.5; }
  /* Oferta recomendada y detalle de precios por separado, lado a lado
     aprovechando todo el ancho de la página — antes iban uno debajo del
     otro. Si solo hay uno de los dos, ese ocupa la fila entera. */
  .propuesta-precios-row { display: flex; gap: 14px; align-items: stretch; margin-bottom: 14px; }
  .propuesta-precios-row .box { flex: 1; margin-bottom: 0; }
  .print-btn { display:block; width:794px; margin:0 auto 14px; background:#173A5C; color:#fff; border:none; padding:12px; font-size:14.5px; font-weight:bold; cursor:pointer; }
  @media print { .print-btn { display:none !important; } body { background:#fff; padding:0; } #page { border:none; margin:0; } }
</style></head><body>
<button class="print-btn" onclick="window.print()">Descargar / Imprimir PDF</button>
<div id="page">
  <div class="header">
    <div class="tint"></div>
    <div class="inner">
      <div class="top-row">
        <div class="eyebrow-cell"><div class="eyebrow">MOORE MARKET &middot; LEGAL Y CUMPLIMIENTO NORMATIVO</div></div>
        <div class="pill-cell"><div class="pill">INFORME DE AUTODIAGNÓSTICO</div></div>
      </div>
      <div class="titlebox"><h1>Informe de autodiagnóstico normativo</h1></div>
      <div class="subtitle">Resultado de vuestro autodiagn&oacute;stico de cumplimiento</div>
      <div class="client">${esc(respuesta.empresa||'')}</div>
      ${respuesta.contacto ? `<div class="client">A la atenci&oacute;n de: ${esc(respuesta.contacto)}</div>` : ''}
    </div>
  </div>
  <div class="body">
    <div class="resultado-box">
      <div class="num">${ev.porcentaje}%</div>
      <div class="txt">Grado de cumplimiento normativo estimado, a fecha de ${esc(fmtDate(respuesta.fecha))}.<br>${pendientes > 0 ? `<strong>${pendientes} de ${ev.totalAplican} obligaciones sin resolver.</strong>` : '<strong>Todo en regla — enhorabuena.</strong>'}</div>
    </div>
    <div class="box">
      <h3>SITUACIÓN POR ÁREA</h3>
      ${areasHTML}
    </div>
    ${ev.seguridadAlimentaria ? `<div class="compromiso-box"><h3>SEGURIDAD ALIMENTARIA</h3><p>Al manejar alimentos, tambi&eacute;n os aplica la normativa de seguridad alimentaria y APPCC — incluida en el paquete Profesional Plus.</p></div>` : ''}
    ${introComercialHTML}
    ${propuestaPreciosHTML}
    ${compromisoHTML}
    ${autogestionHTML}
    <div class="cta">&iquest;Seguimos adelante? Escribidnos y agendamos juntos los siguientes pasos.</div>
    <div class="firma-row">
      <img src="${SP_OFERTA_LOGO_B64}" alt="Moore Market">
      <div class="firma-info">
        <div class="nombre">Equipo Moore Market</div>
        <div class="email">Legal y Cumplimiento Normativo</div>
      </div>
    </div>
    <div class="disclaimer">Informe orientativo generado autom&aacute;ticamente a partir de las respuestas facilitadas — no sustituye una auditor&iacute;a legal formal.</div>
  </div>
</div>
</body></html>`;

  const w = window.open('', '_blank');
  if (!w) { alert('El navegador ha bloqueado la ventana nueva. Permite las ventanas emergentes para esta página.'); return; }
  w.document.open();
  w.document.write(html);
  w.document.close();
}



/* ═══════════════════════════════════════════════════
   PÁGINA PÚBLICA DE ACEPTACIÓN DE PROPUESTA (?propuesta=<token>)
   Sin login. Lee el resumen que se publicó en "propuestasPublicas/<token>"
   (escrito por el panel interno al generar/guardar la propuesta) y permite
   al cliente aceptarla con un clic. La aceptación NO tramita el pago ni
   formaliza un contrato — solo dice "sí, adelante" y avisa al equipo para
   que proceda con la contratación real. Ver Reglas de Seguridad: este nodo
   necesita lectura Y escritura públicas (igual que auditoriasPublicas),
   porque quien entra aquí no tiene sesión iniciada.
   ═══════════════════════════════════════════════════ */
function renderPropuestaPublicaPage(token) {
  document.title = 'Vuestra propuesta — Moore Market';
  document.documentElement.style.background = '#eef2f6';

  const estilos = `
    * { box-sizing: border-box; }
    body { font-family: Arial, sans-serif; background: #eef2f6; margin: 0; padding: 24px 16px; color: #1A2733; }
    .wrap { max-width: 640px; margin: 0 auto; }
    .logo-row { text-align: center; margin-bottom: 18px; }
    .logo-row img { width: 130px; }
    h1 { font-size: 21px; color: #173A5C; margin: 0 0 6px; text-align: center; }
    .subtitle { font-size: 13px; color: #55647a; text-align: center; margin-bottom: 22px; line-height: 1.5; }
    .card { background: #fff; border: 1px solid #dde3ea; padding: 22px 24px; border-radius: 6px; }
    .servicio-row { display: flex; justify-content: space-between; gap: 10px; padding: 10px 0; border-bottom: 1px solid #eef1f5; font-size: 14px; }
    .servicio-row:last-of-type { border-bottom: none; }
    .total-row { display: flex; justify-content: space-between; gap: 10px; padding: 14px 0 0; margin-top: 6px; border-top: 2px solid #173A5C; font-size: 17px; font-weight: bold; color: #173A5C; }
    .accept-btn { width: 100%; background: #0F7A5C; color: #fff; border: none; padding: 14px; font-size: 15px; font-weight: bold; cursor: pointer; border-radius: 4px; margin-top: 20px; }
    .accept-btn:hover { background: #0b5c46; }
    .accept-btn:disabled { opacity: 0.6; cursor: default; }
    .status { font-size: 12.5px; margin-top: 10px; text-align: center; min-height: 16px; }
    .status.err { color: #b5442c; }
    .disclaimer { text-align: center; font-size: 10.5px; color: #8b98a8; margin-top: 14px; }
    .done-box { background: #fff; border: 1px solid #dde3ea; border-radius: 6px; padding: 40px 24px; text-align: center; }
    .done-box .tick { font-size: 40px; margin-bottom: 10px; }
    .loading-box, .error-box { background: #fff; border: 1px solid #dde3ea; border-radius: 6px; padding: 40px 24px; text-align: center; color: #55647a; font-size: 13.5px; }
  `;
  document.head.insertAdjacentHTML('beforeend', `<style>${estilos}</style>`);

  document.body.innerHTML = `
    <div class="wrap">
      <div class="logo-row"><img src="${SP_OFERTA_LOGO_B64}" alt="Moore Market"></div>
      <h1>Vuestra propuesta de servicios</h1>
      <div id="prop-pub-content" class="loading-box">Cargando vuestra propuesta...</div>
    </div>`;

  (async () => {
    try {
      if (typeof firebase === 'undefined' || !firebase.initializeApp) throw new Error('Firebase no disponible');
      let app;
      try { app = firebase.app('propuestaPublica'); } catch (e) { app = firebase.initializeApp(FIREBASE_CONFIG, 'propuestaPublica'); }
      const snap = await app.database().ref('propuestasPublicas/' + token).once('value');
      const prop = snap.val();
      const cont = document.getElementById('prop-pub-content');
      if (!prop) {
        cont.className = 'error-box';
        cont.textContent = 'No hemos encontrado esta propuesta. Puede que el enlace esté caducado o mal copiado — contactad con nosotros y os lo enviamos de nuevo.';
        return;
      }
      if (prop.aceptada) {
        cont.className = 'done-box';
        cont.innerHTML = `<div class="tick">✅</div><div style="font-size:16px;font-weight:bold;color:#173A5C;margin-bottom:6px;">¡Propuesta ya aceptada!</div><div style="font-size:13px;color:#55647a;">La aceptasteis el ${esc(fmtDate(prop.fechaAceptacion))}. Nuestro equipo se pondrá en contacto para formalizar la contratación.</div>`;
        return;
      }
      const servicios = Array.isArray(prop.servicios) ? prop.servicios : [];
      cont.className = 'card';
      cont.innerHTML = `
        <div class="subtitle" style="text-align:left;margin-bottom:16px;">Propuesta para <strong>${esc(prop.empresa||'')}</strong>${prop.contacto?` · A la atención de ${esc(prop.contacto)}`:''}</div>
        ${servicios.map(s => `<div class="servicio-row"><span>${esc(s.nombre)}</span><span style="font-weight:600;">${s.precio!=null?fmtEUR(s.precio)+(s.iva?' + IVA':''):'A consultar'}</span></div>`).join('')}
        <div class="total-row"><span>Total propuesta</span><span>${fmtEUR(prop.total||0)}${servicios.some(s=>s.iva)?' + IVA':''}</span></div>
        <button class="accept-btn" id="prop-pub-accept-btn" onclick="aceptarPropuestaPublicaSP('${esc(token)}')">✓ Aceptar propuesta</button>
        <div id="prop-pub-status" class="status"></div>
        <div class="disclaimer">Al aceptar, nos ponemos en contacto con vosotros para formalizar la contratación — esto no supone ningún cargo automático.</div>`;
    } catch (err) {
      const cont = document.getElementById('prop-pub-content');
      if (cont) { cont.className = 'error-box'; cont.textContent = 'No se pudo cargar la propuesta. Inténtalo de nuevo en unos minutos.'; }
    }
  })();
}

async function aceptarPropuestaPublicaSP(token) {
  const btn = document.getElementById('prop-pub-accept-btn');
  const status = document.getElementById('prop-pub-status');
  if (btn) { btn.disabled = true; btn.textContent = 'Enviando...'; }
  try {
    let app;
    try { app = firebase.app('propuestaPublica'); } catch (e) { app = firebase.initializeApp(FIREBASE_CONFIG, 'propuestaPublica'); }
    await app.database().ref('propuestasPublicas/' + token).update({
      aceptada: true,
      fechaAceptacion: new Date().toISOString().slice(0,10),
    });
    document.getElementById('prop-pub-content').innerHTML = `
      <div class="tick">✅</div>
      <div style="font-size:16px;font-weight:bold;color:#173A5C;margin-bottom:6px;">¡Gracias por confiar en nosotros!</div>
      <div style="font-size:13px;color:#55647a;">Hemos recibido vuestra aceptación. Nuestro equipo se pondrá en contacto en breve para formalizar la contratación.</div>`;
    document.getElementById('prop-pub-content').className = 'done-box';
  } catch (err) {
    if (btn) { btn.disabled = false; btn.textContent = '✓ Aceptar propuesta'; }
    if (status) { status.className = 'status err'; status.textContent = 'No se pudo enviar. Revisa tu conexión e inténtalo de nuevo.'; }
  }
}
